// Auto-generated from AGP / Aurora custom content + core subclass stubs
window.CUSTOM_SUBCLASSES = [{"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_SOUL_ARMS", "name": "Soul Arms", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Armoury", "lvl": 3, "text": "You may choose up to {{proficiency}} in magical or non-magical weapons and attune to them over a long rest. These don't count against your total three attunement slots, magical or otherwise.\r\n\t\t\tYou can then dismiss the weapon, shunting it into a space formed in your core, and it appears whenever you take your stance thereafter. The weapons appear at your feet if you die, meditate over a different weapon that would replace one, or if you use a long rest to end the attunement. The weapon appears at your feet if it is in your space when the bond breaks.\r\n\t\t\tYou can summon a weapon by taking either stance or as a free action. Ending or switching stances allows you to make the current weapon disappear and conjure  a new one if you take another stance. Your conjured weapons disappear if they are more than 5 feet away from you for 1 minute or more. They also disappear if you dismiss these weapons (no action required), or if you die.\r\n\t\t\tAdditionally, you can use your Intelligence modifier for attack and damage rolls with melded weapons."}, {"name": "Weapon Forms", "lvl": 3, "text": "When you would take a stance with one of your attuned weapons you gain additional abilities called Forms. You may choose a Form to take, dependent on the weapon properties, whenever you would swap to, from, or attack with a weapon. You can only use one Form at a time, unless otherwise stated, even if the weapon you use would have multiple properties."}, {"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "Style Master", "lvl": 7, "text": "Upon reaching 7th level, you master appropriate styles for your melded weapons. You choose an additional fighting style. Whenever you would summon or swap a weapon, you may also change this additional style to another you do not know.\nAdditionally, Whenever you reach a level in this class that grants the Ability Score Improvement feature, you can replace a fighting style you know with another fighting style available."}, {"name": "Barrage", "lvl": 11, "text": "You may spend 1 ki point to make an attack as a bonus action."}, {"name": "Master of Many Forms", "lvl": 15, "text": "If a weapon you would use has multiple properties, you may use one additional Form at a time, for a total of two."}]}, {"id": "ID_RDDT_ARCHETYPE_RETIARIUS", "name": "Retiarius", "parentClass": "Martial Role", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Netcaster", "lvl": 3, "text": "You have specialized training in utilizing nets in and out of combat. Starting at 3rd level when you choose this martial role, given access to sufficient fibrous material, you can repair a damaged net with 1hr of downtime, or create one during a long rest.\r\n\t\t\t\tIn addition, the range for a thrown net for you is 10/30 instead of the normal 5/15, and the base escape DC is 12 instead of 10. You can also add your Strength modifier to attack rolls made with your net, rather than Dexterity, and can attack a creature within melee range without disadvantage."}, {"name": "Ensnaring Fighter", "lvl": 7, "text": "Starting at 7th level, you are particularly adept at combating ensnared opponents. Whenever you restrain a creature within 5ft of you with your net, or start your turn within 5ft of a restrained creature, you can use your bonus action to make a weapon attack against that creature."}, {"name": "Weighted Net", "lvl": 10, "text": "Starting at 10th level, you have learned how to make your nets particularly heavy. Given access to adequate materials and an hour of downtime, you can enlarge and weight a net to make it a more effective weapon. You can now restrain any creature that is Huge or smaller, and the escape DC of your net is increased to 15. In addition, whenever your net hits a creature, it deals 1d6 + {{strength:modifier}} bludgeoning damage to it."}, {"name": "Tripping Toss", "lvl": 15, "text": "Starting at 15th level, whenever a creature within 10ft of you moves at least 1ft, you can use your reaction to toss your net at their feet. The targeted creature then makes a Dexterity saving throw against your Flourish DC, and their speed goes to 0 and they fall prone on a failure. A creature that falls this way becomes restrained by your net.\r\n\t\t\t\tIf they succeed the saving throw, your net remains on the ground where you threw it until you retrieve it. The 5ft square area that your net occupies is considered difficult terrain, and any creature that attempts to cross over it must also make the Dexterity saving throw or fall prone and be restrained."}]}, {"id": "ID_RDDT_ARCHETYPE_DIMACHAERUS", "name": "Dimachaerus", "parentClass": "Martial Role", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Doubly Armed", "lvl": 3, "text": "Starting at 3rd level when you choose this martial role, you are an expert at fighting with a weapon in each hand. You can use two-weapon fighting even when the one-handed weapons you’re wielding aren’t light, as long as they aren't heavy, and you can draw or stow two one-handed weapons when you would normally be able to draw or stow only one."}, {"name": "Dextrous Parries", "lvl": 7, "text": "Starting at 7th level, you gain a +1 bonus to AC so long as you’re wielding a separate melee weapon in each hand. In addition, whenever you are wielding separate melee weapons in each hand and another creature hits you with a melee attack, you can use your reaction to add your proficiency bonus to your AC for that attack, potentially causing the attack to miss you."}, {"name": "Vicious Bladework", "lvl": 10, "text": "Starting at level 10, you are just as deadly with your off-hand attacks as you are with your primary weapon. Whenever you engage in Two-Weapon Fighting, you may add your ability modifier to the damage of the attacks you make using your bonus action."}, {"name": "Whirling Strikes", "lvl": 15, "text": "Starting at 15th level, whenever you use your bonus action to engage in Two-Weapon Fighting, you can make two attacks using your bonus action instead of one. These two attacks must be made with two different melee weapons."}]}, {"id": "ID_RDDT_ARCHETYPE_SECUTOR", "name": "Secutor", "parentClass": "Martial Role", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Heavily Armoured", "lvl": 3, "text": "Starting at level 3 when you choose this martial role, you are adept at fighting in armor. You gain proficiency in heavy armor."}, {"name": "Masterful Shieldwork", "lvl": 7, "text": "Starting at level 7, you have become a very skilled defender with a shield. As long as you are holding a shield, you gain an additional +1 bonus to AC."}, {"name": "Staunch Defense", "lvl": 10, "text": "Starting at level 10, if an effect would cause you to make a Dexterity saving throw, you may choose to make a Strength saving throw instead."}, {"name": "Impassable Defender", "lvl": 15, "text": "Starting at level 15, your defensive capabilities are unmatched and allow you to stop enemies in their tracks. Whenever an enemy moves at least 1ft within 5ft of you, you can use your reaction to make a melee weapon attack against that creature. If your attack hits, the creature’s speed is reduced to 0 until its next turn.\r\n\t\t\t\tIn addition, you gain a +1 bonus to your AC when you are wearing Heavy Armor."}]}, {"id": "ID_RDDT_ARCHETYPE_THRAEX", "name": "Thraex", "parentClass": "Martial Role", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Additional Flourish", "lvl": 3, "text": "When you choose this martial role at 3rd level, your careful examination of your enemies has allowed you to understand them better. You may choose an additional Flourish, ignoring subclass prerequisites. You learn another additional Flourish with the same restrictions at 7th and 15th level. These Flourishes do not count toward your Flourishes Known."}, {"name": "Cunning Adaptability", "lvl": 7, "text": "You have an unmatched ability to adapt to the fight around you. Starting at level 7, you can ignore difficult terrain when you take the Move action during combat. In addition, yif your DM is using the optional flanking rules, cannot be flanked in combat."}, {"name": "Adaptive Expertise", "lvl": 10, "text": "At level 10, you have gained the ability to focus in on those talents that would most benefit you in a given situation. Whenever you complete a long rest, choose one of your skill Proficiencies. Until your next long rest, your Proficiency Bonus is doubled for any ability check you make that uses the chosen Proficiency."}, {"name": "Masterful Bladework", "lvl": 15, "text": "At Level 15, whenever you use a Flourish when you take the Attack action, you can use your bonus action to apply a second flourish to that attack."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_DARK_THRALLS", "name": "Dark Thralls", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Subjugate", "lvl": 3, "text": "As an action, you may mark one ally or one enemy for one minute. Enemies, and unwilling allies, must make a Dexterity saving throw or become marked for the duration. You may mark one ally and one enemy total without spending ki. You can mark additional creatures by spending 1 ki point when you would take the action to do so."}, {"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "Umbral Slide", "lvl": 7, "text": "As part of your movement, you may move up to your movement speed as a shadow on a surface. You may move horizontally or vertically, but if your movement ends on a wall or a ceiling then you fall to the ground. This movement does not provoke opportunity attacks.\r\n\t\t\tIn bright light you move at half speed; in dim light or darkness you gain 10 feet of additional movement as a shadow."}, {"name": "Eclipse", "lvl": 7, "text": "You can spend 1 ki point to use the hide action as a bonus action. If you have a marked ally in your aura you can hide without cover."}, {"name": "Shade Mastery", "lvl": 11, "text": "As an action, you can spend 2 ki points and cause a marked enemy in your aura to make a Wisdom saving throw. On a failure they have their shadow torn into and are dealt 4d6 necrotic damage or half of that on a successful save. This damage can not be resisted and you can only use this ability on the same creature once per day.\r\n\t\t\tAdditionally, you may mark creatures as you attack. You can choose to have these attacks deal no damage."}, {"name": "Swarm", "lvl": 15, "text": "When you would use your Shade Mastery feature, that creature instead takes 4d6 necrotic damage on a failed save per marked creature within your aura."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_IAIJUTSU", "name": "Iaijustsu", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Flash Draw", "lvl": 3, "text": "While assuming either of your stances you may draw and sheathe one weapon as part of any and every attack you make. This weapon must deal slashing damage, and cannot have the heavy property. Enemies can also provoke opportunity attacks from you even if you haven't drawn this weapon."}, {"name": "Iai Dice", "lvl": 3, "text": "Your Iai Dice are {{iai:die:count}}d{{iai:dice}}"}, {"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "Iai-Goshi", "lvl": 7, "text": "Twice per short rest you may, as an action, make a single melee attack roll against every enemy within your reach."}, {"name": "Tachi-Ai", "lvl": 11, "text": "While in internal stance, enemies provoke opportunity attacks when they would leave any square in your reach.\r\n\t\t\tAdditionally, you add your Iai die to your weapon damage rolls for attacks made as reactions, and while in external stance you would instead add your Iai die twice."}, {"name": "Kennokabe", "lvl": 15, "text": "You may spend 1 ki point to gain and take a reaction anytime one would be triggered. You may do this {{intelligence:modifier}} times per long rest.\r\n\t\t\tAdditionally, when you are about to take damage from a spell, melee, or ranged attack roll, you may make a weapon attack as a reaction. If you are in external stance, this attack is always made at disadvantage. If you roll higher than the attack roll you may roll your weapon damage adding your Iai dice, and subtract that from the damage you would take. If the damage is negated, you can redirect the attack back to its source, forcing your attacker to target itself with its attack using your attack roll."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_KI_CASTER", "name": "Ki Caster", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Aura Cast", "lvl": 3, "text": "As a part of each of your attacks, you may summon an arrow or bolt to attack with. This ammunition is magical for the purposes of overcoming resistances and deals 2d{{auracast:die}} force damage. This ammunition requires a ranged 2-handed weapon to shoot. It dematerialises upon hitting or missing a target, and making one when another exists causes the older one to disappear, unless stated otherwise.\r\n\t\t\tAdditionally, when you ready an attack, the ammunition does an extra 1d10 damage. It is lost if it is not shot by the end of your next turn, and the extra damage is wasted."}, {"name": "Constructs", "lvl": 3, "text": "When you make a ranged attack roll against an enemy using your aura cast feature, you may infuse your attack with additional spiritual energy. You gain additional abilities called Constructs, which may be applied to ranged attacks.\r\n\t\t\tOnce a turn, when you make a ranged attack roll against an enemy, you may spend up to {{construct:amount}} ki point to infuse the attack with up to {{construct:amount}} constructs."}, {"name": "Point-Blank Shot", "lvl": 7, "text": "Once per short rest, as an action, you may make a ranged attack roll with a range of 5 feet. On a hit, the attack is considered a critical hit. This critical does not double the damage from Constructs."}, {"name": "Sharp Shooting", "lvl": 11, "text": "Whenever you would roll damage for a summoned arrow, you may add {{intelligence:modifier}} to that roll. If you do so while attacking without using a construct, you regain 1 ki point on a d20 roll of 10 or higher. This additional damage is doubled on a critical hit."}, {"name": "Suppressing Fire", "lvl": 15, "text": "As a reaction, when an enemy within your weapon's first range casts a spell, you may make a ranged attack roll against them. This attack cannot be made at advantage. If the attack hits, you do no damage, but the enemy must make a concentration save as if it were concentrating on a spell with a DC equal to your cultivator save DC. On a fail, the spell fails, and the slot is wasted."}]}, {"id": "ID_RDDT_ARCHETYPE_ORDER_OF_THE_PAWN", "name": "Order of the Pawn", "parentClass": "Esoteric Order", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Strength in Numbers", "lvl": 3, "text": "Starting when you choose this order at 3rd level, you gain an upper hand when fighting alongside your allies. You gain advantage on attack rolls against a creature if at least one of your allies is within 5 feet of the creature and not incapacitated."}, {"name": "Additional Arts", "lvl": 3, "text": "At 3rd level, you learn 2 additional arcane arts of your choice. You learn 1 more at 7th level, then again at 10th, and 15th level."}, {"name": "En Passant", "lvl": 7, "text": "Starting at 7th level, whenever you hit a creature with an opportunity attack, you can attack twice, rather than only once."}, {"name": "Additional Fighting Style", "lvl": 10, "text": "At 10th level, you learn one fighting style option of your choice from the Fighter class."}, {"name": "Fighting Edge", "lvl": 15, "text": "At 15th level, whenever you take the Attack action and have advantage on one of those attacks, you can make one additional attack as a bonus action."}, {"name": "Proud Promotion", "lvl": 18, "text": "Starting at 18th level, you learn 2 additional arcane arts of your choice. When choosing these arcane arts, you can ignore all prerequisites, including order requirements."}]}, {"id": "ID_RDDT_ARCHETYPE_ORDER_OF_THE_QUEEN", "name": "Order of the Queen", "parentClass": "Esoteric Order", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Spellbound Sidearm", "lvl": 3, "text": "Starting when you choose this order at 3rd level, you can assign a second spellbound blade, gaining the same benefits as your first. You may recall or dismiss both spellbound blades as the same bonus action. All the rules for two-weapon fighting apply as normal."}, {"name": "Crown Privilege", "lvl": 3, "text": "At 3rd level, when you take the Attack action on your turn, you can spend 1 mana point to gain advantage on attack rolls until the end of that turn."}, {"name": "Arcane Agility", "lvl": 7, "text": "Your speed increases by 10 feet while you aren’t wearing heavy armor. Additionally, you gain a +{{intelligence:modifier}} to your initiative"}, {"name": "Empowered Initiative", "lvl": 10, "text": "Starting at 10th level, you can give yourself an edge when a battle begins. At the start of your first turn of each combat, your walking speed increases by 10 feet, which lasts until the end of that turn. If you take the Attack action on that turn, you deal an additional 2d6 force damage on the first attack."}, {"name": "Moving Target", "lvl": 15, "text": "At 15th level, you gain the ability to pass between the planes in a blink of an eye. When you use the Attack action, you can teleport up to 10 feet before the first attack to an unoccupied space you can see. If you use this feature, the next attack made against you has disadvantage."}, {"name": "Killer Queen", "lvl": 18, "text": "Starting at 18th level, your time on the battlefield has heightened your natural abilities. Your weapon attacks score a critical hit on a roll of 19 or 20. Additionally, when you move on your turn in combat, you can spend 2 mana points to double your speed until the end of the turn."}]}, {"id": "ID_RDDT_ARCHETYPE_ORDER_OF_THE_ROOK", "name": "Order of the Rook", "parentClass": "Esoteric Order", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Bonus Proficiency", "lvl": 3, "text": "When you choose this order at 3rd level, you gain proficiency in heavy armor."}, {"name": "Spellbound Shell", "lvl": 3, "text": "Starting when you choose this order at 3rd level, you can imbue a set of armor with magical qualities similar to that of your spellbound blade. You may recall or dismiss both your spellbound blade and your spellbound shell as the same bonus action."}, {"name": "Titan's Vim", "lvl": 3, "text": "At 3rd level, when you are hit by an attack while you are wearing your spellbound shell, you can use your reaction and spend 1 mana point to gain a bonus +{{intelligence:modifier}} AC until the start of your next turn, possibly causing the attack to miss."}, {"name": "Magical Might", "lvl": 7, "text": "Starting at 7th level, you have advantage on Strength and Constitution saving throws while wearing your spellbound shell."}, {"name": "Arcane Armour", "lvl": 10, "text": "Starting at 10th level, you can summon a powerful outer layer to strengthen your armor. As a bonus action you create this armor, which appears as a spectral layer above your spellbound shell. You gain {{arcanearmour:hp}} temporary hit points equal, and a bonus {{intelligence:modifier}} to your AC. For every 5 damage done to this armor, your AC decreases by 1, until both are reduced to 0. You can use this ability twice, and you regain all uses of it after a long rest."}, {"name": "Hardened Shell", "lvl": 15, "text": "At 15th level, your spellbound shell makes you more difficult to kill. Whenever you take damage, other than psychic damage, you can reduce it by 2."}, {"name": "Castle's Strength", "lvl": 17, "text": "Starting at 18th level, you gain the ability to bolster your spellbound shell. On your turn, you can spend 2 mana points as a bonus action to reinforce your spellbound shell with arcane energy. While reinforced, you have resistance to all damage except psychic damage. This effect lasts for 1 minute. It ends early if you are knocked unconscious."}]}, {"id": "ID_RDDT_ARCHETYPE_ORDER_OF_THE_KNIGHT", "name": "Order of the Knight", "parentClass": "Esoteric Order", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Spellbound Shield", "lvl": 3, "text": "Starting when you choose this order at 3rd level, you can imbue a shield with magical qualities similar to that of your spellbound blade. You may recall or dismiss both your spellbound blade and your spellbound shield as the same bonus action."}, {"name": "Knight's Parry", "lvl": 3, "text": "At 3rd level, when a creature within 5 feet of you hits you with a melee attack while you are wielding your spellbound shield, you can use your reaction and spend 1 mana point to attempt a parry. When you do so, the damage you take from the attack is reduced by 1d10 + {{level:arcane armsman}}. If you reduce the damage below 0, the attacking creature takes damage of the same type equal to the difference."}, {"name": "Heroic Defense", "lvl": 7, "text": "Starting at 7th level, when a creature hits you with an attack while you’re wielding your spellbound shield, you gain a +2 bonus to AC against all subsequent attacks made by that creature for the rest of the turn."}, {"name": "Retaliatory Shield", "lvl": 10, "text": "Starting at 10th level, you can project a magical buffer onto your spellbound shield. As a bonus action, you conjure this barrier, which lasts for 10 minutes. Once per turn when a creature within 5 feet of you hits you with a melee attack, the barrier bursts back, dealing {{intelligence:modifier}} force damage. You can use this ability twice, and you regain all uses of it after a long rest."}, {"name": "Invigorating Counter", "lvl": 15, "text": "At 15th level, when a creature misses you with a spell attack or you succeed on a spell’s saving throw, you can use your reaction to absorb some of the spell’s power. You gain a bonus to damage rolls made with your spellbound blade equal to the level of the spell cast (minimum of 1) until the end of your next turn."}, {"name": "Runic Redirection", "lvl": 17, "text": "Starting at 18th level, whenever a creature within 60 feet of you casts a spell or makes an attack that would affect you, you can use your reaction and spend 2 mana points in an attempt to deflect it with your spellbound shield. The creature must make an Intelligence saving throw against your arcane art save DC. On a failed save, you can redirect the attack or spell to another location within its range."}]}, {"id": "ID_RDDT_ARCHETYPE_ORDER_OF_THE_BISHOP", "name": "Order of the Bishop", "parentClass": "Esoteric Order", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Arcane Adept", "lvl": 3, "text": "Starting when you choose this order at 3rd level, when you attack with your spellbound blade, you can use your Intelligence modifier, instead of Strength or Dexterity modifier, for the attack and damage rolls. Additionally, your mana pool increases by {{intelligence:modifier}}."}, {"name": "Diverse Arsenal", "lvl": 3, "text": "At 3rd level, you can learn two cantrips and two first level spells from the wizard spell list. You can cast these spells by spending 1 mana point per spell level. You learn two additional spells at 5th, 9th, 13th, and 17th level. The level of the spells you can learn is {{bishop:level}}, which is also the maximum level you can cast your spells at. You can use your spellbound blade as a focus for casting these spells."}, {"name": "Protective Boundary", "lvl": 7, "text": "Starting at 7th level, you project a magical aura that shields your allies from arcane attacks. You and friendly creatures within 10 feet of you have resistance to damage from spells. Additionally, when you use your Arcane Exchange feature to heal, you can target one additional creature within 10 feet of you to regain the same amount of health."}, {"name": "Empowering Aid", "lvl": 10, "text": "Starting at 10th level, you can spend 1 mana point to empower one of your allies. As a bonus action, you can choose a willing creature within 10 feet of you. Once within the next 10 minutes, that creature can use an arcane art of your choice, using your level and mana ability. Once the creature uses the arcane art, it loses this benefit. A creature can only possess one of your arcane arts at a time."}, {"name": "Astral Conduit", "lvl": 15, "text": "At 15th level, you learn to channel your magic through the weave itself. When you cast a spell with the range of touch or take the Attack action and use an arcane art, you can spend a bonus action to target a creature up to 60 feet away. If you attack in this way, your weapon does not deal any damage, you only deal the arcane art’s damage."}, {"name": "Mystic Medium", "lvl": 17, "text": "At 18th level, whenever you score a critical hit or reduce a creature to 0 hit points with an arcane art or spell, you regain 1 mana point. Additionally, you learn one 6th level spell from the wizard spell list."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_FALLING_PHOENIX", "name": "Falling Phoenix", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Conjured Phoenix", "lvl": 3, "text": "You gain the cantrip Create Bonfire, and add {{phoenix:cantrip}} to the damage dealt by it."}, {"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "Phoenix Fall", "lvl": 7, "text": "You may cast Burning Hands using 2 ki points. Additionally, whenever you cast Create Bonfire, you may make an attack as a bonus action."}, {"name": "Phoenix's Vestment", "lvl": 11, "text": "Whenever you are in your internal stance you instead gain immunity to fire damage. Additionally, your abilities ignore fire resistance, and treat fire immunity as fire resistance."}, {"name": "Winged Wildfire", "lvl": 11, "text": "While in your external stance you gain fiery wings and a fly speed of 60 feet. While in internal stance you may spend 1 ki point to cast Feather Fall."}, {"name": "Phoenix Arisen", "lvl": 15, "text": "When an attack would reduce you to 0 hit points, you may instead fall out of your current stance and be reduced to 1 hit point and 0 ki remaining. The attacker takes 2d{{arisen:die}} + 1d{{arisen:die}} fire damage per ki point you had left before you were reduced to 0."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_KI_FORTRESS", "name": "Ki Fortress", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Ki Shields", "lvl": 3, "text": "Shields are now a d6 light versatile (d8) bludgeoning weapon for you. You may don a shield with the same Use an object action you use to draw it. Magic shields that have bonuses to AC also apply the same bonuses to any attack and damage rolls you make with those shields. You gain the ability to cast spells, using your shield as a spellcasting focus. You now know the cantrips Blade Ward and True Strike, and you may target {{proficiency}} creatures within your aura whenever you cast them. \r\n\t\t\tYou may spend 1 ki point and cast the 1st level spells from the list below using Intelligence as your spellcasting modifier. You may cast any spell from the list as a bonus action."}, {"name": "Shield Legerdemain", "lvl": 3, "text": "You may spent a ki point to cast Shield on an ally as a reaction when they are within your aura and are about to be hit by an attack."}, {"name": "Force Shields", "lvl": 7, "text": "You may make a thrown weapon attack with an energy version of your shield, with a range of 15/30 using Strength for attack and damage rolls. It deals 1d6 force damage and additional damage equal to any magic AC bonuses imparted by the shield. The shield shatters on impact."}, {"name": "Last Bastion", "lvl": 11, "text": "As long as you have 1 ki point remaining, you may use a bonus action to brace yourself. Until the end of your next turn, your movement speed becomes 0, you act as three-quarters cover for creatures medium size or smaller in a 15 foot cone behind you, and you gain a +2 to your AC and saving throws."}, {"name": "Destructive Shielding", "lvl": 15, "text": "When you hit an enemy with an attack using a shield, you may use up to 3 ki points to do an extra 1d8 damage, plus 1d8 per ki point used after the 1st. Additionally, when you land a critical hit on an enemy, you may make a single extra attack as part of that attack action."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_FULMINIS_SOUL", "name": "Fulminis Soul", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Lightning Strikes", "lvl": 3, "text": "When you successfully hit an enemy, and your previous attack was successful, you gain a spark. You can have a maximum of {{proficiency}} sparks, losing all sparks gained beyond this number. You lose all sparks when you spend a minute without gaining or losing any sparks.\r\n\t\t\tWhen an ability requires you to spend ki points, you may instead spend a spark instead of 1 ki point. If an ability’s ki cost exceeds the number of sparks, you must pay the remaining value in ki. Additionally, you may use your ki points or sparks for the following abilities:\r\n\t\t\tOnce per turn, you may spend 1 ki point and 10 feet of your movement to teleport 10 feet without using an action.\r\n\t\t\tYou may spend 1 ki point to increase your attack range by 5 feet until the end of your next turn, to a maximum of 10 feet."}, {"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "Conductive", "lvl": 7, "text": "Once per turn, while in internal stance, when you land a consecutive hit and have already gained sparks this turn, you gain 2 sparks instead of one.\r\n\t\t\tAdditionally, when you gain a spark, you may immediately spend it to deal 1d4 lightning damage, heal 1d4 hit points, and gain an extra 5 feet of movement until the start of your next turn. This movement gain can stack."}, {"name": "Fulminant", "lvl": 11, "text": "While in external stance you may make an attack as a bonus action, and when you spend ki or sparks to teleport, you may deal 2d4 lightning damage as part of that teleport to enemies within 10 feet of your destination."}, {"name": "Return Stroke", "lvl": 15, "text": "When you start your turn in external stance, with 4 or more sparks, you may spend 2 sparks to make an additional attack as part of the attack action. You may continue to pay and attack within the same turn, as long as you have 2 or more sparks."}]}, {"id": "ID_RDDT_ARCHETYPE_CULTIVATOR_FOUR_WINDS", "name": "Four Winds", "parentClass": "Cultivator Technique", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Stances", "lvl": 3, "text": "You can choose the external or internal stance before you roll for initiative, unless surprised. Otherwise, entering or switching between stances is a bonus action. You are unable to use stances while you are incapacitated."}, {"name": "North Wind", "lvl": 7, "text": "As a reaction, whenever an enemy ends their turn, you may take an extra turn. During this turn, your movement does not provoke attacks of opportunity, and your movement speed is doubled. \r\n\t\t\tAdditionally, a warding breeze guards you, blowing away any mist or gases such as Stinking Cloud or Fog Cloud."}, {"name": "South Wind", "lvl": 11, "text": "You gain a fly and hover speed equal to your movement speed when in internal stance."}, {"name": "East Winds", "lvl": 15, "text": "You may spend 5 ki points to cast Whirlwind. You may spend an additional 2 ki points to become immune to the effects of the spell."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_SOULKNIFE", "name": "Way of the Soulknife", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Never caught unarmed, the soulknife is the literal embodiment of using the power of the mind as a weapon. These psychic warriors do battle using both their physical body and the mind blade, a telekenetic filed honed by the wielder's focus into a razor's edge. While the soulknife may not appear to be a traditional monk, the path that these psionically-gifted individuals take is so similar as to be identical, whetehr their powers are called \"psi\" or \"ki\". A soulknife meditates and develops both th", "features": [{"name": "Mind Blade", "lvl": 3, "text": "At 3rd level, your study and meditation is rewarded in the forming of your mind blade, a semi-solid weapon of psychic energy powered by your will. You can manifest your mind blade as a bonus action or reaction to rolling initiative and dismiss it at will. The mind blade has the form of a one handed weapon of your choice. It has a 5ft reach, deals 1d8 + {{mindblade:damage}} psychic damage at a +{{mindblade:attack}} vs AC, and has the finesse, light and thrown (20/60) properties and counts as a monk weapon you are proficient with. You cannot be disarmed of your mind blade, but if you stop wielding it or are incapacitated, you mind blade dissipates. When thrown you mind blade returns after the attack either hits or misses. If you are effected by an anti-magic effect you must make a DC15 wisdom saving throw to maintain or manifest your mind blade. When you use flurry of blows you can make one of the attacks with your mind blade."}, {"name": "Wild Talent", "lvl": 3, "text": "At 3rd level you manifest minor psionic gifts. You learn the message and mage hand cantrips and do not need any components for them. In addition you can spend 1 ki point to cast identify or 2 to cast detect thoughts. Wisdom is your spellcasting modifier and you do not need to offer any form of components."}, {"name": "Psychic Strike", "lvl": 7, "text": "At 16th level your combat trance allows you to maintain a mental reserve of power - your psionic focus - which is recovered any time you roll initiative. At the start of your turn you can recover your psionic focus by reducing your speed to 0 for that turn or spending a ki point as a bonus action. When damage from your mind blade reduces a creature with intelligence of 6 or higher to 0 hit points you can use your reaction to regain your psionic focus and gain temporary hit points equal to half the damage dealt.\r\n\t\t\tBLADE SKILLS:\r\n\t\t\tWhen you strike a creature with your mind blade you can expend your psionic focus to perform one of the following:\r\n\t\t\tBladewind. Your mind blade shatters into flying shards of psychic energy. Immediately make one additional mind blade attack against another creature within 30ft of you, after which your mind blade dissipates.\r\n\t\t\tNeuroptic Blast. At the start of its next turn, the target must make a constitution saving throw against your ki save DC or be blinded until the end of its turn.\r\n\t\t\tSynaptic Overload. The target is unable to take the Dash, Disengage, or Dodge actions on its next turn."}, {"name": "Imbued Blade", "lvl": 11, "text": "At 11th level you can manifest your mind blade as if you were drawing a weapon reducing the time taken to negligable. As a bonus action you can expend your psionic focus and up to 3 ki points to enhance your mind blade as if concentrating on a spell. Your mind blade gains a magical bonus to attack and damage rolls equal to the expended ki for 10 minutes or until you loose concentration. While concentrating you have advantage on saving throws to maintain or manifest your mind blade."}, {"name": "Knife to the Soul", "lvl": 17, "text": "At 17th level you can force your mind blade to make an incorporeal strike. When you take the attack action, you can expend your psionic focus. Each time this turn that you would make an attack with your mind blade, you can force the target to make a DC{{soul:dc}} dexterity saving throw. On a failure the target takes 1d8 + {{soul:damage}}. This ignores resistance to psychic damage and immunities are treated like resistances."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_BEYOND", "name": "Way of the Beyond", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Unnatural Passage", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, you can use your ki to pass through solid objects with ease. Whenever you use your Step of the Wind, you can spend an additional 1 ki point to gain the ability to pass through solid objects as though they were difficult terrain. If you end your turn inside of an object, you 4d6 force damage and are shunted to the last unoccupied space you were in. This effect lasts until the end of your turn.\r\n\t\t\tAt 6th level, you can use this feature by spending 1 ki point without using your Step of the Wind."}, {"name": "Unnatural Defense", "lvl": 3, "text": "At 3rd level, your training in the mysterious ways of the Beyond has lead you to an equally mysterious method of defense. Whenever you use your Patient Defense, you can spend an additional 1 ki point to gain immunity to one of the following conditions of your choice until the start of your next turn: blinded, charmed, deafened, frightened, grappled, paralyzed, poisoned, prone, restrained, or stunned. You cannot choose a condition that is currently affecting you."}, {"name": "Disrupt Timing", "lvl": 6, "text": "Starting at 6th level, you can quicken your recovery of certain effects. If you are affected by a condition for which you would make a saving throw at the end of your turn, such as with the hold person spell, you can attempt to end it early. As a reaction, you can spend 1 ki point and make the saving throw at the beginning of your turn instead.\r\n\t\t\tYou can use this reaction even if you would normally be incapable of doing so."}, {"name": "Harvest Ki", "lvl": 11, "text": "Starting at 11th level, your able to draw strength directly from your enemies to regain ki. As an action, you can regain 2 ki points as you reach into the soul of a creature within 5 feet of you that you can see. The creature takes psychic damage equal to two rolls of your Martial Arts die.\r\n\t\t\tThis damage increases to three rolls of your Martial Arts die at 17th level."}, {"name": "Ethereal Contact", "lvl": 17, "text": "At 17th level, you become able to partially split your body between the Ethereal Plane and the plane you're on. As a bonus action, you can spend 3 ki points to gain truesight out to a range of 60 feet for 1 minute.\r\n\t\t\tAdditionally, you can touch and attack a creature in the Ethereal Plane that you can see with your hand or any weapon you're holding. Whenever you reach into the Ethereal Plane in this way, your arm and weapon vanish from your plane as it fades into the Ethereal Plane."}, {"name": "Soul Sever", "lvl": 17, "text": "At 17th level, you're able to temporarily disconnect the soul of a creature from the planes. Whenever you hit a creature with both of the attacks granted by your Flurry of Blows, you can attempt to sever their soul from their body. The target must succeed on a Charisma saving throw to avoid the effect. On a failed save, the target's soul leaves their body, and is pushed outside the planes until the end of your next turn. While their soul is separated from their body, the target is vulnerable to all damage that it isn't already immune to.\r\n\t\t\tA creature that has had its soul severed by this feature has advantage against it for the next 24 hours. This feature has no effect on undead or constructs.\r\n\t\t\tOnce you use this feature, you can't use it again until you finish a long rest, unless you spend 5 ki points to use it again."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_ORDERLY_CREATION", "name": "Way of Orderly Creation", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the way of Orderly Creation study the very nature by which all things come into existence. This is often done by slowly separating things into their respective base components. Monks of Orderly Creation use their ki to both create and destroy.", "features": [{"name": "Law of Corporeality", "lvl": 3, "text": "Starting at 3rd level, you begin to learn the many aspects of corporeality, each of which can be accessed with ki points.\r\n\t\t\tAspects. you learn two aspects at 3rd level and a further three at 11th level. Some aspects are defensive benefits some are for offensive means. To apply an aspect to an attack it must be stated before the attack roll."}, {"name": "Law of Animation", "lvl": 6, "text": "At 6th level you learn two acts:\r\n\t\t\tAct of Flow: When you meditate for five minutes or longer, your senses begin to align, you can add {{wisdom:modifier}} to investigation checks made within 300 feet of where you meditated.\r\n\t\t\tAct of Will: While touching a creature you can detect whether they are possessed, charmed or frightened."}, {"name": "Laws of Sentience and Autonomy", "lvl": 11, "text": "At 11th level you can choose 3 more Aspects of Corporeality, additional there are two more to choose from: Aspect of Autonomy and Aspect of Sentience."}, {"name": "Law of Uncreation", "lvl": 17, "text": "Starting at 17th level you touch has the power to return creation to its more base components. As an action you can spend 5 ki points to force a creature you can touch to make a constitution saving throw. On a failed throw they take 10d10 force damage or half as much on a successful one. If this reduces a target to 0 hit points they are reduced to ash, everything non magical on their persons is reduced to ash. You can disable aspects to increase the damage, for each aspect disabled it increases the damage by 5d10. You cna disable up to 3 aspects. A disabled aspect cannot be used for the next 48 hours. When you disable an aspect there is a 50% chance of suffering a drawback. Roll a d20, if the value is greater than 10 nothing happens, if it is 10 or less you suffer a drawback listed on the table."}]}, {"id": "ID_WIKI_ARCHETYPE_WAY_OF_RESOLVE", "name": "Way of Resolve", "parentClass": "Monk", "source": "D&D Wiki", "summary": "Monks of the way of Resolve are beings of brute-force, treating every fight as if it may be their last.", "features": [{"name": "Unyielding Grit", "lvl": 3, "text": "If you are below half of your max hp you can use your bonus action to focus and regain {{Grit:hp}} hp. You may use this ability once per short rest."}, {"name": "Enforcer", "lvl": 3, "text": "Improvised weapons are now considered monk weapons for you. Additionally you can spend one ki point to gain advantage on a strength related check."}, {"name": "Muscle-Based Protection", "lvl": 3, "text": "You add {{strength:modifier}} to your armour class"}, {"name": "One-Two Combo", "lvl": 6, "text": "At level 6 if the first attack in your flurry of blows succeeds you can choose to add one of the following effects to the second:\r\n\t\t\tYou gain {{wisdom:modifier}} to hit and {{strength:modifier}} to damage\r\n\t\t\tAt 11th level you can choose to grapple with your second attack and gain {{wisdom:modifier}} as a bonus to the grapple check"}, {"name": "Limitless Stamina", "lvl": 11, "text": "When you use Unyielding Grit you gain resistance to non-magical Slashing,Piercing and Bludgeoning damage for the next half an hour"}, {"name": "Deadly Fortitude", "lvl": 17, "text": "When you hit 0 hit points you automatically use Deadly Fortitude. Whilst a 0 hit points you are still conscious, you can take your turn as normal. At the start of your turn you still make all the death saving throws, for each one you fail you gain two levels of exhaustion (until you fail 3 where you die from failure and from exhaustion) Any damage you take in this state is tallied to the side. If this exceeds your maximum hit points you die instantly, any healing spells take damage away from this tally first and then add hit points to your total."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_THUNDERING_SKY", "name": "Way of the Thundering Sky", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Drums of War", "lvl": 3, "text": "You gain proficiency with the drum. If you already have this proficiency, you gain proficiency with one other type of musical instrument of your choice."}, {"name": "Flash and Thunder", "lvl": 3, "text": "At 3rd level, you learn the following Thundering Sky Techniques:\r\n\t\t\tLightning Reflexes. When you make an attack of opportunity, you can spend 1 ki point to make an additional attack.\r\n\t\t\tThundering Palm. Immediately after you take the Attack action on your turn, you can spend 2 ki points to cast the thunderwave spell as a bonus action. You can choose to center the spell on yourself, and you cannot damage yourself with this spell.\r\n\t\t\tYou can spend additional ki points to cast thunderwave as a higher level spell. Each additional ki point you spend increases the spell's level by 1. The maximum number of ki points (2 plus any additional points) that you can spend on the spell equals {{level:monk:half}}."}, {"name": "Gathering Storm", "lvl": 3, "text": "When you choose this tradition at 3rd level, your skin begins to ripple with lightning which can be used to aid you in combat. Whenever you hit a creature with two consecutive attacks as part of the same action (such as the Attack action), bonus action (such as Flurry of Blows), or reaction (such as making an attack of opportunity using Lightning Reflexes), you gain a static charge. While you have at least 1 static charge, you can change the damage type of your melee weapon attacks to lightning. You can also spend static charges to fuel your Thundering Sky Techniques as if they were ki points. All of your static charges dissipate after 1 minute has passed without gaining a new one. You can have a maximum {{wisdom:modifier}} static charges"}, {"name": "Bringer of Storms", "lvl": 6, "text": "At 6th level, you learn the following Thundering Sky Techniques:\r\n\t\t\tPierce the Clouds.  If there are clouds, you can spend 1 minute in meditation to cause them to split open and begin to rain. Rain does not obscure your vision. While in rain, you can see as if it were day.\r\n\t\t\tStep through Thunder. You can spend 3 ki points to cast the thunder step spell as an action.\r\n\t\t\tRide the Lightning. You can blast a distant target with a bolt of lightning infused ki energy in place of a normal attack. Make a special ranged attack targeting a creature within 30 feet. On a hit, the creature takes lightning damage equal to 1d{{martial arts:dice}} + {{wisdom:modifier}} and you can spend 1 ki point to ride the lightning. If you do so, you teleport to an unoccupied space within 5 feet of the target as part of the attack. You can use this technique only once per turn."}, {"name": "One with the Storm", "lvl": 11, "text": "When you reach 11th level, your soul becomes one with the raging tempest. You gain resistance to lightning and thunder damage and learn the following Thundering Sky Techniques:\r\n\t\t\tFulminating Strike. When you hit a creature with an unarmed strike, you can spend 3 ki points to send a creature flying with a violent storm-charged strike. The target takes 3d{{martial arts:dice}} extra thunder damage, and must succeed on a Strength saving throw or be pushed to the end of a 20 foot long, 5 foot wide line and fall prone. Each creature or object in the line takes 2d6 bludgeoning damage.\r\n\t\t\tWind Running. Whenever you use your Step of the Wind, you gain a {{speed}}ft flying speed until the end of your turn. If you use Step of the Wind while outdoors in a thunderstorm, the flying speed is maintained until the end of your following turn."}, {"name": "One with the Storm", "lvl": 17, "text": "When you reach 11th level, your soul becomes one with the raging tempest. You gain resistance to lightning and thunder damage and learn the following Thundering Sky Techniques:\r\n\t\t\tFulminating Strike. When you hit a creature with an unarmed strike, you can spend 3 ki points to send a creature flying with a violent storm-charged strike. The target takes 3d{{martial arts:dice}} extra thunder damage, and must succeed on a Strength saving throw or be pushed to the end of a 20 foot long, 5 foot wide line and fall prone. Each creature or object in the line takes 2d6 bludgeoning damage.\r\n\t\t\tWind Running. Whenever you use your Step of the Wind, you gain a {{speed}}ft flying speed until the end of your turn. If you use Step of the Wind while outdoors in a thunderstorm, the flying speed is maintained until the end of your following turn."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_BROKEN_HOURGLASS", "name": "Way of the Broken Hourglass", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Temporal Restoration", "lvl": 3, "text": "Starting when you take this monastic tradition at 3rd level, you can call upon temporal imprints to return an object to a former state. You learn the mending cantrip, and you can restore damage of any kind when you cast the spell (including damage from old age, such as spoilage or rust), as long as the damage occurred no more than 10 days ago."}, {"name": "Crack the Hourglass", "lvl": 3, "text": "Also at 3rd level, you can spend 1 ki point as a bonus action to cause a ripple in the flow of time, moving at incredible speed while time around you appears to slow to a crawl. Until the end of your turn, other creatures cannot take reactions in response to your actions or movement, and you can take three additional actions on this turn. These additional actions can only be used to take the Attack (One unarmed strike only), Dash, Hide, or Use an Object actions.\n\t\t\t\rContinually pushing against the flow of time is strenuous, and as such you must make a DC{{hourglass:dc}} Constitution saving throw or gain one level of exhaustion. Additionally once you use this ability, you gain one level of exhaustion each time you use it again before {{hourglass:time}} minute has passed."}, {"name": "Deja-Vu", "lvl": 6, "text": "At 6th level, you have learned to invoke violent echoes of the past to harm your foes in the present. Once per turn when you take the Attack action, you can spend a ki point to replace one of the attacks to cause a creature you can see within 30 feet of you to reexperience harm it has suffered before. The creature must make a Wisdom saving throw against your ki save DC. On a failed save, the target takes force damage equal to two rolls of your martial arts die and falls prone. On a successful save, it takes half as much damage and doesn't fall prone."}, {"name": "Shatter the Hourglass", "lvl": 11, "text": "By 11th level, your ability to manipulate time has improved enough to stop time almost completely. When you use Crack the Hourglass, you also have advantage on attack rolls until the end of your turn, and your attacks deal additional damage equal to two rolls of your martial arts die on a hit. A creature can take this additional damage only once during the duration of this ability.\r\n\t\t\tIn addition, you have become accustomed to the strain of slowing time. Whenever you finish a short rest, your exhaustion level, if any, is decreased by 1."}, {"name": "Chronal Stasis", "lvl": 17, "text": "When you reach 17th level, you have gained the ability to sever a creature's connection to time, trapping it in temporal stasis. When you hit a creature with an unarmed strike, you can spend 5 ki points to cause the creature to become petrified. While petrified in this way, the creature doesn't fall and can't be moved in any way. At the end of each of its turns, a petrified creature can make a Charisma saving throw against your ki save DC, ending the effect on a success. If a creature fails this saving throw three times before the effect ends, it becomes permanently trapped in stasis and can no longer make saving throws to end the effect. A creature can use the greater restoration spell to end this effect.\r\n\t\t\tOnce you use this ability, you gain 1d6 levels of exhaustion each time you use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_CHRONAL_FLOW", "name": "Way of Chronal Flow", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the Way of Chronal Flow focus their ki to slightly bend time to their whims. Their training allows them to create slight changes in the flow of time and harness this natural force. Peering into the the near future, they confuse foes with unpredictable moves, and are adept at evading and striking in unexpected ways.", "features": [{"name": "Prescient Sight", "lvl": 3, "text": "When you choose this tradition at 3rd level, you have begun to peer into the future and anticipate your foes' actions. You gain the following benefits.\r\n\t\t\tBattle Precognition. You cannot be surprised while you are conscious, and you add your wisdom modifier to initiative rolls.\r\n\t\t\tPunishing Strike. When a creature misses you with an attack, you can immediately use your reaction to make an unarmed strike against that creature."}, {"name": "Chronal Shifting", "lvl": 3, "text": "At 6th level, you gain the ability to shift through the flow of time, and your future sight lets you affect your course of action. You can spend 2 ki points to cast mirror image, blur, or augury, without providing material components. Additionally, you gain the guidance cantrip if you don’t already know it."}, {"name": "Dilation Assault", "lvl": 3, "text": "At 11th level, your power to influence the flow of time with ki manifests. Whenever you spend a ki point to use Flurry of Blows, Patient Defense or Step of the Wind as a bonus action, you may make an extra unarmed strike as part of your bonus action."}, {"name": "Time Domination", "lvl": 6, "text": "At 17th level, you can deftly manipulate time. During combat, you can take an extra turn. You may choose at which point during initiative order you do this. Once you use this feature, you can’t use it again until you finish a short or long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_FLYING_FEET", "name": "Way of Flying Feet", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Aerobatic Bashes", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, you can harness the energy of your movement into your strikes. If you move at least 10ft before taking a melee attack on your turn you can take up to a -5 to the attack roll for double this added to the damage. (-1 --> +2, -2 --> +4)"}, {"name": "Flux of Ki", "lvl": 6, "text": "At 6th level, you are so used to channeling your ki into your movement that you do it instinctively. Your speed increases by 10ft and you no longer need to spend a ki point to take Step of the Wind as a bonus action."}, {"name": "Perplexing Momentum", "lvl": 11, "text": "At 11th level, you have become so nimble, that your speed leaves others dazed. Your pace no longer limits your ability to move stealthily, and when you take the Dash action, Perception checks against you have disadvantage. Additionally, when you hit a creature with your Aerobatic Bashes, it induces disadvantage on saving throws against the stunning strike ability or any other source of stunning until the start of your next turn."}, {"name": "Harmonic Flow", "lvl": 17, "text": "At 17th level, Your control over the flow of ki can be used to ward off attack against you. At the end of your turn, for every time you successfully hit a target with Aerobatic Bashes, you gain {{wisdom:modifier}} temporary hit points."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_STEEL", "name": "Way of Steel", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the Way of Steel strive to imitate the strength, flexibility, and refinability of steel. Through rigorous training, they hardening their bodies to be like the plates of armour, and their fists like the head of a warhammer.", "features": [{"name": "Iron Body", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, your body's ability to take hits has been boosted. As a reaction you can spend a ki point ot add 3 to your ac."}, {"name": "Fists of Steel", "lvl": 6, "text": "At 6th level, you've mastered techniques to harden your body in just the right ways, allowing your fists to strike like a sledgehammer. As a bonus action you can expend 2 kip points to add 1d8 bludgeoning damage to all of your melee attacks for the next minute."}, {"name": "Tempered Body", "lvl": 11, "text": "At 11th level, your body has taken on the ever-improving nature of steel. You are resistant to fire and cold damage. Additionally, if you use your Fists of Steel feature the turn after you've taken fire or cold damage, you can deal 1d6 of that type in addition."}, {"name": "Steel Soul", "lvl": 17, "text": "At 17th level, your body is like a suit of armour. When you are reduced to 0 hit points you can expend 3 ki points to be reduced to 1 hit point instead."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_WATER", "name": "Way of Water", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the Way of Water take inspiration from water's never-ending flow from one place to another. They imitate its ability to gently flow in one moment, or come crashing down the next, learning to smoothly transition from flowing evasion to devastating counter attack.", "features": [{"name": "Gentle Stream, Crushing Current", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, you can influence your ki to flow through your body as a stream flows down a hill. When you use your patient defense, you gain advantage on the first attack next turn."}, {"name": "Sweeping Tide", "lvl": 6, "text": "At 6th level, you have learned a technique to knock enemies feet from under them as the undercurrent in a tide does. When an enemy succeeds their saving throw against your stunning strike you can spend an additional ki point to knock them prone instead."}, {"name": "Form of the Flowing River", "lvl": 11, "text": "At 11th level, you embody the essence of water, and move as if you were a flowing stream. You can move through crowds of people and difficult terrain unimpeded, and you are considered one size smaller for the purposes of squeezing."}, {"name": "Stillness of the Pond", "lvl": 17, "text": "At 17th level, your soul is as still as a pond and you can expand this aura of calm like ripples from an impact. You can expend 5 ki points to create an aura reaching out 20ft from you of complete calm. Any offensive spell or attack that moves past this aura or is made within this aura fails automatically friendly or otherwise. Additionally when you strike a creature who tried to make an offensive action in the aura you gain advantage. This effect ends after 30 seconds or until you end it as a bonus action or until you end it by making an attack. If you end it by making an attack you gain a number of d10 to the damage equivalent to the number of turns the aura was active. For example if you attacked after the first turn you'd gain 1d10, but after five turns it would be 5d10."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_GRAVITATION", "name": "Way of Gravitation", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the way of Gravitation use their ki to manipulate the very force of gravity. To them it is a simple extension of their natural force.", "features": [{"name": "Gravitational Punches", "lvl": 3, "text": "Whenever you strike two different creatures with you unarmed attacks within five rounds of each other you can spend a ki point to create an attraction between the two. They must make a strength saving throw against your ki DC or be pulled towards each other at a rate of 10ft per round. When they collide they take a damage as if they had been falling towards each other.\r\n\t\t\tIf you strike the same creature twice in the same round you can create a gravitational anchor. You can spend 1 ki point to create the anchor, for each 5ft the creature tries to move they must make a strength check against your ki DC. if they fail they loose all further movement on this turn."}, {"name": "Light as a Feather", "lvl": 3, "text": "At third level you can manipulate gravity around yourself, you can stand up from prone using 5ft of movement.\r\n\t\t\tAdditionally you can spend a ki point to increase you high jump by 10ft, your long jump by 15ft, or reduce falling damage by 1d10."}, {"name": "Fluctuate", "lvl": 6, "text": "At 6th level you get the following abilities:\r\n\t\t\tCatch You can spend a ki point as a reaction to cast feather fall on yourself without any components.\r\n\t\t\tAnchor As a reaction to being moved you can choose to increase gravity and not be moved instead"}, {"name": "Low Gravity", "lvl": 11, "text": "At 11th level when you use your step of the wind feature you gain flying speed equal to your walking speed until the end of the round.\r\n\t\t\tAdditionally whenever you hit someone with your unarmed strike they take force damage equal to twice your wisdom modifier"}, {"name": "Plummet", "lvl": 17, "text": "At 17th level your abilities at manipulating gravity have grown to the point where you can control direction to an unprecedented degree. When you strike a creature you can spend a number of ki points to launch it in a direction you choose. The creature must make a strength save against your ki DC on a success they move half the distance on a fail they move the full distance. The distance they move is equivalent to 30ft X the number of ki points you spend."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_WRATH", "name": "Way of Wrath", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the way of Wrath are often shunned from traditional monasteries, the way of wrath is similar to the bloodlust of a barbarians rage, letting your hatred and rage fill yourself, loosing control to it and allowing your connection to the life force of everything, ki, power extraordinary abilities.", "features": [{"name": "Wrathful Trance", "lvl": 3, "text": "When you choose this tradition you gain the ability to give in to the hate and enter a state of mind called a wrathful trance. The trance lasts up to 2 minutes, it ends if you are incapacitated or when you choose to end it. For one attack per turn you can add {{level:monk:half:up}} to the attack roll and damage dice."}, {"name": "Will Breaker", "lvl": 7, "text": "Whilst in a Wrathful trance you can spend two ki points to cast the fear spell without offering any components\n\t\t\t Additionally you gain double your proficiency bonus to intimidation checks"}, {"name": "Invigorating Wrath", "lvl": 11, "text": "At 11th level when you deal damage using at attack whilst in a Wrathful Trance you recover 1d4 hit point every time you deal damage."}, {"name": "Raging Demon", "lvl": 17, "text": "At 17th level you can choose to end your Wrathful Trance early by expending all hatred into a single attack. You can spend a number of ki points to enhance the final attack. For each ki point you spend you deal another 1d10 + {{martial arts:damage}} for this final attack. For each round before the maximum of 20 you end the trance you deal an additional 1d8 damage. You can't use the Wrathful Trance feature after this until you have completed a short or long rest where you spend at least one hour re-building the rage inside."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_DYNAMIS", "name": "Way of Dynamis", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "The Way of Dynamis focuses on training their disciples in how to better utilize the energy generated by their movement. By manipulating the Ki within their bodies as they move, they store the energy that would otherwise be lost and convert it into devastating power that they release through their strikes. The process of sorting and expelling this energy is a closely guarded secret, as in untrained hands it can wreak havoc upon the user's body. Monks that undertake training in the Way of Dunamis ", "features": [{"name": "Dynamis Flow", "lvl": 3, "text": "Starting at 3rd level, you gain the ability to enter into a state known as Dynamis Flow, where you change your movement patterns to gather the continuous kinetic energy that would normally be lost when you move. You may spend 1 ki point to enter Dynamis flow, after which you generate one Kinetic Charge for every 10 ft of movement on your turn. You may have a maximum number of {{dynamis:charge}} kinetic charges and you lose any charges at the start of your next turn. Dynamis flow lasts until the start of your next turn and you cannot use dynamis flow two turns in a row."}, {"name": "Kinetic Blasts", "lvl": 3, "text": "At 3rd level, you can take the built up energy within you and release it in a devastating blast. Once per turn whilst in the state of Dynamis Flow, after gaining at least one Kinetic Charge you can choose to expend any Kinetic Charges you have generated when making an unarmed attack against a target, dealing an additional 1d{{martial arts:dice}} force damage for each expended charge.\r\n\t\t\tAdditionally, you cna cause the attack to expand outwards in a concussive blast. Regardless of whether you hit or miss the intended target you can spend 1 ki point to force each creature in a 15ft cone to make a constitution saving throw against your ki DC or take a number of d{{martial arts:dice}}s in force damage equal to the number of charges you expended.\r\n\t\t\tAny force damage dealt by Kinetic Blasts have the Siege ability dealing double damage to objects and structures."}, {"name": "Dynamis Flux", "lvl": 6, "text": "At 6th level you've refined your movement in Dynamis Flow to gain the following benefits:\r\n\t\t\tFlowing Movement. While in Dynamis Flow, movement through difficult terrain costs you no extra movement.\r\n\t\t\tAgile Flow. Any attacks of opportunity made against you while in Dynamis Flow are made at disadvantage"}, {"name": "Caching Potential", "lvl": 11, "text": "At 11th level you have learned to control the potential energy of your body as you remain still in order to make it more durable. When you use Patient Defense you gain resistance to bludgeoning, slashing and piercing damage."}, {"name": "Dynamis Realized", "lvl": 17, "text": "At 17th level you've perfected how energy flows through your body and are also able to extract the potential energy of those you halt and and devastate their body by converting it to kinetic energy. You gain the following benefits:\r\n\t\t\tKinetic Ceiling. The maximum number of charges you are able to hold doubles\r\n\t\t\tRealised Might. When you hit a creature with Stunning Strike and cause them to be stunned, you may add 1d{{martial arts:dice}} force damage to every following unarmed strike make on that creature on that turn. On the last  hit, the target must make a strength save against your ki DC or be launched 30ft away. If the creatures path is blocked treat it as if the creature had been falling towards the blockage."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_QI_CARDS", "name": "Way of the Qi Cards", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "The destiny is a deck of cards, and you never know what you'll draw tomorrow. You have learned to tap into the collective subconsciousness of all living thing and use this to inscribe Qi cards.", "features": [{"name": "Bonus Proficiencies", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level,you gain proficiency in sleight of hand, playing cards, calligrapher's supplies and painter's supplies."}, {"name": "Qi Cards", "lvl": 3, "text": "At 3rd level, you can spend 1 hour and 1gp worth of materials to create a qi card using calligrapher's supplies or painter's tools, inscribing it with any cantrip of your choice. You can use a cantrip Qi card as many times as you'd like. Additionally you can create leveled spell Qi Cards, the card takes 1 hour for each spell level (5 hours for 5th level), and costs 5^spell level gp (5 for 1st, 25 for 2nd, 125 for 3rd, 625 for 4th etc). Each of these Qi cards can be used once per short rest and don't count against your prepared qi cards. Additionally it takes a number of ki points equivalent to the spell level to use the spell however to create a leveled card you must be of the required level (3ed level for a 2nd level spell, 5th level for 3rd, 7th level for 4th etc.). After finishing as short rest you can prepare {{qicard:number}} Qi Cards. While you hold a prepared Qi Card or a deck of Qi Cards you can cast the cantrips without providing a material component, your save dc is {{qicard:spellcasting}} and your attack bonus is {{qicard:modifier}}. Casting a cantrip counts as an attack for purposes of other monk features."}, {"name": "Trap Card", "lvl": 6, "text": "At 6th level you can spend 1 ki point to set a prepared qi card as a trap card. The cantrip must require a saving throw and cant be concentration. You can have {{wisdom:modifier}} cards set at one time. You can deactivate a trap card as a bonus action. When a creature enters within the range of the cantrip of your trap card the card activates and the spell is cast targeting the creature that activated it. After a card is activated it warps into your possession. When a trap is activated you are alerted immediately."}, {"name": "Focus of the Four Kings", "lvl": 11, "text": "At 11th level your focus is enhanced. If a cantrip requires concentrations its duration becomes 24 hours. Additionally, when any of your Qi Cards that are on the same plane of existence as you deals damage to a creature you can use your reaction to teleport into the nearest unoccupied space to that creature."}, {"name": "Heart of the Cards", "lvl": 17, "text": "At 17th level, you let the heart of the cards guide you in the most critical moments. When you take the attack action in which you replaced both attacks with Qi Card attacks, you can use your bonus action to prepare a Qi Card. Additionally you can use your action to expend 2 ki points to select one trap card and one creature within range of that spell as if you were casting. You can disable the rest of your trap cards including the selected one to cast the cantrip. If the target fails the saving throw then they take additional damage equivalent to 4 unarmed strikes for each trap card that you disabled. It takes half that amount on a successful save."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_DREAMER", "name": "Way of the Dreamer", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "The Ossended Host is an esoteric group of acolytes who worship the power of dreams and nightmares. Monks of this order spend night after night perfecting a form of meditation that can access a communal dream shared by all of their order. Within this dream, generations of monks have recorded legends, forgotten tomes, ancient histories, and much more. This wealth of knowledge is held within and maintained by the mysterious entity that leads the Ossended Host. No outsider has ever seen this being.", "features": [{"name": "Dreamer's Meditation", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, you gain the ability to access a communal dream through deep meditation. Whenever you sleep you find yourself in The Dream, and no longer dream normally. The Dream takes a unique form to each practitioner, though any dreamer is able to use the information the Ossended Host has stored there. If you spend a long rest sleeping you may study in The Dream, looking for information of your choice. At the end of the long rest, you may make an Intelligence check with advantage as though you were in a library searching for information."}, {"name": "Unwanted Visions", "lvl": 3, "text": "At 3rd level, you learn how to trigger memories of past dreams, both good and bad, by striking particular nerves. When you strike a creature, once per turn, you can force them to make a wisdom saving throw. On a failure they take {{wisdom:modifier}} psychic damage and are charmed or frightened (your choice) by/of you until the start of your next turn."}, {"name": "Soothing Bond", "lvl": 6, "text": "At 6th level, you may choose to spend some time in your dream visiting those near you, calming them and opening their minds. At the end of a long rest, up to 5 humanoids other than yourself, who slept within 100ft of your gain {{bond:hp}} temporary hit points. These creatures become bonded to your dream for upt to 24 hours or until they lose the temporary hit points. While bonded to these creatures you may telepathically communicate with them while they are within 60ft of you and they have advantage on saving throws against being frightened."}, {"name": "Dreamer's Insight", "lvl": 11, "text": "At 11th level, The dreamer can sometimes tap into knowledge their conscious mind cannot understand, giving them brief flashes of insight during combat. When a creature hits you with an attack, you can spend 2 ki points as a reaction to gain insight into their future attacks. Until the end of your next turn, you don't provoke attacks of opportunity from them and their attack rolls against you are at disadvantage."}, {"name": "Waking Dream", "lvl": 17, "text": "At 17th level, you have spent so much time within The Dream, that it and the real world blur together, altering your mind beyond mortal recognition. You are immune to psychic damage and the charmed and frightened conditions, and can always perceive illusions for what they are. In addition if any creature attempts to charm you, frighten you, or read your thoughts, they must make an Intelligence saving throw, or take {{level:monk}} psychic damage."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_FLOWING_GRACE", "name": "Way of the Flowing Grace", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "The flowing monk moves as the waters and winds. They glide with grace around and among their enemies, manipulating their foes' aggression into weakness. Monks who follow this tradition learn to wait and listen, moving only when pushed or pulled by the tide of battle. In this way, they stand resolute and untouchable by all but the quickest of foes.", "features": [{"name": "Flowing Dodge", "lvl": 3, "text": "Starting at 3rd level, you can enter a state of utter grace when threatened. \tWhen you use your Patient Defense feature, you may enter a flowing stance until the start of your next turn. While in this stance you gain the following benefits.\r\n\t\t\tYou have a bonus to AC equivalent to the number of hostile creatures within 5ft of you.\r\n\t\t\tWhen you hit a creature with an opportunity attack they take {{level:monk}} additional damage"}, {"name": "Guiding Winds", "lvl": 3, "text": "At 6th level, you gain the ability to show your allies the safe, invisible pathways through a battlefield. When you use your Step of the Wind feature, each willing creature of your choice within 5ft of you can use its reaction to move up to half its walking speed without provoking attacks of opportunity."}, {"name": "Perpetual Vigilance", "lvl": 3, "text": "At 11th level, you become adept at seizing the opportunities that come to you in battle. You have advantage on attack rolls made on other creatures' turns (such as attacks of opportunity)."}, {"name": "Perfect Grace", "lvl": 6, "text": "At 17th level, you enter the final level of serenity. You can take two reactions a round instead of just one. Additionally as part of an opportunity attack you may move up to half your walking speed without provoking attacks of opportunity yourself."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_the Blademaster", "name": "Way of the Blademaster", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the Blademaster value beauty in combat, they turn a violent bloodbath into an artistic display mastering not only their own body but mastering the use of blades as an extension of their own body.", "features": [{"name": "Superior Swordsmanship", "lvl": 3, "text": "When you choose this tradition at 3rd level you gain proficiency with acrobatics, additionally you gain double your proficiency in acrobatics checks, additionally you gain proficiency in swords.\r\n\t\t\tWhenever you use the deflect missiles or flurry of blows abilities you can replace an open hand with a bladed weapon. For flurry of blows you don't change the damage dice from your martial arts dice but the damage type changes to slashing or piercing depending on the weapon."}, {"name": "Blade Surge", "lvl": 3, "text": "After making a melee attack with a bladed weapon you can move up to {{monk:unarmored movement}}ft without attacks of opportunity and then spend a bonus action to make another attack against a new creature."}, {"name": "Duel of Steel", "lvl": 6, "text": "At 6th level your deflect missiles can be used against a melee attack as long as you have a bladed weapon.\r\n\t\t\tAdditionally you can spend a ki point and a bonus action to force a creature into a duel. When a creature is in a duel it can't take the disengage action, if it tries to make an action that is not focused on you you get an attack of opportunity, if anyone else tries to make an attack on you you can use a reaction to split the damage between you and the other duelist."}, {"name": "Blade Dance", "lvl": 11, "text": "At 11th level any time a creature falls prone within range it provokes an attack of opportunity. Additionally you gain an additional reaction every turn that can only be used for the deflect missiles reaction."}, {"name": "Omnislash", "lvl": 17, "text": "At 17th level your blade surge has reached a superior level. You can spend a number of ki points, for each point you can make two attacks, after each attack you can teleport up to {{monk:unarmored movement}}ft to an unoccupied space, when you land you can make any other attacks. Each of the attacks deal you {{martial arts:dice}} + the weapons damage dice + {{martial arts:damage}} + {{wisdom:modifier}} + 2d10 force damage."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_THE_THUNDERCLAP", "name": "Way of the Thunderclap", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "The Way of the Thunderclap is a tradition tailored to those who have an affinity for lightning, being scarcely passed down within the lands of the material plane. Monks of this tradition learn how to use their elemental ki to generate an electric surge within their body, thus enhancing their speed of movement, as well as the effectiveness of their offense, to a level which can be considered unnatural.", "features": [{"name": "Innate Affinity", "lvl": 3, "text": "When you choose this tradition at 3rd level, you learn the Shocking Grasp and Lightning Lure cantrips, and can spend 1 ki point to cast either of them as a bonus action on your turn. This can be done only once per turn. Wisdom is your spellcasting ability for these spells."}, {"name": "Lightning Reflexes", "lvl": 3, "text": "At 3rd level, you learn how to use the voltaic nature of the ki flowing through you to control your muscles well beyond human reaction time. Once per turn, you may choose one of the following benefits:\r\n\t\t\tSonic Burst - You can spend an additional ki point to use Flurry of Blows on your turn without expending a bonus action. When you do, your strikes emit a thunderous boom audible out to 100 feet. Only one Flurry of Blows may be used per turn.\r\n\t\t\tCounter Rush - After using Patient Defense, you can use your reaction to make one unarmed strike against any creature that misses you with a melee attack.\r\n\t\t\tStatic Blur - When using Step of the Wind, your movement is unaffected by difficult terrain, you can move through any creature’s space, and you don’t provoke opportunity attacks. Once you use this benefit, you can't use it again until you move 0 feet on one of your turns."}, {"name": "Storm Charge", "lvl": 6, "text": "At 6th level, you can fully manifest your elemental power, enveloping yourself in a coat of lightning which grants an uncanny boost to your performance. As a bonus action, you can spend 2 ki points to enter a Charged state, lasting for 1 minute. While in this state, you gain the following benefits:\r\n\t\t\tYou shed bright light in a 5-foot radius and dim light for an additional 5 feet, as lightning furiously crackles around your body.\r\n\t\t\tYou gain resistance to lightning damage.\r\n\t\t\tYour unarmed strikes deal an additional 1d{{storm:die}} lightning damage. A creature can take this additional damage only once per turn.\r\n\t\t\tWhenever a creature hits you with a melee attack, it must succeed on a Constitution saving throw or take {{wisdom:modifier}} lightning damage. This can happen only once per turn.\r\n\t\t\tAs a bonus action on your turn, you can expend 1 hit dice to gain 2 ki points. This can be done {{proficiency}} times per use of Storm Charge.\r\n\t\t\tYou may use this ki feature {{storm:usage}} times, and regain any expended uses when you finish a long rest."}, {"name": "Surging Flux", "lvl": 11, "text": "At 11th level, you are able to push the limits of your body and spirit, intensifying the stream of energy flowing through you at the cost of your vitality. You gain further benefits while in Charged state:\r\n\t\t\tAt the start of each of your turns, you gain {{proficiency}} temporary hit points, provided that you have at least 1 hit point. These temporary hit points disappear when your Storm Charge ends.\r\n\t\t\tIf you have half or less of your total hit dice remaining, you can expend {{martial arts:dice}} hit points in exchange for 1 ki point (no action required). This can be done only once per turn.\r\n\t\t\tYou can take one additional reaction per round. This can be done {{wisdom:modifier}} times per use of Storm Charge."}, {"name": "Innate Mastery", "lvl": 11, "text": "At 17th level, you unlock the full potential of this elemental combat style. While in Charged state, you can take one additional bonus action per turn. Additionally, you gain access to the following ki feature:\r\n\t\t\tThunderclap Blitz. As an action on your turn, you can spend 5 ki points to empower yourself and vanish in a burst of spark. Choose up to five creatures you can see within 60 feet of you. Make an unarmed strike or melee spell attack (your choice) against each target. On a hit, a target takes 6d10 lightning damage. You can then teleport to an unoccupied space you can see within 15 feet of one of the targets you hit or missed. All creatures within 10 feet of the space you teleported to must make a Constitution saving throw, taking 1d10 thunder damage and becoming deafened for 1 round on a failed save. This maneuver emits a resounding rumble audible out to 1000 feet."}]}, {"id": "ID_RDDT_ARCHETYPE_WAY_OF_WINTERS_FURY", "name": "Way of the Winters Fury", "parentClass": "Monk", "source": "Reddit : Unearthed Arcana", "summary": "Monks of the way of the Winters Fury live bitter, brutal lives on isolated mountain tops, meditating in thundering storms, freezing streams and skin tearing blizzards until their Ki aligns itself with the power of cold.", "features": [{"name": "Sway the Storm", "lvl": 3, "text": "Starting when you choose this tradition at 3rd level, you learn the Gust and Shape Water cantrips."}, {"name": "Colds Embrace", "lvl": 3, "text": "At 3rd level, you  gain the ability to encase your limbs in ice, allowing you to choose whether your unarmed strikes deal bludgeoning or slashing damage. Whenever you hit a creature with one of the attacks granted by flurry of blows you can impose one of the following effects:\r\n\t\t\tFrozen Ground. Your target has their movement speed reduced to zero until the end of their next turn.\r\n\t\t\tSnowblind. Your target makes a constitution save, if he fails he is blinded until the end of their next turn.\r\n\t\t\tWinters Bite. You deal extra {{wisdom:modifier}} cold damage."}, {"name": "Icicles Advantage", "lvl": 6, "text": "At 6th level, you become resistant to cold damage. In addition whenever you use your unarmed movement to pass over a liquid you now freeze the liquid solid for the next minute. Therefore you won't fall if you end your turn on liquid."}, {"name": "Frostbite Counter", "lvl": 11, "text": "At 11th level, you learn to incorporate the aspects of a blizzard into your physical form. When you use your Patient Defense feature your body turns into a swirling flurry of snow. If ann attacker within 5ft of you misses you with an attack while this feature is active you can spend 1 ki point to use your reaction to let the hit pass through you and counter with two unarmed strikes."}, {"name": "Become Blizzard", "lvl": 17, "text": "At 17th level, you can fully unleash the wrath of your Winters Fury. As a bonus action, you turn yourself into a raging ice storm for 1 minute, granting yourself resistance to all tyoes except fire and immunity to cold. It allows you to move through the space of another creature or through gaps larger than 1 inch in diameter. Enemies that start their turn within 5ft or move into 5ft of you take {{wisdom:modifier}} cold damage."}]}, {"id": "ID_RDDT_ARCHETYPE_UNUS_ANNUS", "name": "Unus Annus", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "We live our lives taking each second for granted. But what would you do if you knew how much time you had left? Warlocks of Unus Annus seek to answer this question. By taking this pack, they knowingly put a time limit on their lives, and intend on living out their lives to the fullest. Warlocks of this pact are perfectly content with the limited time of their lives, for they understand that all things must die, as is the natural order of things. They view undead as abominations that must all be ", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Unus Annus lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Memento Mori", "lvl": 1, "text": "Starting when you make this pact at 1st level, you are doomed to die in 1d20 years. You always know how much time you have left."}, {"name": "Voice of Time", "lvl": 1, "text": "Also at 1st level, you choose which of the two beings resonates with you the most, and decide whether you're an Unus or an Annus. Choose one of the following features. Once you choose one, you cannot choose another one."}, {"name": "Reaper of Time", "lvl": 6, "text": "At 6th level, you are gifted a specialized weapon from Unus and Annus. As an action, you can summon a scythe made of black or white flames, the color depending on whether you're an Unus or an Annus for 1 minute. This scythe deals necrotic damage equal to 1d{{scythe:die}} + {{charisma:modifier}}, and you gain a number of hit points equivalent to the damage you dealt.\r\n      Additionally, if you use this scythe against an undead, you deal an additional 1d{{scythe:die}} and deal radiant damage instead of necrotic damage, however you do not gain any hit points. This scythe is dispelled one you have been knocked unconscious or you dispel it as a bonus action. Once you use this ability, you cannot use it again until you finish a long rest."}, {"name": "Don't Try This at Home", "lvl": 10, "text": "At 10th level, you learn to turn your mistakes into dangerous means of success by improvising. Whenever you miss with an attack or spell, you can reroll it with a Performance check, and you have to take the new roll. If you roll a natural 1, you end up hitting yourself. You can use this ability {{charisma:modifier}} times per long rest."}, {"name": "Carpe Diem", "lvl": 14, "text": "Starting at 14th level, Unus and Annus are aware of your time left and wish to see you live out every single second. Whenever you make a death save, you roll with advantage. In addition, if you roll a natural 20 on a death save, you immediately stabilize and heal {{carpe:diem}} hit points."}]}, {"id": "ID_RDDT_ARCHETYPE_MONSTER_IN_THE_CLOSET", "name": "The Monster in the Closet", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "The weird shadow on the wall, the unsettling creak of the floorboards, the soft scratch against the window. Sometimes the imaginary monsters hiding in the dark are not at all imaginary. Sometimes they don’t fade away as children grow into adults. Sometimes those adults prove to be just as frightening as the monsters themselves.\r\n      Warlocks with a Monster in the Closet patron might know their monster only as a haunting memory, or they may get together, person-to-monster, on a regular basis. T", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Monster in the Closet lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Security Blanket", "lvl": 1, "text": "You have a physical memento from childhood—a favorite toy, a blankey, a hand-drawn picture. While in possession of the memento, you have a +{{warlock:spellcasting:slot}} bonus to all saving throws.\r\n      The item is magically durable and can only be truly damaged with a spell like Wish. The item can be lost however, in which event, a warlock may go to extreme efforts to recover it."}, {"name": "Cast in Darkness", "lvl": 6, "text": "Starting at 6th level, your patron slinks along with you just outside of the material plane, protecting you from harmful magics. You may cast Counterspell without using a spell slot. After using this ability, you may not use it again until you finish a long rest."}, {"name": "Lurking Danger", "lvl": 6, "text": "As a bonus action, you can call the monster partially into the world for 1 minute at your location. The monster acts on your initiative, and you may decide how it spends its action. It may not attack, but it may take other actions and may use your Warlock spell slots to cast spells that you know. It may not cast cantrips.\r\n      The monster is medium sized and shares your AC, movement speed, ability and saving throw modifiers, and maximum HP. It also has 120 foot darkvision and advantage on Intimidation checks.\r\n      After 1 minute or if the monster is reduced to 0 HP, it retreats from the material plane until you call on it again. You may not use this feature again until you finish a short or long rest."}, {"name": "Always Watching", "lvl": 10, "text": "The monster will alert you if it senses danger. While sleeping, you may use your passive perception as if you were awake. You cannot be surprised at the start of combat."}, {"name": "Mystic Arcanum Improvement", "lvl": 14, "text": "While the monster is present using Lurking Danger and either you or your monster use the Attack action, the attacker may make three attacks as follows:\r\n      Eldritch Assault. Magical Melee Weapon Attack: +{{spellcasting:attack}} to hit, reach 5 feet, one target. Hit: 1d10 + {{charisma:modifier}} force damage."}]}, {"id": "ID_RDDT_ARCHETYPE_STAR_FORGER", "name": "The Star Forger", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Your patron is the Star Forger, a creature of immense power and stature with an ability to traverse the galaxy and adjust the very stars themselves, Ancient astral dragons, particularly powerful star spawn, or even Elder Evils.\r\n      With the magic they've granted you, you're able to manipulate your own personal galaxy, bending small stars to your will. Additionally, you can suspend your magic, nurturing it as you wait of the the perfect moment to unleash the full power of the cosmos upon your ", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Void lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Cosmic Suspension", "lvl": 1, "text": "At 1st level, you can delay your spells, casting them when you need them the most. When you cast a warlock spell of 1st-level or higher on your turn, you may suspend it for up to 1 minute. A suspended spell has no immediate effect instead you may use your reaction to cast the spell at any point during that time (including on your turn). If the minute passes without you casting that spell the spell slot is used. You may only suspend 1 spell at a time."}, {"name": "Centre of the Universe", "lvl": 1, "text": "At 1st level, you may use your action to create 3 motes of light that shed bright light in a 5ft radius. As a free action you may dim them to produce dim light or no light. As a bonus action you may move a mote to any point within 60ft of you or have one return to you. If you move more than 60ft from a mote in automatically returns."}, {"name": "Stellar Flare", "lvl": 6, "text": "At 6th level, your galaxy begins to blaze. When a creature you can see moves within 10ft of one of your motes or starts its turn there, you can use your reaction to deal 1d4 radiant damage to that creature on a failed Constitution saving throw."}, {"name": "Approach Velocity", "lvl": 10, "text": "At 10th level, you become immune to fall damage, you cannot be knocked prone while you're conscious and ignore non magical difficult terrain. Additionally, when you take the Dash action you may now move across liquid surfaces as if they were solid, you may still take damage from this and once you stop moving they act like liquids again."}, {"name": "Supernova", "lvl": 14, "text": "At 14th level your mere thoughts pull at the tapestry of the universe, bending it to your will. You may move any number of your motes as a bonus action on your turn. Additionally, as an action on your turn, you can have all of your motes spark with the light of creation. Creatures of your choice within 10ft of at least one of your motes must make a Constitution saving throw. On a failed save, a creature takes 14d4 radiant damage and is blinded until the end of you next turn. In a success, a creature takes half as much damage and isn't blinded. Once you use your motes in this way they go out and may not be summoned until you have finished a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_ANCIENT_FROST", "name": "The Ancient Frost", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Your patron is a powerful wielder of ice and cold. You have bound yourself to an ancient god of frost or cold.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Ancient Frost lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Cold Bringer", "lvl": 1, "text": "At 1st level, you learn the ray of frost cantrip."}, {"name": "Frosted Pact", "lvl": 6, "text": "At 6th level, you can use your charisma modifier for attack and damage rolls with your pact weapon(pact of the blade). You can have an ice mephit for your familiar(pact of the chain). When you deal cold damage with a cantrip you can add your charisma to damage(pact of the tome)"}, {"name": "Ice Elemental", "lvl": 10, "text": "At 10th level you gain the ability to conjure an ice elemental as an action. An ice elemental is the same as an earth elemental with a few changes: It has resistance to cold damage, it deals magical cold damage."}, {"name": "Permafrost", "lvl": 14, "text": "At 14th level whenever you cast a spell that deals cold damage it deals a further 2d8 cold damage"}]}, {"id": "ID_RDDT_ARCHETYPE_VOID", "name": "The Void", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Your patron is the void, the absolute nothingness, the complete absence of existence, itself a concept so unintelligible that the mortal mind fails to comprehend it even on the most basic of levels.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Void lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Twisted Life", "lvl": 1, "text": "At 1st level, you learn Deep Speech and your creature type becomes aberration as well as your original type."}, {"name": "One With Nothing", "lvl": 1, "text": "At 1st level, You skirt the edge of non-existence making it harder for creatures to become aware of you. If a creature has interacted with you for less than 1 hour in the past 24 hours they have disadvantage when trying to recall information about you. Additionally a creature has disadvantage on perception checks to become aware of you."}, {"name": "Void Being", "lvl": 6, "text": "At 6th level the void suffuses your being and reality slightly shifts around you. You gain resistance to cold damage. Additionally, you have a 15ft aura of darkness that you can summon around yourself that non-magical light can't illuminate. All creatures within this aura have their speed halved. You can summon or dismiss this aura as a bonus action."}, {"name": "Uncanny Motions", "lvl": 10, "text": "At 10th level the laws of physics begin to fail to apply to you. You gain the ability to move up, down and across vertical surfaces and upside down without falling.\r\n      Additionally, when you move you can instead begin to fall in any direction of your choosing, you are immune to fall damage if you fall in this way. When you being to fall you can't change anything about your trajectory until you hit a solid surface."}, {"name": "Void Aura", "lvl": 14, "text": "At 14th level you can manifest a fragment of the void. While the aura granted by your Void Being feature is active, you can use an action to increase the range by 20ft and have that darkness become absolute so that magical light is also swallowed. All creatures that you choose take 3d8 cold damage and are blind and deaf whilst inside. These effects last for 1 minute or until you choose to cancel them. Once you have used this feature you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_EMPTY", "name": "The Empty", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Abandoned by all else mortals can find themselves filled with a bursting dread and embraced with as deafening silence. These people find themselves on a day to day basis staring into a void that whispers to them dark secrets and ideas, but only those who look into the void and scream back can truly understand how morbid these thoughts truly are. The Empty are those who when scorned by not only people, but the primal forces of the world be it the gods ore the elements themselves would do anything", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Empty lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Soul Shards", "lvl": 1, "text": "At 1st level, you have {{charisma:modifier}} soul shards that can be used to amplify certain powers.\r\n      Soulburn. Once per turn when casting a warlock spell of 1st level or higher that deals damage you may expend a soul shard to have the spell deal {{charisma:modifier}} additional necrotic damage. If you later gain the pact of the blade or chain boon you may use this feature on attacks made with your pact weapon or familiar.\r\n      Haunt. When you see and enemy within 30ft of you regain hit points as a result of a spell you may use your reaction to expend as many Soul Shards as you have to reduce the amount healed equal to {{charisma:modifier}} times the number of expended Soul Shards.\r\n      You regain all spend soul shards at the end of a long rest and {{level:warlock:half:down}} at the end of a short rest."}, {"name": "Ravenous Intent", "lvl": 6, "text": "At 6th level, your hunger grows and your need to fuel yourself has become so intense that even pain means nothing as long as you can devour those around you. As a reaction when a creature makes an attack roll against you, you can grant the creature advantage on the attack roll and if the hit, you gain advantage on all attack rolls against that target until the end of you next turn, you can do this once per long rest."}, {"name": "Devoured Empathy", "lvl": 10, "text": "At 10th level the void has stripped so much of you away that you barely feel anything at all and as such your physique reflects that. You are immune to being charmed, frightened and stunned."}, {"name": "Starved Singularity", "lvl": 14, "text": "At 14th level, your hunger has grown so intense you're willing to rip apart those around you if it means it would fill the void. As an action you can unleash the void. All creatures within 30ft of you must make a charisma saving throw or suffer 6d6 necrotic damage on a failed save or half as much on a successful one. You gain temporary hit points equal to half of the total damage dealt. Once you've used this feature you can't again until you've finished a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_EVER_DREAMER", "name": "The Ever Dreamer", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "While most warlocks approach their patrons searching for unlimited power and fame, Warlocks of the Ever Dreamer are selected, for one reason or another, by a powerful entity to be their vessel on the material plane. In exchange, the ever dreamer offers a portion of its power to the Warlock.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Ever Dreamer lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Restless Retaliation", "lvl": 1, "text": "Starting at 1st level, your patron teaches you about dreams, and how they can effect living creatures, even while they're awake. When a creature hits you with a melee attack, you can use your reaction to force them to make a constitution saving throw. On a failure they suffer a point of exhaustion for the next minute. You can use this feature {{charisma:modifier}} times per long rest. Creatures that are immune to exhaustion are immune to this effect."}, {"name": "Mind's Transport", "lvl": 6, "text": "At 6th level, your patron allows you to temporarily occupy the minds of others. As a bonus action you can enter the mind of one willing creature within 60ft of you. While within the creatures mind, you have total cover, are immune to all damage except for psychic and are incapacitated. The only creature that can hear you is the creature whose mind you are in. At the start of the creatures next turn, or if they fall unconscious, you are ejected 10ft away from the creature. You can use this feature once per short rest."}, {"name": "Tireless Form", "lvl": 10, "text": "At 10th level your patron teaches you ways you can use your mind to defend yourself. You cannot be put to sleep against your will and attacks against you while you are unconscious are not auto-crits, additionally you are immune to psychic damage."}, {"name": "Dreamer's Final Rest", "lvl": 14, "text": "At 14th level, you can plunge a creature into a darkened slumber, filled with nightmares that attack them. As an action, choose a creature that you can see within 60ft of you. It must make a wisdom save. On a failed save it takes 8d8 psychic damage and is knocked unconscious for 1 minute or until it takes damage. On a successful save the creature takes half damage and is not knocked unconscious. Undead and constructs automatically succeed. You can do this once per long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_LIBRARIAN", "name": "The Librarian", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Your patron is the keeper of a large source of knowledge, be it facts, ingredients, or arcane secrets. You have reached out to them to gain the secrets of the multiverse and power. In return, you search for secret knowledge lost in time or those not found in the library.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Librarian lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Patron's Gift", "lvl": 1, "text": "At 1st level, you gain a skill proficiency of your choice. You gain another at 6th, 10th and 14th level."}, {"name": "Book of Spells", "lvl": 1, "text": "At 1st level, you receive a book containing two warlock cantrips of your choice. You gain another cantrip at 6th level. These don't count against the number of cantrips known. You can only cast these with the book in your possession.\r\n      Your Book of Spells. The spells that you add to your book as you gain levels reflect the arcane findings you have found about the nature of the multiverse. You might find other spells during your adventures.\r\n      Copying a Spell into the Book. When you find a warlock spell of 1st level or higher, you can add it to your book. Copying a spell into your book involves reproducing the basic form of the spell. For each level of the spell, the process takes 3 hours and costs 50gp. The cost represents material components you expend as you master the spell. Once it is in your book you can cast it like any other spells.\r\n      Replacing the Book. You can copy a spell from your own book into another book. You only need 1 hour and 10gp per spell level and can do this even if your don't have the original spellbook.\r\n      If you later gain the Pact of the Tome feature, the book of shadows becomes your book of spells."}, {"name": "Access to Knowledge", "lvl": 6, "text": "At 6th level you can enter your patron's library through a doorway during a rest. Inside you can:\r\n      Learn a piece of information about a creature's lore or stats, however some creatures (DMs discretion) are not recorded.\r\n      Gain proficiency in a tool or skill for a day.\r\n      Learn the location of a mundane thing like town but not that of a specific creature.\n      Borrowing a spell. You can add a spell to your spellbook for a day, for every day you keep it past this one day limit you must pay a fine of 5 + (2 x number of days)gp per day. Inability to pay will cause a debt to rack up, and any currency found in the future, even if not your's, to be immediately sent to your patron.\r\n      You can use two of these effects per rest and you must sleep afterwards if you have to. Additionally you only take 2 hours per spell level to transcribe a spell to your spellbook."}, {"name": "Work of Fiction", "lvl": 10, "text": "At 10th level, whenever you're targeted by an attack by a creature, you can use your reaction to write the attack out of existence. The creature has to make an intelligence saving throw against your spell save DC or the attack is negated, wasting any spell slot or ability if used. You have to do this before learning if the attack hits or misses. You can do this once per short rest."}, {"name": "Better Access", "lvl": 14, "text": "At 14th level, your parton bequeaths unto you a shelf in his library. On this shelf you may store a warlock spell slot as a book. You must expend a slot to do so and this can only be done at the end of a short rest. The spell can be used at any point in the future. You can only store one spell like this at a time. Additionally, when you use Access to Knowledge to borrow a spell, you can borrow non-warlock spells."}]}, {"id": "ID_RDDT_ARCHETYPE_TIMELESS", "name": "The Timeless", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "You have made a pact with a being that exists beyond time. Perhaps they are a denizen of the Astral Plane, or some other dimension which has never felt time's unceasing touch, or even from the Twilight Realm known only to the Shade Lords from the first age of Sharth.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Timeless lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Crack Time", "lvl": 1, "text": "At 1st level, your patron grants you a portion of their power to create time fissures. As an action, you can create {{charisma:modifier}} of time fissures within 60 feet of you that you can see. A time fissure is a point with a 5-foot square centred on it that does not obstruct line of sight or movement and is clearly visible. When a creature other than you enters a time fissure or starts its turn in one, it must make a Dexterity saving throw against your spell save DC. On a failure, the creature is frozen in time until the start of their next turn. A creature which is frozen in time is paralyzed, immune to all damage and all other conditions. Any effects which would last until the end of their next turn now last until the end of their turn after. Any conditions or effects the creature was under resume when they are no longer frozen in time.\r\n      A time fissure immediately disappears once a creature has been forced to make a saving throw from it, 1 minute has passed, you use this feature again or until you dismiss all your time fissures as a bonus action.\r\n      You can use this ability {{proficiency}} times, and you regain all expended uses when you finish a long rest."}, {"name": "Timeless Body", "lvl": 6, "text": "At 6th level, you have mastered your own time and can control processes which would cause you to decay. You have resistance to necrotic damage.\r\n      You no longer age and, as an action, you can change your appearance to that of an older or younger version of yourself. Your size cannot be changed in this way."}, {"name": "Prescient Defense", "lvl": 10, "text": "At 10th level, you receive glimpses of the future when one would deal harm to you. As a reaction when you are targeted by an attack, you can impose disadvantage on the attack roll and immediately teleport to where you were at the start of your previous turn. If you are now behind total cover from the triggering attack, the creature may spend that attack against a different target.\r\n      You can use this ability {{proficiency}} times, and you regain all expended uses when you finish a long rest."}, {"name": "Shatter Time", "lvl": 14, "text": "At 14th level, you can cause your time fissures to burst and rip those around them from their current time. As an action, you can expend a spell slot and destroy all of your time fissures forcing each creature within 10 feet of a time fissure to make a Wisdom saving throw against your spell save DC. On a failure, a creature takes 1d10 necrotic damage for each level of the spell slot you expended, or half as much damage on a success. If a creature fails this safe, you can impose one of the following additional effects:\r\n      •The creature is magically aged by 1 year.\r\n      •The creature's speed is halved until the end if its next turn.\r\n      •The creature cannot take reactions until the end of its next turn.\r\n      •The creature is frozen in time as per the rules of the Crack Time feature.\r\n      If a creature fails the saving throw by 5 or more, they are magically aged by one year.\r Creatures within 10 feet of multiple time fissures are affected only once."}]}, {"id": "ID_RDDT_ARCHETYPE_APOCALYPSE", "name": "The Apocalypse", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "You have made a pact with a being that exemplifies destruction in its purest form.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Apocalypse lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Channel of Apocalypse", "lvl": 1, "text": "Starting at 1st level, the vary nature of having a link to a world ending power gives you the following benefits:\r\n      Apocalyptic Visage. As an action, you can alter your appearance to make it reflect the destructive nature of your patron.\r\n      History of Misery. Whenever you make an intelligence check to recollect information about great catastrophes, you are always considered proficient in the related skill and have advantage on the roll.\r\n      Voice of Doomsayer. You learn the thaumaturgy cantrip."}, {"name": "Touch of Ruin", "lvl": 1, "text": "At 1st level, you gain abilities based on the aspects of the apocalypse."}, {"name": "Visions of Apocalypse", "lvl": 6, "text": "At 6th level, you learn how to bestow your foes with crushing visions of their demise, with the extent of that vision depending on your patron and the fears of your enemy. When being targeted by an attack from a creature you can see within 60ft of you you can use a reaction to force the target to make a wisdom saving throw. If the target fails they miss automatically and become frightened until the end of their next turn. Once you use this ability you can't use it again untl you finish a short or long rest."}, {"name": "Deathly Protection", "lvl": 10, "text": "At 10th level, you are an emissary of death and don't succumb so easily to it. As a reaction to being reduced to 0 hit points you can use your reaction to attempt to drain vitality from your aggressor, as long as you can see it. Make a ranged spell attack against the creature. On a hit the target takes necrotic damage equal {{level:warlock}} + {{charisma:modifier}}, you gain that amount of hit points. Once you use this feature you can't use it again until you finish a short rest."}, {"name": "Avatar of Doom", "lvl": 14, "text": "At 10th level, you are an emissary of death and don't succumb so easily to it. As a reaction to being reduced to 0 hit points you can use your reaction to attempt to drain vitality from your aggressor, as long as you can see it. Make a ranged spell attack against the creature. On a hit the target takes necrotic damage equal {{level:warlock}} + {{charisma:modifier}}, you gain that amount of hit points. Once you use this feature you can't use it again until you finish a short rest."}]}, {"id": "ID_RDDT_ARCHETYPE_TWINS", "name": "The Twins", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "You have made a pact with a pair of patrons, two daggers, fey twins or a two headed mad god. Whatever it may be the two of them ffer up a new style of warlock.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Twins lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Bilocation", "lvl": 1, "text": "At 1st level, the unusual nature of your patron allows you to be in two places at once. As a bonus action you can create a second instance of yourself, it appears in an unoccupied space that you can see in 30ft of you and lasts for 1 hour. When this effect ends you choose which image fades. Whenever you take any form of action, bonus action or movement you can choose wich instance performs the action. They share the same body, therefore they have the same hit points tacking damage as one, the same equipment and stats. You can use this feature once per long rest."}, {"name": "Twinned Cantrip", "lvl": 6, "text": "At 6th level, you are able to twin your cantrips. Whenever you cast a cantrip, you cast it twice in the same action, bonus action or reaction. Ending the effects of one spell, or if one of them is dispelled or countered they both are."}, {"name": "Twinned Spell", "lvl": 10, "text": "At 10th level you can twin your spells. When you cast a spell you can expend a spell slot one level higher to cast the spell twice in the same action, bonus action or reaction. Ending the effects of one spell, or if one of them is dispelled or countered, they both are"}, {"name": "Mystic Arcanum Improvement", "lvl": 14, "text": "At 14th level you can choose one more 6th level and 7th level spell to use with your Mystic Arcanum Improvement. When you gain 8th level and 9th level Mystic Arcanum spells you can choose two instead of one."}]}, {"id": "ID_RDDT_ARCHETYPE_VOIDWALKER", "name": "The Voidwalker", "parentClass": "Warlock", "source": "Reddit : Unearthed Arcana", "summary": "Your patron is an entity ruling over the Void, a being of pure chaos. Despite its claims of neutrality of its motivations, it has been shaping the history of mankind for centuries and millennia. Beings of this sort include the Dead God, and the Void itself.", "features": [{"name": "Expanded Spell List", "lvl": 1, "text": "The Voidwalker lets you choose from an expanded list of spells when you learn a warlock spell."}, {"name": "Far Reach", "lvl": 1, "text": "At 1st level, you gain one of the following features.\nBlink. You can use your bonus action to teleport up to 10ft away to an unoccupied space you can see. While moving this way you don't provoke opportunity attacks and are invisible. You can also spend 15ft of movement to travel 30ft.\nDisplace. You can use your bonus action to form a Void link up to 30ft from you. On your next turn you can teleport to the Void link as a bonus action, not provoking attacks of opportunity. The link stays for 1 minute or until you dismiss it. If you move further than 60ft away from it it dissipates, you can teleport to the link as a bonus action as long as it exists. It is invisible."}, {"name": "Void Gaze", "lvl": 6, "text": "At 6th level, you can use your bonus action or your action to see any living creature, construct or undead within 30ft of you."}, {"name": "Creature of Darkness", "lvl": 10, "text": "At 10th level you gain one of the following features.\nShadow Walk. You can use your action to transform into a shadow for 1 minute. In this state you and anything on your person are completely invisible. You cease to be invisible if you attack or cast a spell. While in this form you can end it by making a melee attack using your spell attack bonus dealing 4d10 force damage on a hit. This attack counts as an attack with a finesse weapon for purposes of a rogue's sneak attack. You can use this once per short rest.\nDevouring Swarm. You can cast Conjure Animals at 5th level once per short rest. You can only summon a swarm of rats."}, {"name": "Arcane Link", "lvl": 14, "text": "At 14th level you gain one of the following features"}]}, {"id": "ID_RDDT_ARCHETYPE_COLLEGE_OF_ORIGAMI", "name": "College of Origami", "parentClass": "Bard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Papercraft", "lvl": 3, "text": "At 3rd level, you gain proficiency with the Origami kit. If you already have this proficiency, you gain proficiency with one other type of artisan’s tools of your choice.\nThe information on Origami kits can be found at the end of this subclass"}, {"name": "Paper Manipulation", "lvl": 3, "text": "Starting at 3rd level, you gain the ability to use paper imbued with your magic and use it to perform tasks. You can expand a bardic inspiration to make one of the following effect:\r\n      Paper Tool. As an action, you create a nonmagical object in your hands that is no larger than 3 feet on a side and weighs no more than 10 pounds. Even if the object is visibly made of paper, it functionally works the same as a normal example of said object. After 10 minutes, it crumbles into a pile of paper.\r\n      Paper Shuriken. As an action, you create 10 paper shurikens. You can then use your bonus action to throw one of them. Roll a ranged spell attack. The shurikens have a range of 60 feet and deal 1d8 + {{charisma:modifier}} on a hit. The shurikens disappear after a long rest."}, {"name": "Origami Clone", "lvl": 6, "text": "Beginning at 6th level, as an action you create a perfect illusion of yourself made of paper that lasts for 1 minute or until you lose your concentration (as if you were concentrating on a spell). The illusion appears in an unoccupied space that you can see within 30 feet of you. As a bonus action on your turn, you can move the illusion up to 30 feet to a space you can see, but it must remain within 120 feet of you.\r\n      For the duration, you can cast spells as though you were in the illusion’s space, but you must use your own senses. when you use a paper shuriken, both you and your clone can throw a shuriken. Additionally, when both you and your illusion are within 5 feet of a creature that can see the illusion, you have advantage on attack rolls against that creature, given how distracting the illusion is to the target."}, {"name": "Greater Paper Manipulation", "lvl": 14, "text": "Starting at 14th level, your paper manipulations gain additional effects:\r\n      Paper Tool. When creating an object using this feature, the object now appears indistinguishable from a normal object and can measure up to 10 feet on a side and weigh up to 100 pounds.\r\n      Paper Shuriken. You now craft 20 paper shuriken at a time, and the shuriken now explodes when hitting a target, dealing an additional 2d8 fire damage."}]}, {"id": "ID_RDDT_ARCHETYPE_COLLEGE_OF_JOURNEYS", "name": "College of Journeys", "parentClass": "Bard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Bonus Proficiencies", "lvl": 3, "text": "You gain proficiency in one of Animal Handling, Navigator's Tools, Land Vehicles or Water Vehicles. In addition you gain 5ft speed of movement, this increases to 10ft at 14th level."}, {"name": "Traveler's Lore", "lvl": 3, "text": "At 3rd level, your time spent traveling throughout the world has hastened your pace and broadened your horizons. You gain a number of spells based on your level much like a Cleric as you slowly learn whilst exploring the world."}, {"name": "Inspire Urgency", "lvl": 3, "text": "You learn to inspire speed and agility in your allies. A creature that has one of your bardic inspiration die can use that die, when it does so it automatically takes the dash and disengage actions involuntarily."}, {"name": "From Thither to Yonder", "lvl": 6, "text": "At 6th level, As a bonus action you can move yourself or one other creature up to 30ft to an unoccupied space you can see. If the creature is willing they are teleported there and can use a reaction to make an opportunity attack with advantage due to surprise. If the creature is not willing they must make a dexterity saving throw or be teleported. When a creature within 30ft of you gets hit you can use your reaction to impose disadvantage and move the creature up to 30ft to an unoccupied space. You can do either of these two things a number of times equal to your charisma modifier per long rest, both abilities take up a usage."}, {"name": "The Planar Shuffle", "lvl": 14, "text": "Starting at 14th level you can dance to the resonant tunes of the planes. You can begin this dance as a bonus action. For the next minute at the beginning of your turn you can teleport up to 10ft you can also grab another creature and teleport them with you retaining the same orientation. You can use this ability 3 times per long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_COLLEGE_OF_SILENCE", "name": "College of Silence", "parentClass": "Bard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Mute", "lvl": 3, "text": "You begin to appreciate that words are not always necessary. You learn the message cantrip and can cast it as a bonus action without verbal components. When casting message you are able to target {{charisma:modifier}} creatures."}, {"name": "Actions Speak Louder Than Words", "lvl": 3, "text": "At 3rd level, you develop the ability to grant others strength through their own silence. Whenever a creature uses one of your bardic inspiration die to increase an attack roll, they can apply the roll to damage as well however if they do so they are unable to speak until the start of their next turn."}, {"name": "The Sound of Silence", "lvl": 6, "text": "Starting at 6th level, you are able to create pockets of peace and quiet. You can cast the silence spell without expending a spell slot {{charisma:modifier}} times per long rest. The radius of the spell if cast in this way is doubled."}, {"name": "Strong But Silent Type", "lvl": 14, "text": "At 14th level, your ability to empower others through silence fully awakens. Creatures that use your bardic inspiration gain the following benefits until the start of their next turn or until they speak.\r\n      Their AC increases by 2.\r\n      They gain {{level:bard}} temporary hit points.\r\n      They may deal {{charisma:modifier}} additional damage for one attack on their turn."}]}, {"id": "ID_RDDT_ARCHETYPE_COLLEGE_OF_CACOPHONY", "name": "College of Cacophony", "parentClass": "Bard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Booming Voice", "lvl": 3, "text": "Beginning at 3rd level, your voice is a booming force. Thunder damage you deal is unaffected by areas of silence. Your voice can be heard normally in areas if silence and in tough weather conditions. You cannot be magically silenced or deafened."}, {"name": "Create Cacophony", "lvl": 3, "text": "At 3rd level, you can use your bonus action to expend a Bardic Inspiration in order to create a kind of cacophonous noise inside the target's head.\r\n          Dissonance. A target you can see within 60ft of you starts hearing sour, dissonant notes. That creature must succeed on a wisdom saving throw or suffer disadvantage on its attack rolls until the end of its next turn.\r\n          Noise. A target within 60ft of you starts hearing loud distracting noises inside its head. If it is concentrating on a spell it must roll a concentration check at disadvantage or lose concentration. In addition any concentration checks it makes for the next minute are at disadvantage.\r\n          Growl. A target within 60ft of you starts hearing an aggressive primal sound. The creature must succeed on a wisdom saving throw or be frightened of you until the end of your next turn."}, {"name": "Thunderous Boom", "lvl": 6, "text": "Starting at 6th level, when you unleash powerful noises, you do so with extra ferocity. When you deal thunder damage you can reroll any die once taking the new roll. You may do this once per short rest."}, {"name": "Stunning Impact", "lvl": 14, "text": "At 14th level, your noises are too much for the ears of your targets to handle. When you deal thunder damage and roll maximum on at least one die, you can cause all creatures affected to make a constitution saving throw or be stunned until the end of its next turn on a failed save."}, {"name": "Drown Down", "lvl": 14, "text": "Starting at 14th level you gain the ability to react instinctively to disrupt magical incantations. When a creature you can see and hear within 60ft of you casts a spell with a vocal component, you can use your reaction to attempt to disrupt that spell. The target must make a concentration save or lose concentration on the spell and have it fail. They still expend the spell slot but the spell has no effect. You can do this once per long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_COLLEGE_OF_MANIFESTATIONS", "name": "College of Manifestation", "parentClass": "Bard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Artistic Projection", "lvl": 3, "text": "At 3rd level, you gain the ability to manifest your creative power into the world around you. As a bonus action, you can expend one of your Bardic Inspirations to summon one of the following artistic projections, following their rules for how they are used and summoned.\r\n      Barrier. You summon a wall of magical force within 30ft of you. The wall is up to 15ft wide, 10ft tall and 5ft thick. You can also have it or a circle of up to 10ft in diameter or a 10x10 square with the same height and thickness. You choose what the wall looks like. It has an AC of 15 and {{barrier:hp}} hit points. Creatures you choose can pass through it, others must destroy it first.\r\n      Guardian. You summon an interpretation of your desire to protect. You can summon a guardian and attach it to a creature you choose within 30ft. Once per turn, whenever the creature takes damage from an attack or spell, they can roll 1d{{bardic-inspiration:dice}} and decrease the damage taken by the amount rolled.\r\n      Weapon. You can summon a weapon of magical force within 30ft of you and make a melee spell attack with it. The attack deals your 1d{{bardic-inspiration:dice}} + {{level:bard}} in damage of a type of your"}, {"name": "Duet Performance", "lvl": 6, "text": "At 6th level, you can create illusory copies of people so real that they are almost in discernable from their real counterparts in both appearance and skills. If you perform for at least 1 minute, you can choose a creature that witnessed the whole performance and create an illusory duet of them. You choose what the duet is wearing, but its body is a complete replica of the subject. While the duet exists, it can interact with the world, it can walk, climb, talk and do any other mundane task other than make attacks or cast spells. It can also perform skill checks using the same bonuses as the original creature. Once it performs 4 checks (not including perception or stealth),it takes damage or 8 hours have passed the duet dissipates into smoke. You can summon a duet once per short rest."}, {"name": "Manifesting Performance", "lvl": 14, "text": "By 14th level, your mastery of your artistic projections allows you to spend time creating larger and larger projections over longer periods of time. If you perform for at least 1 minute, you can summon a gargantuan or smaller object within 120ft of you. The object can be anything from a large rock or statue, a small structure, a section of a castle wall or other things created in the bard's imagination. The object remains for {{level:bard}} hours. It has an AC of 15 and {{manifestation:hp}} hit points . If it is reduced to zero hit points, or you use this feature again, it dissipates and all creatures in or on the object fall harmlessly to the ground. You can use this feature once per long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_CIRCLE_OF_THE_RADIATION", "name": "Circle of Radiation", "parentClass": "Druid", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Circle Spells", "lvl": 2, "text": "Your body, mind, and spirit has been exposed to the profound feeling of becoming radioactive. This has seeped into your magic and has become part of your very being.\nAt 3rd, 5th, 7th, and 9th level you gain access to the spells listed for that level in the Circle of Radiation Spells table. Once you gain access to one of these spells, you always have it prepared, and it doesn't count against the number of spells you can prepare each day. If you gain access to a spell that doesn't appear on the druid spell list, the spell is nonetheless a druid spell for you."}, {"name": "Irradiated Spellcasting", "lvl": 2, "text": "At 2nd level, once per turn when you damage a creature you can see with a spell, you can choose to have the creature become Radioactive. A Radioactive creature emits a dim, greenish light in a 5-foot radius around them. This light makes it impossible for the creature to benefit from being invisible. A Radioactive creature must succeed on a Constitution saving throw at the end of each of their turns or take {{irradiated:die}}d6 radiant damage. On a success ending the effect is ended.\r\n\t\t\tWhen a Radioactive creature within 30 ft of you makes a Constitution, Dexterity, or Strength saving throw you may use your reaction to weaken them further. Roll a d4 and subtract the number rolled from the creature’s roll."}, {"name": "Wild Shape Mutations", "lvl": 2, "text": "Your radiation has mutated and infected your Wild Shape transformations, when you expend a use of your Wild Shape roll a d{{mutation:die}} and reference the Mutation table to see what mutation you develop.\r\n\t\t\tAlternatively, instead of rolling on the table, you may expend an extra use of your Wild Shape in order to choose any of the first four mutations on the Mutation Table to develop."}, {"name": "Nuclear Nullification", "lvl": 6, "text": "At 6th level you gain resistance to radiant damage."}, {"name": "Lethal Radiation", "lvl": 6, "text": "When a creature fails their Constitution saving throw to remove the Radioactive effect all creatures of your choice within 5 ft of them take {{wisdom:modifier}} radiant damage."}, {"name": "Radiation Sickness", "lvl": 10, "text": "At 10th level, creatures have disadvantage on saving throws to remove the Radioactive effect."}, {"name": "Arcane Half Life", "lvl": 14, "text": "Starting at 14th level as a bonus action you can start to emit radioactive waves from your body. Once activated you glow with dim greenish light in a 5-foot radius. This light makes it impossible for you to benefit from being invisible.\r\n\t\t\tWhen irradiated creatures are poisoned while within 10 ft of you and if a creature ends their turn within 10 ft of you they become Radioactive, immediately making the saving throw. You can choose to end this effect as a bonus action."}]}, {"id": "ID_RDDT_ARCHETYPE_CIRCLE_OF_THE_DRAGON", "name": "Circle of The Dragon", "parentClass": "Druid", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Emissary of the Dragon", "lvl": 2, "text": "You learn to speak, read, and write Draconic. In addition, you have advantage on saving throws against being charmed or frightened. While you can see a dragon, you ignore the effects of being charmed or frightened."}, {"name": "Circle Forms", "lvl": 2, "text": "The rites of your circle grant you the ability to transform into the most feared creatures in all the realms. You can use your Wild Shape to transform into a dragon with a challenge rating as high as {{circle forms:cr}}. This includes dragons you have not seen before. Additionally, you can transform into a dragon that has movement speeds from the Limitations column of the Beast Shapes table, but you cannot use those movement speeds until you’ve reached the appropriate druid levels shown on the table."}, {"name": "Frightful Transformation", "lvl": 6, "text": "Starting at 6th level, when you wild shape, your each creature of your choice within 10 feet must succeed a Wisdom saving throw against your Druid spell save DC or become frightened for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature's saving throw is successful or the effect ends for it, the creature is immune to the dragon's Frightful Presence for the next 24 hours."}, {"name": "Wild Draconic Form", "lvl": 10, "text": "At 10th level, you can expend two uses of Wild Shape to transform into a Druidic Dragon. When you do so, choose a type of dragon from the Draconic Essence table. Your breath weapon, damage immunity, and eye color while transformed are determined by the dragon type, as shown in the table."}, {"name": "Druidic Dragon Wings", "lvl": 14, "text": "At 14th level, you gain the ability to sprout a pair of Druidic Dragon Wings from your back, gaining a flying speed equal to your current speed. You can create these wings as a bonus action on your turn. They last until you dismiss them as a bonus action on your turn.\r\n\t\t\tYou can’t manifest your wings while wearing armor unless the armor is made to accommodate them, and clothing not made to accommodate your wings might be destroyed when you manifest them."}]}, {"id": "ID_RDDT_ARCHETYPE_CIRCLE_OF_THE_SANDS", "name": "Circle of Sands", "parentClass": "Druid", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Anger of the Sands", "lvl": 2, "text": "You have access to another option to use your wild shape feature - the sandstorm."}, {"name": "All is Dust", "lvl": 6, "text": "As reaction to taking being hit by an attack you can use your reaction to impose disadvantage on the attacker potentially turning the hit into a miss.\r\n\t\t\tYou can use this feature a {{proficiency}} times and regain all uses when you finish a short rest.\r\n\t\t\tAdditionally the size of you sandstorm form becomes huge and you deal 2d8 damage."}, {"name": "Wrath of the Dunes", "lvl": 10, "text": "At 10th. level the damage dealt by your Anger of the sands feature is increased to 3d8. Additionally the effect lasts for a number of minutes equal to your Wisdom modifier."}, {"name": "Hatred of the Desert", "lvl": 14, "text": "At 14th level, your ability to transform into a sandstorm is unmatched. As a Bonus Action you may choose to modify your form.\r\n\t\t\tEach of these modifications last until the end of your transformation. However when you take on one of these modifications you must begin to make concentration checks at the end of your turns. The DC for these checks is 10 plus twice the number of modifications you have active at that point."}]}, {"id": "ID_RDDT_ARCHETYPE_CHRONOKEEPER", "name": "Chronokeeper", "parentClass": "Rogue", "source": "Reddit : Unearthed Arcana", "summary": "You focus your training on the magical study of chronomancy, and use that time-manipulating magic to make it so things tend to go your way. Rather than learning spells as an Arcane Trickster does, you learn unique arcane techniques passed through Chronokeepers. Though, in rare cases, particularly prodigious rogues can learn these techniques without a mentor.", "features": [{"name": "Chronoshift", "lvl": 3, "text": "Starting at 3rd level, you may manipulate time in your favor. When you roll initiative, you mark your current location in space and time for up to 10 minutes. Once during these 10 minutes you may use your bonus action to teleport back to this location as long as it is unoccupied and within 60ft. Once you have teleported you gain sneak attack on your next hit as long as it is made before the end of your turn.\r\n            When you use this bonus action, once per long rest, you may choose to regain {{intelligence:modifier}} temporary hit points."}, {"name": "Hidden in Time", "lvl": 9, "text": "Starting at 9th level, you can leap back to a previous position as you conceal yourself from enemies. When you take the Hide action on your turn, you can choose to teleport to an unoccupied space within 15ft that you've occupied since the start of your last turn, before you make the Stealth check."}, {"name": "Forethought", "lvl": 13, "text": "At 13th level, you learn to call upon glimpses of the future. As a bonus action, you roll a d20, the next time you would roll a d20 this turn you can choose to use this roll rather than rolling.\r\n            You may use this feature {{intelligence:modifier}} times and you regain all expended uses of it when you finish a long rest."}, {"name": "Timesplit", "lvl": 17, "text": "Starting at 17th level, you learn to use your chronomatic abilities to split your reality into two separate timelines, and then take the better of the two. At the start of a turn, you can choose to activate this feature. After you do so, you complete your turn as normal. When that turn ends, however, you immediately repeat the turn rather than moving on to the next one. You begin the turn again in the same state as you started it, and the world around you is returned to that state as well. You then complete the turn again, potentially taking different actions and creating new outcomes.\r\n            At the end of the second turn, you choose one of the two turns This turn fully completes, and all actions and outcomes become finalized, whereas the other turn is disregarded as if it never happened. However both yourself and all other creatures are aware of the fact that it happened and whatever events ocurred within it.\r\n            Once you use this feature you cannot use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_WIND_THIEF", "name": "Wind Thief", "parentClass": "Rogue", "source": "Reddit : Unearthed Arcana", "summary": "Rogues of the Wind Thief archetype are swift and precise. They dash past without warning, strike at a weakpoint and dash away in he blink of an eye.", "features": [{"name": "Swiftness of the Wind", "lvl": 3, "text": "Starting at 3rd level, your speed increases by 10ft, opportunity attacks made against you are made with disadvantage whilst you aren't wearing armour heavier than light."}, {"name": "Strike of the Wind", "lvl": 9, "text": "Starting at 9th level, if you move 15ft or more in a straight line before attacking, you gain advantage on the attack roll.."}, {"name": "Slippery like the Wind", "lvl": 13, "text": "At 13th level, you've mastered the wind's incorporeal nature. As an action, you can slip out of being grappled. Though a space no smaller then 3 inches by 3 inches, or through a cracked door or window. Once you use this feature you can't use it again until you finish a short rest."}, {"name": "Born of Flame", "lvl": 17, "text": "Starting at 17th level, you can use your wind techniques to avoid what would otherwise be certain doom. If you are hit by an attack or spell, or fail a saving throw against an area effect such as fireball, you can turn the hit not a miss or a failed save into a success. Once you use this feature you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_ASH_STALKER", "name": "Ash Stalker", "parentClass": "Rogue", "source": "Reddit : Unearthed Arcana", "summary": "Rogues of the Ash Stalker are a paranoid nightmare.", "features": [{"name": "Lying Ash", "lvl": 3, "text": "Starting at 3rd level, you can imitate the way ash lies unnoticed beneath a great fire. When you take the hide action, you can used an allied creature your size or larger for cover."}, {"name": "Smoky Eyes", "lvl": 9, "text": "Starting at 9th level, when you hit an enemy with a sneak attack, you can attempt to blur their vision. The target makes a constitution save against {{smokyeyes:dc}}. On a failure they are blinded until the end of your next turn."}, {"name": "Smoke Cloud", "lvl": 13, "text": "At 13th level, You've mastered your ashen abilities in a way that makes others think you've disappeared. As an action you can choose a point within 60ft range. You teleport to that location vanishing in a puff of smoke. You can use this feature twice per short rest."}, {"name": "Born of Flame", "lvl": 17, "text": "Starting at 17th level, You can return to your roots as part of a great fire. As an action, you can kick up a cloud of dust around you that glows like the embers of a fire. Any creatures within 15 ft of you have to make a dexterity save against {{flame:dc}}. On a failure they take 4d8 fire damage and are blinded until the end of your next time. On a success they take half damage and aren't blinded."}]}, {"id": "ID_RDDT_ARCHETYPE_FIGHTER_BLADEDANCER", "name": "Bladedancer", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "Bladedancers stand among the most harshly trained fighters, usually culled in a \"Trial by fire\". Forced into this life without say, bladedancers seek true perfection in hand-to-hand combat. Impervious to fear, pain and distractions these soldiers are a pinnacle of resilience, but also grace. Some prefer swinging a blade in each hand, and some prefer the added dexterity of wielding their weapons with two hands. Some may take a hundred years to truly master this technique and some may take a thous", "features": [{"name": "Remarkable Technique", "lvl": 3, "text": "Starting when you choose this archetype at 3rd level, Through harsh training you have learned to swing with precision, perfectly utilizing the weight of the weapon. Whenever wielding more than one melee weapon you suffer no penalties as long as the weapons don't have the heavy property. Additionally you gain a {{dexterity:modifier:half}} bonus to attack rolls with melee weapons."}, {"name": "Unrelenting", "lvl": 7, "text": "At 7th level, your harsh training has taught you the savagery of combat. You become immune to the afraid and charmed conditions, you also have advantage on saving throws against being put to sleep."}, {"name": "Superior Agility", "lvl": 10, "text": "At 10th level, you perfectly utilize advantages in combat. Whenever you have advantage on an attack roll you can choose instead to attack twice. If there are two sources that cause you to have advantage then you can attack three times or choose one of your two attacks to benefit from the advantage. This continues stacking for however many sources cause you to have advantage. A source of advantage is removed if you have a source of disadvantage and this too stacks."}, {"name": "Weakpoint", "lvl": 15, "text": "At 15th level, your experience in combat has granted you insight into the weakpoints of your enemies. You critical range increases by 1 (20 --> 19-20 etc.) Additionally if your attack roll surpasses the targets armour class by more than double their bonus you critical hit them.(eg an AC of 14 would have a bonus of 4 therefore an 22 would critical, an AC of 20 would require a 40 to critical without rolling a critical.)"}, {"name": "Godly Technique", "lvl": 18, "text": "At 18th level your complete mastery of bladedancing has granted you the power to hit with lethal precision. Whenever your attack roll hits with the weakpoint critical (surpasses double their ac bonus) and the target is below your maximum critical damage, they die instantly. When this happens all creatures that can see you within 60ft must make a DC{{technique:save}} wisdom saving throw or become frightened of you."}]}, {"id": "ID_WOTC_XGTE_ARCHETYPE_FIGHTER_STONE_WARRIOR", "name": "Stone Warrior", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "Fighters of the Stone Warrior archetype exemplify the pinnacle of resilience and persistance They model themselves after the stone's raw durability and strength, but also its versatility. On top of boasting incredible defense, they learn techniques that are useful in a wide array of situations.", "features": [{"name": "Sentinel of Stone", "lvl": 3, "text": "Starting when you choose this archetype at 3rd level, you've taken on the unmoving nature of stone. You have advantage against saving throws to resist being stunned or frightened and have immunity to being petrified."}, {"name": "Toughness of Granite", "lvl": 7, "text": "At 7th level, you embody the resilience of stone. If you end your turn without moving you +2 to your AC until the start of your next turn."}, {"name": "Impassibility of Sandstone", "lvl": 10, "text": "At 10th level, you can imitate how difficult it is to move through certain rocks. When you hit a creature with a melee attack you can \"weigh it down\". If you do so, its walking speed is halved and it can't take reactions until the start of your next turn. You can use this feature 3 times per short rest."}, {"name": "Sharpness of Obsidian", "lvl": 15, "text": "At 15th level, you can embody the jagged and sharp edges of volcanic glass. When you take damage from an enemy within melee range you can use your reaction to counter attack and make a melee strike against that creature."}, {"name": "Master of Stone", "lvl": 18, "text": "At 18th level you understand the true nature of stone. As an action, you can turn yourself into stone for 1 minute or until you use a bonus action to break it. This is not petrification and you are still able to function normally but gain the following benefits: \r\n\t\t\tYou gain resistance to slashing, piercing, cold, fire and psychic damage. \r\n\t\t\tYou have immunity to poison and necrotic damage. \r\n\t\t\tThe bonus AC given by Toughness of Granite is +5. \r\n\t\t\tWhen you use Impassibility of Sandstone feature the creature has its speed reduced to 0. \r\n\t\t\tWhen you use your Sharpness of Obsidian feature you deal an additional 2d8 damage."}]}, {"id": "ID_RDDT_ARCHETYPE_FIGHTER_LIGHTING_STRIKER", "name": "Lightning Striker", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "Being masters of fast combat Lighting Strikers excel in ending a fight as fast as possible.", "features": [{"name": "Honed Reflexes", "lvl": 3, "text": "When you choose this archetype at 3rd level, you can't be surprised additionally you gain advantage on initiative."}, {"name": "Quick-Draw Style", "lvl": 3, "text": "If you haven't made a melee attack against a creature that hasn't made an attack against you yet you gain advantage on that attack. Additionally any non heavy weapon counts as finesse for you."}, {"name": "Burst Movement", "lvl": 7, "text": "At 7th level you have mastered you agility. You can take the dash action as a bonus action, if you take the dash action it is coupled with the disengage action as part of the same bonus action. Additionally when you move you can walk across liquids and vertical surfaces, if you end your turn on one of these surfaces you fall as normal. When you long jump the distance is doubled."}, {"name": "Flash Attack", "lvl": 10, "text": "At 10th level, you've learned to use your momentum when you attack. When you attack with advantage due to Quick-Draw Style or directly after you move you add 1d6 lightning damage to your attack."}, {"name": "Path of Least Resistance", "lvl": 15, "text": "At 15th level you've taken on lightning's ability to move quickly from place to place. When you hit an enemy with your Flash attack, if there are enemies within range of your speed you can move to the nearest one and make another flash attack. If the attack hits you can continue to do this as long as you do not miss and each new creature you have not struck that round. You can use this feature once per short rest."}, {"name": "Bolt Strike", "lvl": 18, "text": "At 18th level you've mastered the art of finishing the fight in a single strike. Choose a point within 100ft of you, you move in a straight line to this point making a melee attack on anyone within 5ft of you when you move. If you hit you add an additional 4d6 lightning damage, in this movement you ignore attacks of opportunity. Once you use this feature you can't again until you've finished a short rest."}]}, {"id": "ID_RDDT_ARCHETYPE_FIGHTER_GLADIATOR", "name": "Gladiator", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "A Gladiator isn't all about combat; the fierce fighter of the arena thirsts for recognition, and the right to boast their strength. When the people see you and the style of your form and armour, they know your fighting style, your specialty, and how you are a force to be feared.", "features": [{"name": "Gladiator Build", "lvl": 3, "text": "When you choose this archetype at 3rd level you gain a specialty in one of the following fighting styles:"}, {"name": "Irresistible Challenge", "lvl": 3, "text": "Starting at 3rd level, you can use your bonus action to cast Compelled Duel, or cast it as part of your second wind feature. The dc is {{challenge:dc}}. You don't have to maintain concentration on the spell. You can use this feature once per short rest."}, {"name": "Win The Crowd", "lvl": 7, "text": "At 7th level, you add your proficiency bonus to intimidation check. Additionally you gain advantage on persuasion checks related to haggling the price of a key item of your Gladiator build. (Eg spears for hoplites.)"}, {"name": "Escalating Odds", "lvl": 10, "text": "At 10th level, you are inured to battles of attrition, eventually gaining the upper hand against your opponent by memorizing the flow of combat. During combat, at the end of each of your turns you gain an Escalating Odds point. You can spend any Escalating Odds points you have to gain a +1 to an attack roll, you can spend any number of points on a single attack. Any time you lose consciousness or combat ends you lose any escalating Odds points."}, {"name": "Ardent Recognition", "lvl": 15, "text": "At 15th level, you become an icon of combat and glory. Whenever a creature witnesses you kill another creature, and knows your name, it will be able to recall you perfectly for the next decade. Additionally you can spend ten minutes gathering information on a person. The amount of information you can find or recall is directly linked to any combat experience that you may have had with them. The amount of information, if any, is up to the discretion of the DM."}, {"name": "Glorious Moment", "lvl": 18, "text": "You learn this feature at 18th level. A Gladiator's battle should not end without their moment of glory; an act of emboldening prowess that anyone would pay to behold. Before your take the attack action on your turn you can choose one of the following:\n\t\t\t\t\tMoment of Finality. You discard all hesitation and place all your strength into one decisive strike, hoping to end the battle. You make one attack against a creature within reach, you forgo any additional attacks you would normally gain as part of the attack action. For each attack you forgo you add a +5 to your damage roll. Additionally when you hit your roll as if you had landed all strikes you would normally make in the attack action.\n\t\t\t\t\tMoment of Splendor. You flourish your weapon, preparing to make a spectacle out of your opponent. After you finish your last attack with the attack action all creatures within 60ft of your that can see you must make a wisdom save. The DC for this is {{challenge:dc}}. If the creature has been attacked by you this turn then it automatically succeeds. If a creature fails they become charmed by you for 1 minute.\n\t\t\t\t\tMoment of Vehemence Your display of zeal and combat fervor strikes fear into m"}]}, {"id": "ID_WOTC_XGTE_ARCHETYPE_FIGHTER_STANDARD_BEARER", "name": "Standard Bearer", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "All soldiers are trained to withstand the perils and distress of war. A few are trained to maintain morale and act as a symbol for all allies to push forward. Anyone can carry a flag into battle, but only a standard-bearer can make the best of their position on the battlefield to ensure victory for their allies.", "features": [{"name": "Bonus Proficiencies", "lvl": 3, "text": "When you choose this archetype at 3rd level, you gain proficiency in Weaver's Tools and your choice of Deception, Intimidation, Performance or Persuasion."}, {"name": "Battle Standard", "lvl": 3, "text": "When you adopt this subclass you gain a war glag known as a battle standard. Wearing your battle standard or attaching it to any polearm counts as wielding it. All battle standards are designed to inspire your allies and bear a symbol upon them. A battle standard costs 5gp to make and can either be tailored at a shop or made using Weaver's tools during a long rest."}, {"name": "Inspire", "lvl": 3, "text": "At 3rd level as an Action, while wielding your battle standard, all allied creatures within 30ft of you that can see you are inspired. These creatures gain a bonus +{{charisma:modifier}} to weapon damage rolls until the start of your next turn. You can use this feature twice per short rest."}, {"name": "Stand Fast", "lvl": 7, "text": "At 7th level, while wielding your battle standard at the start of initiative, roll 1d10 + {{charisma:modifier}}. You and all allied creatures that can see your battle standard gain temporary hit points equal to the roll."}, {"name": "Invigorating Banner", "lvl": 10, "text": "At 10th level your battle standard acts as a reminder of your victories, reinvigorating your allies. As part of a short rest, you and all allied creatures that can see your battle standard can add {{charisma:modifier}} to every hit die spent to recover hit points"}, {"name": "Heraldry of Hope", "lvl": 18, "text": "At 18th level your presence on the battlefield bolsters your allies to endure under your banner. While wielding your battle standard, allied creatures other than yourself within 30 ft of you that make a saving throw may add {{charisma:modifier}} to that saving throw. They may do this once per round."}]}, {"id": "ID_RDDT_ARCHETYPE_FIGHTER_MAGE_SLAYER", "name": "Mage Slayer", "parentClass": "Fighter", "source": "Reddit : Unearthed Arcana", "summary": "Fighters that train with an order of Mage Slayers learn a variety of techniques to deal crushing blows to magic users, disrupting concentration and interrupting casting in a disciplined campaign to counter and disable an enemy caster.", "features": [{"name": "Slayer's Target", "lvl": 3, "text": "Starting when you choose this archetype at 3rd level, you can use your bonus action to mark an enemy you can see within 60ft of you. If they visibly attempt to cast a spell you can use your reaction to make an attack against that creature. On a hit they must make a concentration check at disadvantage. If they fail then the spell fails, it consumes a spell slot however there are no further effects. After 1 minute the target ends. You can use this feature {{level:fighter}} per short rest."}, {"name": "Devastating Strike", "lvl": 7, "text": "At 7th level, you learn to focus your attacks into fewer more powerful strikes. As an action you can make a single attack. If you hit, you roll double the dice."}, {"name": "Studied Hunter", "lvl": 10, "text": "At 10th level, if you spend at least one minute observing a creature, even if in combat, you can glean two pieces of information based off the ones below. The DM will reply either equal, inferior or superior in comparison to your own.\r\n\t\t\tCasting ability: the creatures casting ability (wisdom, intelligence or charisma) not in comparison to yours but which ability they use.\r\n\t\t\tCasting ability score: in comparison to your intelligence score\r\n\t\t\tCasters level: The casters level vs your total level\r\n\t\t\tConstitution saving throw: In comparison to your Constitution saving throw\r\n\t\t\tArmour class: compared to your armour class\r\n\t\t\tCurrent hit points: In comparison to your current hit points"}, {"name": "Predatory Focus", "lvl": 15, "text": "At 15th level, your singular focus on your target makes you harder to stop. When you mark a Slayer's Target until your next turn any spells they make against you are made at disadvantage and you have advantage on the saving throws."}, {"name": "Relentless Hunter", "lvl": 18, "text": "At 18th level your hunger to destroy your target increases. You can mark up to 5 targets with your Slayer's Target as long as you can see them regardless of the range, All benefits of Slayer's Target and Predatory Focus last until you drop them or loose sight of them for over a minute."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_GALVANIST", "name": "Galvanist", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "Some Artificers don't know when to stop. They tinker and they fiddle and they make a mess. But sometimes it is these less refined Artificers who end up changing the course of history. You must fail and fail gloriously if you want to make a real difference and that is what the Galvanist knows. They want to enhance and change magic in order to save the world.", "features": [{"name": "Conduit Caster", "lvl": 3, "text": "When you choose this archetype at 3rd level, you gain proficiency in Jewelers Tools and you learn the Lightning Lure and Shocking Grasp cantrips."}, {"name": "Galvanist Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the GALVANIST Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Galvan Battery", "lvl": 3, "text": "Starting at 3rd level you have discovered the way to create a Galvan Battery. A Galvan Battery is a small contraption of your design that gives off a dim light within a 5 ft radius and is either worn or embedded in armor and can be used as your spellcasting focus. It’s function is to try to contain extreme amounts of raw arcane power so that you can attempt to borrow and channel this energy to aid you in battle.\r\n\t\t\tUsing Jewelers Tools, you can take a bonus action to begin charging your Galvan Battery. The charge lasts for 1 minute unless it is removed from your contact or until the energy explodes.\r\n\t\t\tOnce activated it immediately gains 1 charge and gains an additional charge at the start of each of your turns. Your movement speed is increased by 5 ft for every charge your Galvan Battery currently has.\r\n\t\t\tOnce per turn, after you deal damage to a creature, you may deal additional damage to a creature with an attack or spell, you can deal an additional 1d8 lightning damage for each charge the Galvan Battery has to the target or a different creature within 15 ft of the target. In addition, if you roll the same number on any of the d8s, the Galvan Battery becomes unstable and the "}, {"name": "Alternating Current", "lvl": 5, "text": "Starting at 5th level When you are hit by an attack you can use your reaction to reduce the damage taken by {{intelligence:modifier}} and then you can choose to have a branch of electricity shoot back to the attacker if they are within 60 ft and they take {{intelligence:modifier}} lightning damage."}, {"name": "Arcane Accumulator", "lvl": 9, "text": "At 9th level, your Galvan Battery can store and expend incredible amounts of arcana at a moments notice allowing you to adapt to many situations:\r\n\t\t\t• Any spell you cast ignores resistance to lightning damage and treats immunity to lightning damage as resistance to lightning damage.\r\n\t\t\t• When you roll for extra damage with your Galvan Battery feature you may add an extra dice that is being rolled and after rolling discard one dice of your choice. You may use this feature {{proficiency}} times and you regain all uses on a long rest."}, {"name": "Voltaic Surge", "lvl": 15, "text": "Once you have reached 15th level, you have learned how to make your Galvan Batteries greatest failure into your biggest success:\r\n\t\t\t• The additional damage from Galvan Battery increases to 1d10 for each charge.\r\n\t\t\t• Once per long rest if you fall unconscious while your Galvan Battery is active you can expend all your charges to shock yourself back to life and regain consciousness with 1 health and an additional 1d8 temporary hit points for each charge of the Galvan Battery expended."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_AERONAUT", "name": "Aeronaut", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "One of the most dangerous obsessions an artificer can pursue has always been mechanical flight. Many strive for this lofty goal, and all but the most dedicated, and often the most foolhardy, artificers fail in their pursuits. Experiments that end in disastrous explosions, catastrophic falls from the sky, and deadly malfunctions are not out of the norm for an Aeronaut perfecting their mechanical flying machine. You constantly strive to achieve the lofty goal of every Aeronaut, the creation of an ", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt this specialization at 3rd level, you gain proficiency with woodcarver's tools. If you are already proficient with woodcarver's tools you instead gain proficiency with one type of artisan's tools of your choice."}, {"name": "Aeronaut Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Aeronaut Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Flying Machine", "lvl": 3, "text": "Upon reaching 3rd level, your experiments with flight have paid off. At the end of a long rest, as long as you have access to your woodcarver's tools, you can construct a flying machine, choosing its appearance. Your flying machine is a magical item that requires attunement and can be used as a spellcasting focus for your artificer spells. It is constructed to fit your size, and It can be worn over normal clothing and light or medium armor. You must spend time during each long rest maintaining your flying machine with woodcarver's tools. If you do not, your flying machine ceases to function.\r\n\t\t\tWhile you have your flying machine equipped and attuned, you gain a {{flying machine:speed}} foot flying speed. This flying speed does not stack with flying speeds gained from other features or spells."}, {"name": "Airborne Assault", "lvl": 5, "text": "Your flying machine allows you to attack from unorthodox positions to inflict more damage. Starting at 5th level, when you have your flying machine equipped and are at least 5 feet off the ground, your attacks deal an additional 1d8 damage.\r\n\t\t\tIn addition, if you become prone or restrained while flying with your flying machine, you remain in place in the air. If you are incapacitated, you fall at a rate of 10 feet per round."}, {"name": "Aerial Maneuvers", "lvl": 9, "text": "You have greatly improved the maneuverability of your flying machine. Beginning at 9th level, you can use the Dash action as a bonus action on your turn. You can dash in this way {{proficiency}} times, and regain all expended uses when you finish a long rest.\r\n\t\t\tIn addition, while you have your flying machine equipped, you gain a +{{intelligence:modifier}} bonus to your Dexterity ability checks and saving throws."}, {"name": "Master Aeronaut", "lvl": 15, "text": "Upon reaching 15th level, become an Aeronautical expert. If have your flying machine equipped and you are subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw, and only half damage if you fail."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_OPERATIVE", "name": "Operative", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "An Operative is an artificer who uses their genius to infiltrate an organization, steal information, and escape into the night. Operatives are often hired as spies or even assassins, selling their considerable talents to rival orders, wealthy merchants, and anyone else who can afford their price.", "features": [{"name": "Operative Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Operative Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Chameleon Engine", "lvl": 3, "text": "At 3rd level, you construct a chameleon engine: a device you can use to cloak your appearance. Your chameleon engine is a Tiny object; you decide your engine's appearance.\r\n\t\t\tWhile your chameleon engine is on your person, you can use your action and expend a spell slot of 1st level or higher to activate it. Your engine remains active for 1 hour, or until it is more than 5 feet away from you. As a bonus action, you can use your activated engine in one of the following ways:\r\n\t\t\t• You make yourself—and anything on your person—look different. You can't alter your height or width by more than 1 foot, and you can't change your body type. Touching your disguise reveals it to be illusory, because things can pass through it. Otherwise, you can look however you like.\r\n\t\t\t• You blend into your surroundings, becoming invisible until you move, or until you take an action or reaction. The first time you cast an artificer spell while invisible, you can roll 1d8 and add the result to one damage roll of the spell.\r\n\t\t\tAny of your engine's effects end early when it deactivates. You can activate your engine once without expending a spell slot. You can't do so again until you finish a long rest.\n\t\t\t"}, {"name": "Hidden Weapon", "lvl": 5, "text": "Starting at 5th level, if you have your thieves' tools with you when you finish a long rest, you can disguise an arcane focus as an ordinary trinket, such as a watch, cane, or quill, turning it into a hidden weapon. Your hidden weapon doesn't appear magical to spells and effects such as detect magic. It returns to its true form if you use this feature again, or if you die.\r\n\t\t\tYou can use your hidden weapon as a spellcasting focus. When you cast an artificer spell through the hidden weapon, you can add your Intelligence modifier to one damage roll of the spell. In addition, if the spell has verbal components, you can ignore them if the spell also has somatic components."}, {"name": "Backup Plan", "lvl": 9, "text": "Starting at 9th level, you can adapt to new situations on the fly. As an action, you can replace one of your prepared spells wth another spell you can prepare from the artificer spell list.\r\n\t\t\tAlternatively, you can use your action to end one of your artificer infusions and imbue a nonmagical object you touch with an infusion. If you replace an infusion, you can't imbue an object with that infusion again until you finish a long rest.\r\n\t\t\tYou can use this feature a number of times equal to your Intelligence modifier (a minimum of once), and you regain all expended uses when you finish a long rest."}, {"name": "Master Infiltrator", "lvl": 15, "text": "Starting when you reach 15th level, you master the use of your Chameleon Engine. You gain the following benefits:\r\n\t\t\t• When you use your engine to change your appearance, you can make your voice sound different for the duration. You can perfectly mimic the voice of another creature, or distort your voice enough to be unrecognizable.\r\n\t\t\t• When you use your engine to become invisible, moving doesn't cause you to become visible again."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_ATOMICIST", "name": "Atomicist", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "Masters of the Atom Atomicists are potent spellcasters and tinkerers who take advantage of the dangerous nature of toying with the building blocks of reality.", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "You gain proficiency with alchemist’s supplies. If you already have this proficiency, you gain proficiency with one other type of artisan’s tools of your choice."}, {"name": "Atomicist Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Atomicist Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Magical Radiation", "lvl": 3, "text": "At 3rd level, you learn how to use magic to split matter. As a bonus action using your tinkers tools, you can begin emitting a poisonous radiation for one minute. Creatures that move to within {{radiation:distance}} feet of you or begin their turn within five feet of you must make a Constitution saving throw against your spellcasting DC or take {{radiation:damage}}d10 radiant damage. You can end this effect with a bonus action, and this effect ends early if you are knocked unconscious.\r\n\t\t\tYou may use this effect {{proficiency}} times. You regain spent uses after a long rest.\n\t\t\tAdditionally at 3rd level, any time you cast a cantrip or spell that would deal fire, force, necrotic, or poison damage, you can instead have it deal radiant damage."}, {"name": "Protective Suit", "lvl": 5, "text": "You have developed a protective suit to shield yourself from the hazards of your magic. After a long rest, you can touch any set of armor and modify it into a protective suit. You are proficient with it while you are wearing it, and you have resistance to radiant and poison damage and have advantage on saving throws against poison.\r\n\t\t\tAdditionally, when you attack with a melee weapon, you deal {{intelligence:modifier}} radiant damage in addition to the weapon’s normal damage."}, {"name": "Poisonous Light", "lvl": 9, "text": "Any time you deal radiant damage, the target must make a Constitution saving throw against your spellcasting DC. If they fail, they are poisoned for one minute. They may re-attempt this saving throw on any of their subsequent turns as an action. If at any point, they succeed on this saving throw, they are immune to this effect for one hour."}, {"name": "Going Nuclear", "lvl": 15, "text": "By 15th level, your studies have made your mastery of the atom without compare. As an action, you may cast disintegrate as a 7th-level spell, except it deals radiant damage instead of force. You can do this once, and regain the ability to do this after a long rest or by choosing to gain a level of exhaustion."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_SIGILIST", "name": "Sigilist", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "There are some who toe the line between artificery and magic, manipulating the Wave through symbols of binding and protection. They specialize in crafting arcane glyphs which ward against harm, and while they are known by many names across many cultures, they're most commonly referred to as Sigilists.", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt the Sigilist specialty at 3rd level, you gain proficiency with calligrapher's supplies. If you already proficient with calligrapher's supplies, you gain proficiency with another set of artisan's tools of your choice."}, {"name": "Sigilist Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Sigilist Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Wardcrafting", "lvl": 3, "text": "You gain the ability to Inscribe items with various sigils of protection\n\t\t\tOver the course of a short rest, you can Inscribe {{proficiency:half}} wards. The total number of Inscribed wards can't exceed {{proficiency}}.\r\n\t\t\tA friendly creature with the ward on their person becomes its Bearer and gains benefits from its protection. When you Inscribe a ward, choose one of the following benefits.\r\n\t\t\t•Choose a skill or tool proficiency. Whenever the bearer makes an skill or tool check for the skill or tool you chose they may add a d4 to the roll.\r\n\t\t\t•Choose a damage type. Damage dealt by the bearer overcomes resistances to this type of damage.\r\n\t\t\t•Choose an artificer spell of a level for which you have spell slots. The bearer may use their spell slots to cast this spell at the inscribed level or higher.\r\n\t\t\tAdditionally, when the bearer of a ward is hit by an attack or fails a saving throw, you may use your reaction to destroy the ward in a burst of protective magic. Until the start of the Bearer's next turn, attack rolls against the Bearer have disadvantage.\r\n\t\t\tInscribed Wards fade after 24 hours if they are not destroyed beforehand."}, {"name": "Disrupting Sigil", "lvl": 5, "text": "Once per turn, when you damage a creature with an Artificer cantrip, you may use your bonus action to temporarily mark it with a disrupting sigil. Until the start of your next turn, whenever that creature makes an attack roll or saving throw they subtract a d4 from the roll. You may do this {{intelligence:modifier}} times per short rest."}, {"name": "Improved Wardcrafting", "lvl": 9, "text": "Your skill with creating magical sigils increases. You gain additional options when Inscribing wards:\r\n\t\t\t•Choose a damage type. The Bearer gains resistance to damage of that type\r\n\t\t\t•Choose an ability, whenever the Bearer makes an ability check or saving throw for that ability, they can add a d4 to the roll.\r\n\t\t\t•When you choose a damage type for the Bearer to ignore resistances of, it also now ignores immunities to that damage type.\r\n\t\t\t•Choose an Artificer cantrip. The Bearer can cast that cantrip using Intelligence as their spellcasting ability.\r\n\t\t\tAdditionally, the d4 from your Disrupting Sigil ability increases to a d6."}, {"name": "Barrier Ward", "lvl": 15, "text": "Your mastery with defensive sigilry enables you to create a perpetual shield around warded creatures. Each of your wards provides its Bearer with a pool of extra HP equal to your artificer level. Whenever the bearer would take damage they can choose to use the Wards HP. The ward doesn't have the same immunities and resistances as you, it is resistant to poison and force damage and nothing else."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_DUNGEONEER", "name": "Dungeoneer", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "While most focus on singular inventions, dungeoneers use their know-how to weaponize mundane objects. Trusted to safeguard untold riches and powerful artifacts, dungeoneers use basic adventuring gear to construct defensive traps, puzzles, and structures that can repel all but the most hardy adventurers. Did you learn your craft in the service of a powerful creature, or under the tutilage of a master?", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt the dungeoneer specialty at 3rd level, you gain proficiency with carpenter's tools and mason's tools. If you already proficient with either of these tools, you gain proficiency with another set of artisan's tools of your choice."}, {"name": "Dungeoneer Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Dungeoneer Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Dungeoncraft", "lvl": 3, "text": "Starting at 3rd level, when you finish a long rest, you can create {{proficiency}} objects from the Dungeoncraft Table. If an object forces a creature to make a saving throw they use your artificer spell save DC."}, {"name": "Resourceful Fighting", "lvl": 3, "text": "Beginning at 3rd level, you can arm yourself with whatever is around you, turning mundane objects into weapons. You gain proficiency with improvised weapons, and when you attack with an improvised weapon you can use your Intelligence, in place of Strength or Dexterity, for attack and damage rolls."}, {"name": "Extra Attack", "lvl": 5, "text": "Starting at 5th level, you can attack twice, rather than once, whenever you take the Attack action on your turn."}, {"name": "Arcane Improvisation", "lvl": 9, "text": "Starting at 9th level, when you cast a Dungeoneer Spell that has a material component, you can cast the spell without providing the material component. Once you use this feature you must finish a long rest before you can do so again.\r\n\t\t\tIn addition, your improvised weapons and Dungeoncraft objects are considered magic for the purpose of overcoming resistances and immunities."}, {"name": "Master Dungeoneer", "lvl": 15, "text": "You have become a master Dungeoneer. Upon reaching 15th level, when a creature makes a saving throw against one of your Dungeoncraft Objects or Dungeoneer Spells, they have disadvantage on their saving throw.\r\n\t\t\tIn addition you can cast the passwall and wall of stone spells as rituals. Their casting time becomes 1 hour, they don't consume spell slots, and the structure is permanent."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_ARCHIVIST", "name": "Archivist", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "For centuries chroniclers and librarians have sought the best way to store vast troves of information. While most were satisfied with scrolls, tomes, and books, the first archivists strove for something greater, storing libraries worth of information in one solitary object, and created the first artificial minds. As an archivist, you are on the cutting edge of arcane advancement. Like all new breakthroughs, you must be careful with who you allow to witness this ability. How will you use your fri", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt this specialization at 3rd level, you gain proficiency with calligrapher's supplies. If you already have proficiency with calligrapher's supplies you gain proficiency with another type of artisan's tools of your choice."}, {"name": "Archivist Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Archivist Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Artificial Mind", "lvl": 3, "text": "Starting at 3rd level, you can awaken artificial minds. At the end of each long rest, you can touch a Tiny nonmagical object with calligrapher's supplies, awakening a mind within. While the mind is inside it, the object is a magic item that requires attunement, and you can use it as a spellcasting focus. If you rouse an artificial mind while you already have one from this feature, the mind transfers to the new object. While attuned to the mind, you gain the following features:\r\n\t\t\tInformation Overload. Your artificial mind can overload the minds of your enemies with information. As an action, you can force a creature that you can see within 30 feet to make an Intelligence saving throw. On a failed save, it takes {{overload:damage}}d8 psychic damage and disadvantage on the next attack roll it makes before the start of your next turn.\r\n\t\t\tMagical Telephony. You can communicate telepathically with any creature carrying one of your infused items within a 1-mile radius. The creature can respond telepathically.\r\n\t\t\tSkill Proficiencies. You gain proficiency in two skills from the respective column on the table below. The material of the object that houses your artificial mind determines t"}, {"name": "Acute Overload", "lvl": 5, "text": "Starting at 5th level, when you deal psychic damage to a creature you gain a bonus +{{intelligence:modifier}} to the damage roll.\n\t\t\tIn addition, you can expend a spell slot to increase the psychic damage dealt by your Information Overload feature. The damage increases by 2d8 for a 1st-level spell slot, and an additional 1d8 for each spell level higher than 1st-level."}, {"name": "Improved Consciousness", "lvl": 9, "text": "The cognitive abilities of the artificial mind have grown and it can aid you in spellcasting. Starting at 9th level, when you are forced to make a Constitution saving throw to maintain concentration on a spell, you gain a bonus +{{intelligence:modifier}} to the saving throw."}, {"name": "Master Archivist", "lvl": 15, "text": "Upon reaching 15th level you have attained the peak of archival expertise. As an action on your turn, you can turn into pure information and teleport to an unoccupied space within 60 feet that you can see, or to an unoccupied space within 5 feet of an object bearing one of your infusions."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_COMPOSER", "name": "Composer", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "Behind every great musician, every standing ovation, every sold out concert, there is someone who put quill to parchment and penned the notes. These great minds are known as composers. Unlike other bards and entertainers, composers take a more mathematical and cerebral approach to music and song. They are masters of patterns that go unnoticed, and when they apply their analytical minds to a problem it is only a matter of time before they find a solution.", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt the composer specialty at 3rd level, you gain proficiency with smith's tools and one instrument of your choice. If you already proficient with smith's tools, you gain proficiency with another set of artisan's tools of your choice. At the end of a long rest, you can switch the instrument proficiency you gained from this feature with another instrument, provided you have the new instrument available."}, {"name": "Composer Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Composer Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Musical Apparatus", "lvl": 3, "text": "Starting at 3rd level, you construct a completely unique musical instrument of your own design. You are proficient and with this instrument and it can be used as a spellcasting focus by you. Whenever you make skill check with this apparatus you can add double your proficiency bonus to the roll. If it is destroyed, you can construct a new musical apparatus with your smith's tools at the end of a long rest.\r\n\t\t\tYou can only maintain one musical apparatus at a time, and if you create a new one, your previous musical apparatus falls into disrepair and becomes unusable. Your musical apparatus can also be weaponized depending on its design. At the end of each long rest, you can choose one of the following options for your musical apparatus:\r\n\t\t\tRaucous Blast. Your apparatus can assault creatures with a blast of painful sound. As an action, make a spell attack against a creature within 60 feet that can hear you. On hit the creature takes {{raucous:damage}}d8 thunder damage and is deafened until the start of your next turn. \r\n\t\t\tRinging Strike. Your apparatus is a simple weapon with the versatile property, and it deals 1d8 (1d10) bludgeoning damage on hit. You are considered proficient wit"}, {"name": "Thunderous Note", "lvl": 5, "text": "Starting at 5th level, when you deal thunder damage to a creature you gain a bonus +{{intelligence:modifier}} to the damage roll.\r\n\t\t\tIn addition, when you attack with your musical apparatus, you can expend a spell slot to knock the target back. The creature is knocked back 10 feet for a 1st-level spell slot, and an additional 10 feet for each spell level higher than 1st."}, {"name": "Resonant Frequency", "lvl": 9, "text": "Beginning at 9th level, as an action you can play a note at a pitch that causes a creature of your choice within 10 feet to resonate with undetectable vibrations for 1 hour. The next time that creature is hit with a melee attack, the attacker must make a Constitution saving throw. On a failed save, they take 2d8 thunder damage and cannot take reactions until the beginning of their next turn. On a successful save they take half damage and can use their reaction as normal.\r\n\t\t\tYou may use this feature {{intelligence:modifier}} times, and you regain all expended uses when you finish a long rest."}, {"name": "Master Composer", "lvl": 15, "text": "You have mastered both the theory and applications of sound and used this knowledge to improve the effectiveness of your musical apparatus and your composer techniques. Upon reaching 15th level, you gain the following features:\r\n\t\t\t•You are immune to thunder damage and the deafened condition.\r\n\t\t\t•You can change the weaponized effect of your musical apparatus at the end of a short or long rest.\r\n\t\t\t•When you use your Thunderous Note feature Large or smaller are knocked prone.\n\t\t\t•The damage of Resonant Frequency becomes to 4d8."}]}, {"id": "ID_RDDT_ARCHETYPE_ARTIFICER_FORGEWRIGHT", "name": "Forgewright", "parentClass": "Artificer", "source": "Reddit : Unearthed Arcana", "summary": "While most artificers are primarily inventors that take up a life of adventure to further their research or test experiments in the field, those known as forgewrights seek out battle for its own sake. Reveling in the thrill of combat, they combine their innovative spirit with their skill as a warrior to forge the signature weapon of a forgewright, an arcane armament.", "features": [{"name": "Tools of the Trade", "lvl": 3, "text": "When you adopt the forgewright specialty at 3rd level, you gain proficiency with smith's tools and martial weapons. If you are already proficient with smith's tools, you gain proficiency in another set of artisan's tools of your choice."}, {"name": "Forgewright Spells", "lvl": 3, "text": "Starting at 3rd level, you always have certain spells prepared after you reach particular levels in this class, as shown in the Forgewright Spells table. These spells count as artificer spells for you, but they don’t count against the number of artificer spells you prepare."}, {"name": "Arcane Armament", "lvl": 3, "text": "Your intimate knowledge of warfare and arcane magic allows you to combine both with ease. Starting at 3rd level, you learn to forge an arcane armament. At the end of each long rest, you touch one melee weapon and turn it into your arcane armament, granting it the following properties:\r\n\t\t\t•The weapon you is considered magic if it was not already.\r\n\t\t\t•You can use your Intelligence, in place of Strength or Dexterity, for the attack and damage rolls.\r\n\t\t\t•You gain a +{{armament:damage}} bonus to your attack and damage rolls with it, unless the base weapon granted a higher bonus.\r\n\t\t\t•It can bear one of your infusions, even if it was already a magic item before becoming your arcane armament.\r\n\t\t\t•Bonuses to attack an damage rolls innate to the weapon, or from an infusion, do not stack with the bonuses from this feature. You must choose one instance to use.\r\n\t\t\tYour arcane armament is usable only by you. Enchanting a second weapon causes the magic in the first to end."}, {"name": "Extra Attack", "lvl": 5, "text": "You wield your arcane armament as an extension of yourself. Starting at 5th level, you can attack twice, rather than once, whenever you take the Attack action on your turn."}, {"name": "Arcane Smite", "lvl": 9, "text": "Your connection with your arcane armament has grown, allowing you to enhance your strikes. Beginning at 9th level, when you hit a target with a magic weapon attack you can channel magical energy through your arcane armament to create one of the following effects:\r\n\t\t\t•The target takes an extra 2d6 force damage. You can expend a spell slot to increase this damage. The damage increases by 1d6 per level of the spell slot you expend.\r\n\t\t\t•You gain {{level:artificer}} temporary hit points.\r\n\t\t\t•You can force the target to make a Strength saving throw. On a failed save they are knocked prone.\r\n\t\t\tYou can use this ability a number of times equal to your Intelligence modifier (minimum of once), and you regain all expended uses when you finish a long rest."}, {"name": "Master Forgewright", "lvl": 15, "text": "You have become a master among forgewright artificers, and your Arcane Armament is a legend among magic weapons. Upon reaching 15th level, you can extend the power of your arcane armament to your allies. As an action, choose {{intelligence:modifier}} weapons within 30 feet. For the next minute these weapons deal an additional 1d6 force damage on hit.\r\n\t\t\tYou can use this feature once per long rest, unless you spend a spell slot of 3rd-level or higher to use it again."}]}, {"id": "ID_RDDT_UA_ARCHETYPE_CLERIC_DIVINE_DOMAIN_IMMORTALITY", "name": "Immortality Domain", "parentClass": "Cleric", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Domain Spells", "lvl": 1, "text": "You gain domain spells at the cleric levels listed in the Immortality Domain Spells table. See the Divine Domain class feature for how domain spells work."}, {"name": "Immortal Sect", "lvl": 1, "text": "When you choose this domain at 1st level, you must choose the sec you follow when pursuing Immortality. Diving Body or Divine Wisdom."}, {"name": "Immortal Defenses", "lvl": 1, "text": "At 1st level, your unarmoured AC is equal to 12 + wisdom modifier"}, {"name": "Channel Divinity: Immortal Form", "lvl": 2, "text": "As an action you can channel your divinity to enter your immortal form for 1 minute. The benefits of your immortal form are dictated by your immortal sect."}, {"name": "Summoning the Divine Peach Tree", "lvl": 6, "text": "At 6th level, as an action, you can summon an immortal peach tree to an empty space within 30ft of you for 1 hour. The peach tree grows instantly to 10ft tall and blossoms with pink flowers. When you or an ally reduce a creature to 0 hit points within 60ft of the tree that creature's life force is absorbed and they become a peach on the tree. A peach remains fresh for one hour and eating one grants a number of benefits as long as you are within 100ft of the tree. When a creature eats a peach they can choose one of the following benefits.\r\n\t\t\tHave lesser restoration cast on them.\r\n\t\t\tRegain 2d4 + your wisdom modifier hit point.\r\n\t\t\tGain advantage on saves against the poisoned condition for the next 24 hours.\r\n\t\t\tYou may only eat one peach per 24 hours."}, {"name": "Immortals Blessings", "lvl": 8, "text": "Starting at 8th level you gain benefits based off your immortal sect."}, {"name": "True Immortal", "lvl": 17, "text": "At 17th level, you gain the spell invulnerability and it counts as a cleric spell for you, it does not count against the number of spells you can have prepared. Additionally you do not age and can choose what age you appear. You gain additional benefits dependent on your immortal sect."}]}, {"id": "ID_RDDT_UA_ARCHETYPE_CLERIC_DIVINE_DOMAIN_LUCK", "name": "Luck Domain", "parentClass": "Cleric", "source": "Reddit : Unearthed Arcana", "summary": "There are deities of good and deities of evil. Then there are those who decide that chance is the greatest mediator of good and evil. Clerics of the luck domain embrace this mediator, their holy symbols often reflect this, being playing cards or roulette balls.", "features": [{"name": "Domain Spells", "lvl": 1, "text": "You gain domain spells at the cleric levels listed in the Luck Domain Spells table. See the Divine Domain class feature for how domain spells work."}, {"name": "Bonus Proficiencies", "lvl": 1, "text": "When you choose this domain at 1st level you gain proficiency in the gaming sets and improvised weapons"}, {"name": "Tip the Scales", "lvl": 1, "text": "When you cast a spell that targets a friendly creature they have advantage on their next roll that requires a d20."}, {"name": "Channel Divinity: Stroke of Luck", "lvl": 2, "text": "Starting at 2nd level you start to get the hang of luck. When friendly creatures are forced to make a saving throw you can use your reaction to grant a number of creatures = {{wisdom:modifier}} advantage on the saving throw."}, {"name": "Lucky Streak", "lvl": 6, "text": "You score a critical hit on a 7 or 20 but a critical fail on a 13 or 1."}, {"name": "Potent Improvisation", "lvl": 8, "text": "Starting at 8th level you add {{wisdom:modifier}} to attack and damage rolls with improvised weapons. Additionally once per turn with an improvised weapon you can deal an additional 1d8"}, {"name": "Arcane Roulette", "lvl": 17, "text": "Starting at 17th level you can push your luck to the extreme. You can use your action once per long rest to use arcane roulette. Roll a 1d10 and the 9th level spell listed takes effect as if a cleric spell for you. You must choose a target before you roll."}]}, {"id": "ID_RDDT_UA_ARCHETYPE_CLERIC_DIVINE_DOMAIN_MADNESS", "name": "Madness Domain", "parentClass": "Cleric", "source": "Reddit : Unearthed Arcana", "summary": "The domain of madness celebrates the variety of shapes the mind can take, reveling in the truth and freedom of madness. Many of the gods of madness are considered Evil by nature but that isn't quite true. However a lawful madness god doesn't exist", "features": [{"name": "Domain Spells", "lvl": 1, "text": "You gain domain spells at the cleric levels listed in the Madness Domain Spells table. See the Divine Domain class feature for how domain spells work."}, {"name": "Bonus Cantrip", "lvl": 1, "text": "When you choose this domain at 1st level you gain Vicious Mockery cantrip"}, {"name": "Divine Hallucinations", "lvl": 1, "text": "At 1st level you can use an action to enter a trance. you become incapacitated for 1 minute and begin to see visions. The DM rolls a d6 in secret, on a 5 or 6 the vision shows a real threat, on a 1 to 4 the vision shows a fake threat. you can do this a number of times equivalent to {{wisdom:modifier}} times per long rest"}, {"name": "Gift of Madness", "lvl": 1, "text": "Immediately after a creature hits you you can use your reaction to force them to suffer from your madness. They must make a wisdom saving throw against your spell save, on a failed save they take 2 + {{level:cleric}} psychic damage and are frightened till the end of your next turn. You can use this a number of time equivalent to {{wisdom:modifier}} times per long rest."}, {"name": "Channel Divinity: Dread Whispers", "lvl": 2, "text": "As an action you choose a point you can see within 60 feet. Each creature within 10ft of the point must make a wisdom saving throw. on a failed saving throw they take 1d6 + {{level:cleric}} psychic damage and becomes frightened for 1 minute. In this frightened state it treats all other creatures as enemies."}, {"name": "Crazed Stumbling", "lvl": 6, "text": "Starting at 6th level When you deal psychic damage to a creature you can force it to walk up to 10ft in any direction."}, {"name": "Potent Spellcasting", "lvl": 8, "text": "Starting at 8th level you can add {{wisdom:modifier}} to any damage you deal with a cleric cantrip."}, {"name": "Already Mad", "lvl": 17, "text": "At 17th level you can't be frightened or charmed and you have immunity to psychic damage."}]}, {"id": "ID_RDDT_UA_ARCHETYPE_CLERIC_DIVINE_DOMAIN_PLAGUE", "name": "Plague Domain", "parentClass": "Cleric", "source": "Reddit : Unearthed Arcana", "summary": "Mortals have long viewed Plague as a tool of the gods, clerics of the Plague domain are given the ability to become harbingers of this great death.", "features": [{"name": "Domain Spells", "lvl": 1, "text": "You gain domain spells at the cleric levels listed in the Plague Domain Spells table. See the Divine Domain class feature for how domain spells work."}, {"name": "ID_RDDT_UA_ARCHETYPE_FEATURE_DIVINE_DOMAIN_PLAGUE_BLESSING_OF_MALADAY", "lvl": 1, "text": ""}, {"name": "Plague Doctor", "lvl": 1, "text": "At 1st level, you can imbue your healing magic with purifying magic, when you heal a creature you also purge one poison or disease that affects them. You can do this {{wisdom:modifier}} times per long rest"}, {"name": "Channel Divinity: Unleash The Plague", "lvl": 2, "text": "As a reaction when you deal poison or necrotic damage you can use your reaction to infect it with one of the following diseases that lasts a number of days equivalent to your cleric level. The target can make a constitution save every hour it is infected to fight the disease, this includes when you use your channel divinity. THe options are: Atrophy, Lethargy, Migraine, Nausea, Necrosis and Psychosis"}, {"name": "Black Death", "lvl": 6, "text": "By 6th level the blessing of your deity allows you afflict those who would normally resist your attacks. Whenever you cast a spell that deals poison or necrotic damage you can switch the damage type to necrotic or poison. Your spells can cause the poisoned condition to targets that are immune to the poisoned condition as long as they are not also immune to necrotic damage. If they are immune to both you can't overcome their poisoned immunity. The disease caused by Unleash the Plague is considered non magical and can't be dispelled by antimagic field or other such effects."}, {"name": "Potent Spellcasting", "lvl": 8, "text": "Starting at 8th level you can add {{wisdom:modifier}} to any damage you deal with a cleric cantrip."}, {"name": "Harbinger Of Pestilence", "lvl": 17, "text": "At 17th level you are able to walk amongst the sick with impunity and are a master of spreading sickness to others. You are immune to poison damage and the poisoned condition. Additionally if a hostile creature dies whilst suffering from one of your plagues you regain that use of channel divinity."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_FOCUS", "name": "Path of Focus", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Many barbarians use their raw rage and adrenaline to display martial prowess, but there are also how through force of will learn to control this rage to temper it into a much more terrifying force.", "features": [{"name": "Contain The Fury", "lvl": 3, "text": "Starting at 3rd level, you learn to temper your fury. Instead of entering a rage you may instead enter a focused rage. You do not gain the standard rage benefits, instead you gain the following benefits:\r \n            You may add your rage damage bonus to the first attack roll you make on your turn.\r\n            You deal a critical hit on a 19 or 20. \r\n            You may take the disengage and dash actions as a bonus action."}, {"name": "Hone The Spirit", "lvl": 6, "text": "At 6th level, your focused and disciplined nature allows you to shake off most brutal blows. Whenever you're hit by a critical hit you can use your reaction to reduce it to a normal hit. When you do this your next attack has advantage as your senses hone from the pain."}, {"name": "Feed The Beast", "lvl": 10, "text": "At 10th level, you have learned to control your rage but understand the merit of occasionally allowing its reckless nature to take hold. Now all attacks add your Rage Damage bonus to the attack roll and damage."}, {"name": "Master The Focus", "lvl": 14, "text": "At 14th level, Your ability to use your rage to ground yourself rather than give in has reaped additional benefits. When you enter a focused rage whenever you deal a critical hit you gain 2d12 hit points additionally uo score a critical hit on an 18-20."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_TITAN", "name": "Path of The Titan", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "For some, the size of mortal weapons is a suggestion rather than a limitation.", "features": [{"name": "Titanic Might", "lvl": 3, "text": "Starting at 3rd level, you gain a great strength within yourself. When not raging with a strength score of 16 or greater, you can engage in two weapon fighting with two weapons even if they don't have the light property, as long as they don't have the heavy or two handed property. \r\n            With a strength score of 18 or higher while not raging, you can use a two handed weapon in one hand however you have disadvantage on attack rolls. \r\n            With a strength score of 20 or higher, while not raging you can engage in two weapon fighting with two, one-handed heavy weapons."}, {"name": "Titanic Rage", "lvl": 3, "text": "Starting at 3rd level, once per long rest you can enter a titanic rage. In this state you gain all the benefits of titanic might, (can engage in two weapon fighting with two, one-handed heavy weapons, and can use a two handed weapon in one hand at disadvantage). Additionally you can increase the range of any thrown weapons by double and can now throw any weapon without the thrown property with a (20/60) range. You do not apply proficiency bonus with this throw even if you are proficient with the weapon you are throwing."}, {"name": "Grim Determination", "lvl": 6, "text": "At 6th level, you have advantage on saving throws against being charmed or frightened whilst raging."}, {"name": "Rend", "lvl": 6, "text": "At 6th level, if on your turn you hit a creature with consecutive attacks using two different two handed weapons, you can make the creature take additional damage equal to your {{barbarian rage:damage}}."}, {"name": "Dread Maneuver", "lvl": 10, "text": "At 10th level, you can perform awesome attacks during your titanic might rage. You can perform the following maneuvers.\r\n            Cleaving Leap. When you make a jump, you can triple your jumping distance. If you long jump at least 30ft of high jump at least 10ft, you can use the attack action to make 1 attack with each weapon with advantage against a creature within range when you land or when you enter their threatened squares if they are flying. The attack deals {{level:barbarian}} additional damage.\r\n            Steel Whirlwind. You can use your action to begin a deadly dance. You can move up to half your movement speed. This movement provokes attacks of opportunity at disadvantage. You can make a single weapon attack against each creature that enters your threatened squares when you are moving.\r\n            You can use this feature once per long rest"}, {"name": "Ever-Mighty", "lvl": 14, "text": "Starting at 14th level, you can use your Titanic Might rage whenever you wish an infinite number of times per day. You can draw two two handed weapons when you would normally be able to draw one."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_DEPTHS", "name": "Path of The Depths", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Many barbarians use their raw rage and adrenaline to display martial prowess, but there are also how through force of will learn to control this rage to temper it into a much more terrifying force.", "features": [{"name": "Quirk", "lvl": 3, "text": "You have developed a slight cosmetic feature, roll 1d8 to choose a quirk from the table"}, {"name": "Aquatic Adaptation", "lvl": 3, "text": "You have adapted to the water, you gain a swimming speed of 30ft and can breathe both air and water."}, {"name": "Raging Waters", "lvl": 3, "text": "At 3rd Level you learn how to channel the strength of water into your rage. When you enter rage you begin to slightly leak seawater. The first creature you hit on each turn take an additional 1d8 cold damage and can be pushed up to 10ft in a straight line away from you."}, {"name": "Moving Current", "lvl": 6, "text": "At 6th level, you can move more like flowing water. You gain resistance to cold damage and have advantages on saves against restraining or grappling."}, {"name": "Under the Waters", "lvl": 10, "text": "At 10th level, you can aid your allies in aquatic environments. You can ritually cast water breathing. Additionally when you aid someone on any form of check to do with swimming they can use your bonus if it is higher. Charisma is your spellcasting ability"}, {"name": "Crashing Wave", "lvl": 14, "text": "At 14th level, when you move more than 20ft towards a target then strike them you deal an additional 1d8 cold damage and 1d8 force damage. Additionally they must make a strength save against {{crashingwave:dc}} or be pushed 20ft and be knocked prone, on a success they are not moved or knocked prone."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_HEROES", "name": "Path of Heroes", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Most barbarians are known for their heavy weapons, quick and furious temper and savage nature. But there are barbarians who choose to take a path in which they focus on delivering deadly punches.", "features": [{"name": "Hero's Fist", "lvl": 3, "text": "Starting when you choose this path at 3rd level, your unarmed strikes normally deal 1d8 + {{strength:modifier}}.\r\n            Whilst raging, you can add your rage damage to both attack and damage rolls with your unarmed strikes. Each turn the first unarmed strike that hits a target deals an additional 1d8, which increases to 1d10 at 10th level. Your unarmed strikes deal a critical hit on a 19 or 20."}, {"name": "Indomitable Spirit", "lvl": 6, "text": "Starting at 6th level, because of your Indomitable Spirit you have advantage on saves against the charmed, frightened or paralyzed conditions. When you succeed a saving throw against being frightened you can use your reaction to try and frighten the creature. The creature must make a DC{{Spirit:dc}} wisdom save. Additionally your fists now count as magic weapons."}, {"name": "Signature Move", "lvl": 10, "text": "At 10th Level, you have created a signature move, this counts as an unarmed attack and has one of the following effects, this increases to 2 at 14th level and 3 at 18th level:\r\n            Before you attack, you can dash for free, if you move more than 30ft in a line towards the target (movement and dash) then the attack deals additional damage equivalent to {{dexterity:modifier}}d4s\r\n            Before you attack you can jump into the air and dash down and deal an additional d4 for every 5 ft you are above your target.\r\n            When you attack you also gain temporary hit points equivalent to {{level:barbarian}} + {{constitution:modifier}} \r\n            With your attack you can mage an additional attack as part of the same attack that deals an additional 1d6 damage\r\n            When you attack you deal an extra 1d8 fire, lightning or cold damage"}, {"name": "One for All", "lvl": 14, "text": "At 14th level, whenever you enter your rage or use your signature move all allies within 15ft gain the following benefits for the next minute:\r\n            They gain temporary hit points equivalent to {{level:barbarian:half}} + {{constitution:modifier}}\r\n            They have advantage on saving throws against being Charmed, Frightened and Paralyzed.\r\n            Additionally when you are below 1/4 of your maximum hit points, your signature move deals triple damage or the hit points you receive are tripled.\r\n            At 18th level the range of the aura increases 30ft and the threshold becomes 1/2 maximum hit points."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_ICE", "name": "Path of Ice", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Barbarians of the Path of Ice are a unique case in that their rage doesn't resemble that of any other barbarians. Instead, it takes the form of cold, intelligent concentration and observation. Their anger gives them focus, and they use it much to their enemies' detriment.", "features": [{"name": "Frozen Heart", "lvl": 3, "text": "Starting when you choose this path at 3rd level, the essence of the ice is imbedded into your very soul. You have resistance to cold and freezing temperatures don't effect you."}, {"name": "Total Concentration", "lvl": 3, "text": "Starting at 3rd level, you enter Total Concentration when you rage. You now have advantage on intelligence checks and saving throws. Attacks that target you have disadvantage. You have resistance to fire and psychic damage."}, {"name": "Fury of the Blizzard", "lvl": 6, "text": "At 6th Level, your familiarity with the winter allows you to summon it during the tides of battle. As an action, choose a point within 60ft of you, In a 30ft radius around that point a blizzard blankets the battlefield. The area becomes difficult terrain and heavily obscured, any creatures that end their turns inside take 3d6 cold damage. Once you use this feature you can't again until you finish a short rest."}, {"name": "Eyes of the Winter Wolf", "lvl": 10, "text": "At 10th level, your levelheadedness allows you to strike true when you see an opening, If you get advantage on a melee attack roll, the attack deals an extra 1d6 cold damage."}, {"name": "Flash Freezing", "lvl": 14, "text": "At 14th level, you can channel your fury to control your body temperature. When you grapple an enemy, you can use your bonus action to attempt to flash freeze them. If you do so the target must make a Constitution save against {{flashfreeze:dc}}. On a failure they take 6d8 cold damage and their speed is reduced to 0 until the start of your next turn. On a success the creature takes half the damage and can still move. If a creature is reduced to 0 hit points it becomes a solid block fo ice. Once you have used this feature you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_FULMINOUS", "name": "Path of The Fulminous", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Even in the worst of storms, with winds crashing all around and rain beating down, there is one force that stands out as the most powerful. The lightning strike. Barbarians who follow this path try to emulate this power.", "features": [{"name": "Lightning's Fury", "lvl": 3, "text": "Starting at 3rd level, when you rage you are empowered with the fury of a lightning strike granting you the following benefits. Your unarmed strikes deal 1d6 bludgeoning damage. The bonus rage damage that you deal is lightning. If you take the attack action you can make an unarmed strike as part of the same action."}, {"name": "Fulminous Soul", "lvl": 6, "text": "At 6th level, the power of lightning has permeated your soul. You gain resistance to thunder and lightning damage. In addition, your unarmed strikes you make when raging count as magical."}, {"name": "Sudden Storm", "lvl": 10, "text": "At 10th level, you gain the ability to ready your allies for battle. When you roll initiative, you can use your reaction to give all allies in 30ft advantage on the roll. If you use this there is no surprise round against you."}, {"name": "Storm Bolt", "lvl": 14, "text": "At 14th level, you can become what you are emulating. When you move 10ft in any straight line during a single turn whilst raging you can become a lightning bolt. You instantly travel 30ft in a straight line. The transformation removes the grappled or restrained conditions, and the instant movement doesn't provoke attacks of opportunity. At the end of this movement you return to your original form and all creatures around you must make a constitution save (DC = {{stormbolt:dc}}) or take 1d6 + {{level:barbarian:half:up}} level thunder damage. On a success the target takes half damage."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_ANTIMAGIC", "name": "Path of Antimagic", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Barbarians that follow this path use their rage to push through the damage of magic and resist its effects. After all, if some creatures can use their minds to affect the barbarian, then the barbarian can use their minds to ignore those effects. The Path of Antimagic is a simple one, headed straight through whatever magics might try and stand in your way.", "features": [{"name": "Mind over Magic", "lvl": 3, "text": "Starting when you choose this path at 3rd level, your rage begins to shield you. While raging you have resistance to all spell damage."}, {"name": "Unstoppable Juggernaut", "lvl": 6, "text": "Starting at 6th level, not even magical trickery can stop you. While raging, your speed by magic and any magical effects that would paralyse or petrify you instead causes the effects of the slow spell. Additionally, if you are frightened by a spell, willingly moving towards the source counts a difficult terrain."}, {"name": "Magic Sense", "lvl": 10, "text": "At 10th Level, your continuous battle with magical forces has honed your ability to notice magic to an uncanny degree. You gain the ability to cast detect magic as a ritual. Additionally, you have advantage on intelligence and wisdom checks vs illusions."}, {"name": "Magical Magnet", "lvl": 14, "text": "At 14th level, you begin to draw magic towards you to snuff it out. If a creature within 10ft of you is targeted by a spell, you can use your reaction to force the spell to target you. If the spell requires an attack roll it is made with disadvantage, if it requires a saving throw it is made with advantage."}]}, {"id": "ID_RDDT_ARCHETYPE_PATH_OF_FIRE", "name": "Path of Fire", "parentClass": "Barbarian", "source": "Reddit : Unearthed Arcana", "summary": "Barbarians of the Path of Fire draw their rage from the blazing heat of their souls, taking inspiration from the lame's ability to continue growing indefinitely, consuming all around it.", "features": [{"name": "Rising Fire", "lvl": 3, "text": "Starting when you choose this path at 3rd level, the fire in you is drawn out by your weapons. While you rage, your melee weapons attacks deal an additional d4 fire damage."}, {"name": "Warmth of the Flame", "lvl": 6, "text": "At 6th level, the fire in your soul also warms your body. You are resistant to cold damage and suffer no adverse effects from extreme cold. When you rage this becomes an immunity."}, {"name": "Fiery Soul", "lvl": 10, "text": "At 10th Level, your rage has grown into an all consuming wildfire. When you reduce an enemy to 0 hit points while raging, you gain 15 temporary hit points."}, {"name": "Erupting Fury", "lvl": 14, "text": "At 14th level, your anger is like a chamber of pressure in a volcano, ready to explode out at any moment. When you enter a rage, any creatures within 15ft of you must make a dexterity save with a DC of {{flashfreeze:dc}}. On a failure, the creature takes 6d6 + {{constitution:modifier}} fire damage and is pushed 10ft away. On a success, they take half as much and aren't pushed."}]}, {"id": "ID_RDDT_ARCHETYPE_WIZARD_SPELLSHAPING", "name": "Spellshaping", "parentClass": "Wizard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Spellshaping", "lvl": 2, "text": "When you adopt this tradition at 2nd level, you gain the ability to sculpt your spells into different shapes. Whenever you cast a spell that effects an area, you can sculpt it into a different size and shape by choosing the new shape and following the below table. Set N to the radius or length of the spell you are casting."}, {"name": "Mystical Divergence", "lvl": 6, "text": "When a spell is cast that affects an area within 15 feet of you, you can use your reaction to choose a number of creatures that you can see within the area, up to {{intelligence:modifier}}. Each chosen creature automatically succeeds on its Saving Throw against the spell."}, {"name": "Additional Spell Shapes", "lvl": 10, "text": "Starting at 10th level you can shape spells into even more shapes."}, {"name": "Concentrated Arcanum", "lvl": 14, "text": "When a creature within 60 feet of you casts a spell, you can use your reaction to make a Spell Attack Roll contested by the creature's own. If you win the contest, you can change the direction the spell is being cast up to 45 degrees if it's a line or cone, or move it up to 20 feet if it's a cube, cylinder or sphere. If you win by more than 5, you can change it up to 90 degrees or move it up to 50 feet. If your d20 roll is a 20, you can freely choose any direction or point within range."}]}, {"id": "ID_RDDT_ARCHETYPE_WIZARD_MELEE_MAGIC", "name": "Melee Magic", "parentClass": "Wizard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Impervious", "lvl": 2, "text": "When you cast a spell, that spell is no longer capable of damaging you, for example your fireball detonating next to your face will not harm you. Additionally you no longer have disadvantage within 5ft and any spell attacks within 5ft are treated as melee attacks (no disadvantage for prone)"}, {"name": "Warcaster", "lvl": 2, "text": "As you have studied close quarters combat you have become proficient in light armour, additionally you are able to use any weapon you are proficient with as an arcane focus."}, {"name": "Defensive Measures", "lvl": 2, "text": "At 2nd level you've learned to utilise a small amount of magic to protect yourself even whilst fighting in the thick of combat. You can reduce the casting time of a number of spells to protect yourself reducing the time to a bonus action. You can only cast these spells if you have them prepared."}, {"name": "Spell Blitz", "lvl": 6, "text": "When you cast a spell, instead of casting it at a range you can teleport up to the target as long as the spell would reach to an an unoccupied space, (a 30ft spell allows you to teleport 30ft towards a creature but only if the spell hits) you must then make this spell attack within 5ft. Once done this reduces your speed to 0 if it were not already. If you do this a creature has disadvantage on dexterity saves as it would be surprised."}, {"name": "Arcane Deterrent", "lvl": 10, "text": "When you roll to check if you keep up concentration after an attack, all creatures in melee range must make a dexterity save against your spell save DC or take 1d6 magic damage (overcomes all resistances and immunities) per spell level."}, {"name": "Swift Casting", "lvl": 14, "text": "When you teleport using Spell Blitz you may, as part of that action, cast a cantrip within melee range"}]}, {"id": "ID_RDDT_ARCHETYPE_WIZARD_ENTROPY", "name": "School of Entropy", "parentClass": "Wizard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Arcane Savant", "lvl": 2, "text": "The time and cost for copying necromancy spells or spells that deal necrotic damage into your spellbook is halved."}, {"name": "Drain Life", "lvl": 2, "text": "Your knowledge of life and death allows you to steal the life energy from creatures touched by your dark spells. Once per turn when you reduce one or more creatures to 0 hit points with a spell of 1st level or higher you gain temporary hit points equal to double the spell level, or three times if the damage was necrotic or was a necromancy spell. Alternatively, when a creature within 30ft of you is reduced to 0 hit points you can use your reaction to reap its life and regain 3 hit points."}, {"name": "Necrosis", "lvl": 6, "text": "Starting at 6th level, you've learned to suffuse your spells with negative energy, leaving your enemies weakened and vulnerable. Whenever you successfully hit one or more creatures with a spell that deals necrotic damage, or one or more creatures fail a save against a necromancy spell, you can choose a number of those creatures equal to half your wizard level, to suffer one of the following effects:\r\n\t\t\tFestering Wounds. Whenever the creature takes damage they take an additional 1d4 necrotic damage.\r\n\t\t\tWithering Muscle. The creature's movement speeds are reduced by 10 and it subtracts 1d4 from all damage rolls it makes.\r\n\t\t\tDecaying Mind. The target has disadvantage on Constitution saving throws to maintain concentration, also they have disadvantage on Intelligence, Wisdom and Charisma checks and saves.\r\n\t\t\tRotting Flesh. The creature can't regain hit points\n\t\t\tThe effects last 1 minute"}, {"name": "Death's Reach", "lvl": 10, "text": "At 10th level, you can briefly tap into the Negative Energy plane and imbue the weave around you with its energies. As a bonus action you can increase the range of a necromancy or necrotic damage spell, the range is doubled and touch spells increase to 30ft. Additionally necrotic damage you deal ignores resistances and treats immunities as resistances."}, {"name": "Necrolord", "lvl": 14, "text": "At 14th level, you no longer need to eat, drink, sleep or breathe, you gain resistance to necrotic damage and poison damage, the resistance to necrotic damage increases to an immunity at 16th level. When you cast a spell that deals necrotic damage, you can choose any number of targets to be immune to the spell. Additionally, when you affect creatures with your Necrosis feature you can induce two effects."}]}, {"id": "ID_RDDT_ARCHETYPE_WIZARD_ELEMENTS", "name": "School of The Elements", "parentClass": "Wizard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Knowledge of the Elements", "lvl": 2, "text": "When you choose this arcane tradition at 2nd level, you gain proficiency in the nature skill and learn primordial. Additionally when you make a check to do with elements of the elemental planes you have advantage and use double your proficiency modifier."}, {"name": "Elemental Control", "lvl": 2, "text": "When you choose this arcane tradition at 2nd level, you gain the control flames, gust, mold earth and shape water cantrips. When you cast a spell that deals acid, cold, fire, lightning or thunder damage you can choose to substitute this damage with one of the other four."}, {"name": "Elemental Resistance", "lvl": 6, "text": "At 6th level choose either acid, cold, fire, lightning or thunder damage when you finish a long or short rest. You gain resistance to that damage type until you choose a new damage type at the end of a rest. Additionally you can use your reaction to extend this resistance to one creature within 30ft of you that you can see who just took that type of damage."}, {"name": "Elemental Attunement", "lvl": 10, "text": "You gain an additional benefit based on which damage type you chose for your resistance."}, {"name": "Elemental Embodiment", "lvl": 14, "text": "At 14th level, you attain the ability to become one with the elements. As an action you can cast one of the following without expending a spell slot, Investiture of fire, Investiture of cold, Investiture of stone, Investiture of wind. Once you use this feature you can't again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_WIZARD_MASTERY", "name": "School of Mastery", "parentClass": "Wizard", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Arcane Savant", "lvl": 2, "text": "The time and cost for copying 1st and 2nd level spells into your spellbook is halved"}, {"name": "Preferred Spell", "lvl": 2, "text": "Each level you can choose a spell from your spellbook to become a preferred spell. When you cast this spell you gain a number of advantages based on your level. You gain advantage to hit or induce disadvantage for saving throws"}, {"name": "Improved Spell Critical", "lvl": 2, "text": "Your spells score a critical on a score of 19-20 additionally your spell save DC increases by one."}, {"name": "Sling Spell", "lvl": 6, "text": "When you cast a spell as an action you can cast a cantrip with casting time of bonus action as part of the same action."}, {"name": "Eldritch Resistance", "lvl": 10, "text": "Whenever a spell forces you to make a saving throw or you are forced to make a concentration check you can choose to gain advantage on the check once per short rest."}, {"name": "Superior Spell Critical", "lvl": 14, "text": "Your spells score a critical on a score of 18-20 additionally your spell save DC increases by one."}]}, {"id": "ID_RDDT_ARCHETYPE_RANGER_VOIDSTALKER", "name": "Voidstalker", "parentClass": "Ranger", "source": "Reddit : Unearthed Arcana", "summary": "Voidstalker rangers are rangers who favour the bow, imbuing their bows with the ferocious nature of the void to become highly mobile, highly lethal archers.", "features": [{"name": "Arcane Arrows", "lvl": 3, "text": "At 3rd level, you gain the ability to create an arrow infused with magic. Your eyes and bow glow faintly as you pull back the string, and a arrow made of energy forms in the bow. You can spend an action to create and fire a cantrip arrow. You can use 3 of these per long rest."}, {"name": "Voidstalker Magic", "lvl": 3, "text": "Starting at 3rd level, you learn an additional spell when you reach certain levels in this class, as shown in the Voidstalker Spells table. The spell counts as a ranger spell for you, but it doesn't count against the number of ranger spells you know."}, {"name": "Magic Empowerment", "lvl": 7, "text": "At 7th level, your movement speed increases by 15ft, when you take fall damage it is reduced by {{empowerment:fall}}, you can impose disadvantage on attacks up to {{dexterity:modifier}} per short rest. Additionally you gain the lunge ability.\r\n            Lunge.As an action you can launch yourself in any direction as far as your movement speed. When you do so you do not impose attacks of opportunity additionally as a bonus action you can take one attack with your bow whilst in motion."}, {"name": "Arcane Boost", "lvl": 11, "text": "By 11th level, using your stores of magical power, you can boost your physical abilities for a short period. You can use a bonus action to activate one of the following effects for 1 minute once per long rest:\r\n                Spell Shield. You gain a +2 to AC as you are enshrouded in magical energy\r\n                Arcane Vision. Your eyes begin to glow with energy and you gain the ability to see up to 120ft in both magical and non magical darkness and have advantage on all checks that would use your eyes.\r\n                Spell Sniper. If you don't move on your turn you gain advantage on all attack rolls, additionally you gain 1d8 force damage if your attack lands."}, {"name": "Void Bow", "lvl": 15, "text": "At 17th level, you've unlocked the void energy within you. You can summon your void bow, a magical longbow that generates its own ammunition. As an action you can summon the bow and it lasts for 1 minute. As an action you can fire 3 arrows from the bow, each arrow deals 10d6 force damage in a 10ft radius on a failed dexterity save against your spellsave DC. You can use this feature once per long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_RANGER_SHADOW_CONCLAVE", "name": "Shadow Conclave", "parentClass": "Ranger", "source": "Reddit : Unearthed Arcana", "summary": "Shadow Conclaves are at home in the darkest places: deep under the earth, in Shadowy alleyways, in primeval forests, and wherever else the light dims.", "features": [{"name": "Shadow Remnants", "lvl": 3, "text": "At 3rd level, you can conjure shadowy replicas of your attacks that trail just behind them, containing a fragment of their original power. When you're not in an area of bright light, each time you make a weapon attack on your turn, your target takes 1d4 damage of the weapon's type regardless of whether or not the original attack hit. Additionally as a bonus action you can darken a 10ft diameter one light level for 1 minute."}, {"name": "Shadow Magic", "lvl": 3, "text": "Starting at 3rd level, you learn an additional spell when you reach certain levels in this class, as shown in the SHADOW CONCLAVE Spells table. The spell counts as a ranger spell for you, but it doesn't count against the number of ranger spells you know."}, {"name": "Unending Sight", "lvl": 3, "text": "At 3rd level, no shadows can hide your enemies from you. You gain 60ft darkvision however it also works in magical darkness."}, {"name": "Merge with Shadow", "lvl": 7, "text": "By 7th level, While you are in darkness and not moving you can use an action to become invisible to all but truesight. Should you attack, or force a creature to make a saving throw, you must use and action to become invisible again. Additionally when you are in darkness or dim light you can teleport up to 90ft as a bonus action."}, {"name": "Shadow Strike", "lvl": 11, "text": "At 11th level, you learn to strike as a shadow, unleashing a devastating bombardment of attacks on your enemies. As an action you can make 4 strikes within range of you, these done's hve to be on the same target. These attacks can only be used with a melee weapon that does not have the heavy property, or a ranged weapon. You can use this when you are in darkness and can perform this feature {{wisdom:modifier}} per long rest."}, {"name": "My Shadow and I", "lvl": 15, "text": "Starting at 15th level, you have changed your focus to letting shadows help and guide you to enforcing your will on your own shadow. As an action you can detach your shadow and have it latch onto another creature you can see, make a ranged spell attack on a hit your shadow latches on, on a miss it doesn't. Your shadow retains its shape but acts on your will. While you don't have your shadow you lose 10 from have your maximum hit points. While your shadow is attached to another creature you always know where that creature is as long as it is on the same plane as you. Additionally any attacks you make against the creature your shadow is attached to are made with advantage. Your shadow can attempt to siphon health from the attached creature to you. The creature must make a Constitution saving throw or take 2d8 necrotic damage, you gain the number of hit points the creature looses."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_ANARCHY", "name": "Oath of Anarchy", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "The Oath of Anarch swears paladins to ideals of liberty, collectivism and a rejection of hierarchical rulership.", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "Syndical Solidarity / Freed From Chains."}, {"name": "Aura of Defiance", "lvl": 7, "text": "Starting at 7th level, you and friendly creatures within 10ft of you have advantage on saving throws against attacks spells or other effects that would reduce their speed, paralyze them or restrain them."}, {"name": "Free Spirited", "lvl": 15, "text": "Starting at 15th level, Your walking speed increases by 10ft and you can move across difficult terrain without expending additional movement"}, {"name": "Exalted Insurgent", "lvl": 20, "text": "At 20th level, you can use an acton to take the form of a fearless revolutionary. For 1 minute you gain the following benefits:\r\n\t\t\tYou and friendly creatures within 30ft of you have advantage on attack rolls against a creature is there is at least one enemy of the target within 5ft of the target.\r\n\t\t\tFriendly creatures that start their turn in 30ft of you have their speed increased by 15ft until the end of their turn.\r\n\t\t\tYou deal double damage to structures and objects.\r\n\t\t\tThis effect ends early if you are incapacitated or die. Once you use this feature, you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_WAR", "name": "Oath of War", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "On a battle field everyone fights for something, whether good or evil everyone has something that ignites the spark of passion. Paladins who take this oath thrive in the thick of war, searching for a good fight.", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "Champion of War / Improved Warfare."}, {"name": "Aura of Glory", "lvl": 7, "text": "Starting at 7th level, you and friendly creatures within 10ft can add {{wisdom:modifier}} to their attack and damage rolls, this doubles if they are below half max hit points."}, {"name": "Blades of Strife", "lvl": 15, "text": "Starting at 15th level, once per turn when you land a weapon attack against a creature, you can additionally deal the weapons damage to another creature within 5ft of the attack's original target."}, {"name": "Angel of Honour", "lvl": 20, "text": "Gain the following benefits for 1 hour: \r\n\t\t\tYou gain 20 ht points at the start of each of your turns. \r\n\t\t\tYou can make an additional attack whenever you take the attack action. \r\n\t\t\tYour Strength score increases by 4."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_THE_PRIMORDIALS", "name": "Oath of The Primordials", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "Many Paladins pledge themselves to gods. Very few pledge themselves to the elements or the world itself.", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "Return to Form / Elemental Strike."}, {"name": "Aura of The Elements", "lvl": 7, "text": "Starting at 7th level, the elements have designated yous as their protector. You and friendly creatures within 10ft of you have resistance to cold, fire, lightning and thunder damage."}, {"name": "Elemental Warden", "lvl": 15, "text": "Starting at 15th level, you age 1 year for every 10 years that pass and you can't be aged by magical means. There is also a slight cosmetic change that incorporates the elements."}, {"name": "Elemental Avatar", "lvl": 20, "text": "At 20th level, You can use your action to undergo a transformation for 1 minute you gain the following benefits: You gain immunities to the damage types listed in aura of the elements. You gain a flying speed of 60ft. As a bonus action you choose 3 creatures that must make a charisma saving throw. On a failed save they take {{paladin:level}} of damage in one of the types of damage listed in your aura of the elements. on a successful save the damage is halved."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_ASH", "name": "Oath of Ash", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "Paladins who vow the Oath of Ash seek to preserve the longevity of civilization, dedicating every resource at their disposal to securing future prosperity. Paladins sworn to this oath believe that progress is not automatic nor inevitable, but a journey where each step demands sacrifice, struggle, and suffering. To them, only those with unbreakable focus and determination can wield the brilliant torch of progress. These paladins achieve this by cauterizing the detrimental aspects of civilization ", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "Pyroclastic Tide / Igneous Coliseum."}, {"name": "Aura of the Epicentre", "lvl": 7, "text": "Starting at 7th level, hostile creatures within 10 feet of you treat the ground as difficult terrain and take fire damage equal to your Charisma modifier (minimum of 1) for every 10 feet they move within the range of your scorching aura. You can choose to suppress this aura at will."}, {"name": "Mantle Crusher", "lvl": 15, "text": "Starting at 15th level, Whenever a creature hits you with an attack, the ground shakes as you absorb the impact of the strike, and you can use your reaction to force creatures of your choice within 10 feet of you to make a Dexterity saving throw against your spell save DC. If it fails, it is knocked prone and takes bludgeoning damage equal to half your paladin level."}, {"name": "Angel of Honour", "lvl": 20, "text": "Gain the following benefits for 1 minute: \r\n\t\t\tA veil of smoky ash cloaks you from hostile sight, creating an aura of soot that radiates 30 feet from you. The first time any hostile creature enters the smoke or starts its turn there during a battle, the creature must succeed on a Constitution saving throw against your spell save DC or become blinded until the start of their next turn.\r\n\t\t\tYou and allied creatures within the ashy aura gain resistance to fire damage and ignore the difficult terrain you create. Hostile creatures lose resistance to fire damage and those with immunity to fire damage are treated as if they had resistance to fire damage instead.\r\n\t\t\tWhenever you are to take fire damage, you instead gain temporary hit points equal to half of the damage.\r\n\t\t\tWhen you move 0 feet on your turn, the ground around you melts into lava, transmuting into a 15-foot square of difficult terrain. Each tile of lava deals damage equal to half your paladin level in fire damage to any creature that enters it for the first time or ends its turn there. The area cools down and returns to normal terrain after 1 minute."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_METAL", "name": "Oath of Metal", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "Paladins taking on the Oath of Metal have realized the meaning of life. Life doesn't matter. There is no greater purpose, the strong survives, the weak perish. Heaven and Hell are just places like any other. Death is just another road to walk on, and in the end, we shall all become children of the grave, deep in the iced earth.", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "For Whom The Bell Tolls / Heaviest Matter of the Universe."}, {"name": "Symphony of Destruction", "lvl": 7, "text": "Starting at 7th level, a choir of spirits play a symphony around you while you're not incapacitated. The symphony can be heard for up to 10ft in every direction, but not through total cover. Any creature of your choice that hears the choir takes {{charisma:modifier}} additional psychic damage when they take damage from any source."}, {"name": "Death Clock", "lvl": 15, "text": "Starting at 15th level when you reach 0 hit points, you can choose to halt the gears that grind the living to dust. For 1d4+1 turns you can continue fighting as normal. During this time yu cannot be healed in any way and you do not roll death saving throws, even if you would take additional damage. After the effect ends you call unconscious on 0 hit points and take 1 level of exhaustion. You may use this ability once per long rest."}, {"name": "Iron Man", "lvl": 20, "text": "At 20th level, you gain the ability to awaken the warrior within, and turn your skin into living metal. You can use your action to become a metal warrior and gain the following benefits for 1 minute: \r\n\t\t\tYou gain resistance to all damage and your AC becomes 20 if it isn't 20 or higher already.\r\n\t\t\tYou automatically succeed on any Strength saving throw that would knock you prone or move you against your will. \r\n\t\t\tThe bonus damage from Symphony of Destruction is doubled.\r\n\t\t\tThis effect ends early if you are incapacitated or die. Once you use this feature, you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_ARCHETYPE_OATH_OF_THE_COMMON_MAN", "name": "Oath of the Common Man", "parentClass": "Paladin", "source": "Reddit : Unearthed Arcana", "summary": "The Oath of the Common Man is born of togetherness, mutual suffering, and righteous indignation at those who would put their boot heel to the collective neck of the worst-off in society. When a greedy baron levies unfair taxes that cut the poor to the bone, when a pompous dragon ransacks the countryside to build his own personal hoard, when a bloodthirsty tyrant forces the poor into conscripted service in his armies, to fight and die on the frontlines, the paladin of the Common Man will be there", "features": [{"name": "Oath Spells", "lvl": 3, "text": "You gain oath spells at the paladin levels listed."}, {"name": "Channel Divinity", "lvl": 3, "text": "Worker's Harmony / Turn the Bourgeois."}, {"name": "Aura of Solidarity", "lvl": 7, "text": "Beginning at 7th level, whenever you or a friendly creature within 10 feet of you takes damage, you may choose to instead divide that damage evenly between all friendly targets within this aura, rounding up fractions to the nearest whole hit point. As an example: If there are 3 friendly creatures in this aura (yourself included) and one takes 20 hitpoints of damage, you may choose to have all three friendly creatures take 7 hitpoints of damage instead."}, {"name": "Revolutionary Spirit", "lvl": 15, "text": "Starting at 15th level, you may take the Help action as a bonus action on each of your turns.\r\n\t\t\tIn addition, you have advantage on all Charisma checks involving interaction with laborers and the common man."}, {"name": "Strength of the People", "lvl": 20, "text": "At 20th level, you can transform yourself into a larger-than-life icon of the working class and their revolutionary struggle. Using your action, you can gain the following benefits for 1 minute, as long as you can see or hear a conscious friendly creature:\r\n\t\t\tYou grow to large size and your equipment grows with you, doubling your reach and movement speed.\r\n\t\t\tAt the start of each of their turns, any friendly creature that can see or hear you (including yourself) gains {{charisma:modifier}} temporary hit points. \r\n\t\t\tAs a bonus action on your turn, you may apply the benefits of the Help action to {{charisma:modifier:half:up}} friendly creatures, within 30 feet of you and that can see or hear you.\r\n\t\t\tOnce you use this feature, you can't use it again until you finish a long rest."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_EMBER_HEART", "name": "Emberheart", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "You have been touched by primordial fire. Did you receive this power as a gift from a noble Efreeti, or were you born near a rift leading to the elemental plane of fire? This ember of primal flame within you may manifest in your outward appearance or through your emotions. Most Emberheart sorcerers revel in their exotic appearance; flame red hair, eyes like glowing embers, or dark skin with magma peering through cracks. Is your flaming soul a raging inferno, unable to be controlled, or, do you s", "features": [{"name": "Emberheart Magic", "lvl": 1, "text": "Whenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a conjuration or evocation spell from the sorcerer, warlock, or wizard spell list."}, {"name": "Heart of Flame", "lvl": 1, "text": "The primordial fire in your soul emboldens you. Starting at 1st level, you are resistant to fire damage and have advantage on saving throws to resist being charmed or frightened. In addition, you can speak, read, and write Ignan."}, {"name": "Wild Fire", "lvl": 6, "text": "Starting at 6th level, when you reduce a creature to 0 hit points with a spell that deals fire damage, you can use you reaction to cause the creature to explode. Creatures within 10 feet must make a Dexterity saving throw. A target takes fire damage based on the size of the slain creature on a failed save, or half as much damage on a successful one. Small creatures deal 1d6 fire damage, and for each size category above Small, the explosion deals an additional 1d6 damage. Tiny or smaller creatures produce no explosion."}, {"name": "Kindle the Flame", "lvl": 14, "text": "You are restored by flame. Beginning at 14th level, when you cast a spell of 1st-level or higher that deals fire damage, you can choose to regain hit points equal to the level at which the spell was cast + your Charisma modifier (minimum of 1)."}, {"name": "Primordial Inferno", "lvl": 18, "text": "You have mastered the elemental fire that burns within your soul, allowing you to become more elemental then mortal. Upon reaching 18th level, you no longer need to eat, drink, or sleep, and you are immune to fire damage.\r\n\t\t\tIn addition, when you take damage from a creature within 60 feet, that you can see, you can use your reaction to spend 2 sorcery points and rebuke them with elemental flame. The creature must make a Dexterity saving throw, and on a failed save they take {{level:sorcerer}} fire damage."}]}, {"id": "ID_WIKI_SORCERER_ARCHETYPE_VORTEX_SOUL", "name": "Vortex Soul", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "You have the innate ability to manipulate the weave of time and space itself. To you, timelines and gravity wells are as obvious and natural as the wind or waves. Regardless of the reason, you can manipulate the energy known as dunamis as naturally as one might speak or run.", "features": [{"name": "Gravity Anchor", "lvl": 1, "text": "At 1st level, you can subtly manipulate the gravity effecting you as a bonus action. You can either make it stronger or weaker.\r\n\t\t\tStronger. You have advantage on strength ability checks and saving throws and can't be knocked prone. However your movement speed is halved.\r\n\t\t\tWeaker. Your walking speed increases by 10ft, you can jump twice as far and twice as high and difficult terrain doesn't cost additional movement. However you have disadvantage on strength saves or ability checks.\r\n\t\t\tYou can end these effects or switch between them as a bonus action"}, {"name": "Intuitive Chronurgy", "lvl": 6, "text": "Starting at 6th level You learn the haste and slow spells. You can cast them using a spell slot or at 3rd level by expending 3 sorcery points. You have advantage on concentration checks with these spells."}, {"name": "Psychosomatic Contrast", "lvl": 6, "text": "At 6th level, you have advantage on checks to discern illusions and you can't be aged magically."}, {"name": "Zero Gravity Point", "lvl": 14, "text": "At 14th level you can enshroud yourself in a pocket of zero gravity as a bonus action. While the pocket exists you can \"fly\" at a speed of 30ft per turn and no gravity effects (such as reverse gravity) can effect you. The pocket lasts until you are incapacitated or you dismiss it as a bonus action. Although you can technically fly, it is much closer to a constant falling. For this reason once you are in the air you can't effect your motion unless you have something to push off or some other way of generating a force (such as a loaded crossbow firing)"}, {"name": "ID_WIKI_ARCHETYPE_FEATURE_VORTEX_SOUL_ZERO_CONFLUX_OF_THE_SOUL", "lvl": 18, "text": ""}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_METALLIC_SOUL", "name": "Metallic Soul", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "", "features": [{"name": "Metallic Spells", "lvl": 1, "text": "Whenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a conjuration or evocation spell from the sorcerer, warlock, or wizard spell list."}, {"name": "Magnetic Warrior", "lvl": 1, "text": "Your magnetic abilities allow you greater control of weapons. When wielding a metallic weapon with which you are proficient, you can use your Charisma Modifier, instead of Strength or Dexterity, for the attack and damage rolls."}, {"name": "Forged By Fire", "lvl": 6, "text": "When you fail a Constitution Saving throw made to maintain concentration on a spell that deals fire damage, you can expend one Sorcery Point to succeed instead."}, {"name": "Lodestone Armament", "lvl": 14, "text": "At 14th level, your affinity for using magnetism as a weapon increases. You learn animate objects, and it doesn't count against the number of spells you know. When you cast animate objects and target only metallic objects, each object has double the amount of Hit Points it would normally have."}, {"name": "Magnetic Lock", "lvl": 18, "text": "As an action, you can choose a creature you can see within 60 feet of you that is made of or wearing a large amount of metal and force it to make a Strength Saving throw. The creature is paralyzed for 1 minute on a failed saving throw, and can remake the Saving throw as an action on each of its turns, ending the effect on a success.\r\n\t\t\tAlternatively, as an action, you can choose a metallic object that is huge or smaller and lock it in place as if it were an immovable rod.\r\n\t\t\tYou can end either of these effects at any time, no action required."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_WAVEBORN", "name": "Waveborn", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Within you dwells a drop of elemental power drawn from primordial waters. You have an innate connection to the ocean depths, babbling brooks, and the frigid waters of frozen lakes. How did you come to wield the power of elemental waters? Did you inexplicably survive a shipwreck, awakening with oceanic power, or did you drink from a stream flowing from the elemental plane of water?", "features": [{"name": "Waveborn Magic", "lvl": 1, "text": "Whenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a conjuration or evocation spell from the sorcerer, warlock, or wizard spell list."}, {"name": "Heart of the Sea", "lvl": 1, "text": "The elemental waters within you have altered your physical form. Starting at 1st level, you are resistant to cold damage, you gain a swimming speed equal to your movement speed, and you can breathe both air and water. In addition, your connection to elemental water allows you to speak, read, and write Aquan."}, {"name": "Curse of the Depths", "lvl": 6, "text": "When you draw upon the oceanic energy within you, your watery spells carry with them a deadly curse. Starting at 1st level, when you cast a spell that deals cold damage, reduces a creature's movement speed, or forces a creature to move, you can spend additional sorcery points to reduce the movement speed of the creature. For each sorcery point you expend, the movement speed of the creature is reduced by 5 feet."}, {"name": "Watery Resilience", "lvl": 6, "text": "Beginning at 6th level, you can assume a watery form when under assault. When you are hit by an attack, you can use your reaction to shift into a liquid form, gaining resistance to bludgeoning, piercing, and slashing damage until the end of your current turn. As part of the same reaction you can immediately move up to your full movement speed without provoking opportunity attacks.\r\n\t\t\tYou can use this ability {{proficiency}} times, and you regain all expended uses when you finish a long rest."}, {"name": "Oceanic Empowerment", "lvl": 14, "text": "Your improved control over the elemental waters that fuel your power improves your Curse of the Depths. Starting at 14th level, when you reduce the movement speed of a creature to 0 with your Curse of the Depths feature, you can force the creature to make an (additional) Constitution saving throw. On a failed save, the creature is covered in elemental ice and is restrained until the start of your next turn. A creature can use an action to scrape the ice off the target, ending the restrained condition early.\r\n\t\t\tIn addition, while you are using your swimming speed, you can take the Dash action as a bonus action on your turn."}, {"name": "Primordial Waters", "lvl": 18, "text": "Upon Reaching 18th level, your body and soul are permanently altered by the power of the primordial sea from which you draw your power. You no longer need to eat, drink, or sleep, you are immune to cold damage, and you are resistant to bludgeoning, piercing, and slashing damage.\r\n\t\t\tIn addition, when you are hit with a critical hit, you can use your reaction to turn the critical hit into a normal hit."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_STORMSOUL", "name": "Stormsoul", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Within you dwells a spark of elemental air, marking you as a stormsoul sorcerer. You have an innate affinity with the storms and squalls of the material world. How did you come to bear this power within you? Were you blessed at birth by a noble Djinni, did you make a deal with a primordial air elemental, or were you born in the eye of a terrible storm?", "features": [{"name": "Stormsoul Magic", "lvl": 1, "text": "Whenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a conjuration or evocation spell from the sorcerer, warlock, or wizard spell list."}, {"name": "Heart of Winds", "lvl": 1, "text": "When you call upon your inner storm you gain the ability to fly, if only briefly. Starting at 1st level, when you cast a spell of 1st-level or higher you gain a temporary flying speed equal to your remaining movement speed, that lasts until the end of your current turn. If you end your movement in the air you fall to the ground, taking appropriate falling damage. While flying you do not provoke opportunity attacks. In addition, your connection to elemental air allows you to speak, read, and write Auran."}, {"name": "Stormborn", "lvl": 6, "text": "Your control over the storm within you grows, empowering your physical form against tempestuous magic. Beginning at 6th level, you are resistant to lightning and thunder damage.\r\n\t\t\tIn addition, whenever you cast a spell of 1st-level or higher that deals lightning or thunder damage, you can expend additional sorcery points to cause stormy magic to erupt from you. For each additional sorcery point you expend you can force one creature within 15 feet of you to make a Dexterity saving throw. On a failed save, targets takes {{level:sorcerer:half}} thunder damage."}, {"name": "Storm Guide", "lvl": 6, "text": "In addition to controlling the storm within, your affinity for the winds allows you to exert control over the weather around you. Starting at 6th level, you can control existing weather conditions in the following ways:\r\n\t\t\t•If it is raining, as an action, you can stop the rain from falling in a 20-foot radius sphere centered on you. You can end this effect as a bonus action on your turn.\r\n\t\t\t•If it is windy, as a bonus action, you can change the direction the wind blows within a 100-foot radius sphere centered on you. The wind blows in the direction you choose until the end of your next turn."}, {"name": "Windcaller", "lvl": 14, "text": "Upon reaching 14th level, your power over the wind allows you to fly. You gain a flying speed equal to your movement speed. As you fly your lower extremities become a whirlwind."}, {"name": "Primordial Storm", "lvl": 18, "text": "You have mastered the elemental storm that rages within you, and you have become more elemental then mortal. Upon reaching 18th level, you no longer need to eat, drink, or sleep, and you are immune to lightning and thunder damage.\r\n\t\t\tIn addition, when you are hit by a melee attack, you can use your reaction to force the attacker to make a Strength saving throw. On a failed save, the creature takes {{level:sorcerer}} thunder damage and is pushed back 30 feet in a straight line. On a successful save they take half damage and do not move."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_STONEBLOOD", "name": "Stoneblood", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "You are a stoneblood sorcerer, a mortal with an intrinsic tie to the elemental plane of earth. The stalwart power of stone suffuses your body making you immovable and unyielding as the mountains. Did you gain this power from an ancient earth elemental, barter for it with the greedy Dao, or are you descended from the original dwarves, molded from the bedrock of the world? The power that dwells within your blood urges you to remain steadfast in your decisions, and hoard the fruits of the earth; pr", "features": [{"name": "Stoneblood Magic", "lvl": 1, "text": "Whenever you gain a sorcerer level, you can replace one spell you gained from this feature with another spell of the same level. The new spell must be a conjuration or evocation spell from the sorcerer, warlock, or wizard spell list."}, {"name": "Heart of Stone", "lvl": 1, "text": "You can draw upon the earthen magic within you harden your physical form for a limited time. Starting at 1st level, you can use a bonus action to take on an elemental form, your physical form becomes covered in rock and stone, and you gain the following benefits:\r\n\t\t\t•You gain temporary hit points equal to your sorcerer level.\r\n\t\t\t•If you are not wearing armor or wielding a shield, your armor class is equal to {{stone:ac}}.\r\n\t\t\t•You use your Constitution modifier for the attack and damage rolls of your unarmed strikes.\r\n\t\t\t•Your unarmed strikes deal 1d10 bludgeoning damage. If you strike with two free hands, the d10 becomes a d12.\r\n\t\t\tThis transformation lasts for one minute, until you end it as a bonus action, or fall unconscious. You can use this ability {{proficiency}} times, and you regain all expended uses when you finish a long rest.\r\n\t\t\tIn addition, you can speak, read, and write Terran."}, {"name": "Crushing Blow", "lvl": 6, "text": "You have learned to draw upon the crushing weight of the earth to augment your strikes. Starting at 6th level, when you hit a creature with a melee weapon attack or unarmed strike, you can expend sorcery points to deal additional bludgeoning damage to the target. The extra damage is 2d6 for 2 sorcery points, plus 1d6 for each additional sorcery point you expend. This bludgeoning damage is considered magical for the sake of overcoming resistances and immunities. Each time you use this feature you can spend a maximum of {{level:sorcerer:half}} sorcery points.\r\n\t\t\tIn addition, your unarmed strikes while in your elemental form from your Heart of Stone feature count as magical for the sake of overcoming resistances and immunities."}, {"name": "Aegis of Stone", "lvl": 14, "text": "Beginning at 14th level, you can use a bonus action to expend 3 sorcery points and grant an aegis of protective earth magic to one creature you touch, including possibly yourself. The creature gains resistance to nonmagical bludgeoning, piercing, and slashing damage for 1 minute.\r\n\t\t\tWhen a creature hits the protected target with a melee attack, you can use your reaction to teleport to an unoccupied space within 5 feet of the attacker and make one melee weapon attack against them. You can teleport in this way only if you and the attacker are on the same surface. If you use this ability to grant a protective aegis to another creature, the effect immediately ends for the first creature."}, {"name": "Primordial Bulwark", "lvl": 18, "text": "You have mastered the elemental earth that dwells deep within your soul, allowing you to become more elemental then mortal. Upon reaching 18th level, you no longer need to eat, drink, or sleep, and you are permanently resistant to bludgeoning, piercing, and slashing damage. In addition, you can have your Aegis of Stone active on up to three creatures at one time."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_SPELL_STEALER", "name": "Spell Stealer", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Your magic is a perverted amalgamation of other spellcasters magic. You may have formed an incongruous bond of magic and blood by compressing arcane energy in your body forcefully, resulting in an artificial sorcerer whose magic is as interchangeable as books on a bookcase.", "features": [{"name": "Hijack", "lvl": 1, "text": "At 1st level, you can use your action to make a ranged spell attack to produce an instantaneous arcane tether towards a spellcaster you can see within 60ft. The tether is visible but intangible. The tether fails on non-spellcasters. Upon a successful tether you can choose a spell that you know they have or let the DM choose a random spell they know to copy. Once you are told the spell you can use a number of sorcery points equal to the spell level, the tether retracts from the spellcaster and that is now a spell you know, counting as a sorcerer spell. You can hold {{charisma:modifier}} spells using this ability, when you try to copy another you can choose one spell to forget."}, {"name": "Quell", "lvl": 6, "text": "Starting at 6th level you learn counterspell if you don't already know it. If you successfully counterspell you can expend a number of sorcery points equal to half the spell level round down to add it to your spells known. You can hold {{charisma:modifier}} spells."}, {"name": "Blowback", "lvl": 14, "text": "At 14th level, you can hold {{blowback:spells}} with Hijack and {{blowback:spells}} with Quell."}, {"name": "Arcane Redistribution", "lvl": 18, "text": "At 18th level when you successfully quell a spell you can choose to convert it into a number of sorcery points equal to the spells level rather than learn it."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_BLOOD_MAGIC", "name": "Blood Magic", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Your magic is the magic that exists within all living creatures ,the magic in blood. Those who continually loose blood slowly die from this however you are much more resilient, your blood is made much more for hematomancy.", "features": [{"name": "Resilient Blood", "lvl": 1, "text": "At 1st level, your blood is more resistant then many other peoples. You can draw upon it as you grow. You gain an additional hit die, you gain another at 4th, 8th, 12th, 16th and 20th level (These are not shown on the sheet but do make a note.)"}, {"name": "Hematurgy", "lvl": 1, "text": "As you gain in your power you can tap on your life force to power your spells. You can take a number of d8s damage equivalent to the level of the spell that you are casting to reduce the spell slot to that of a cantrip. Additionally you can take a d8 damage to gain that number of sorcery points. This damage ignores all resistances and immunities. As you take damage you reduce your hit die by the number of d8 damage you take. (For a 5th level spell you take 5d8 damage and reduce your hit die by 5)"}, {"name": "Bleed Magic", "lvl": 6, "text": "At 6th level, you gain the ability to cast spells through your wounds. when you take any form of damage that would make you bleed you can spend a sorcery point per spell level to use a reaction to cast a spell that would normally take an action or bonus action to cast."}, {"name": "Crimson Power", "lvl": 14, "text": "At 14th level, when you fall below half your hit points you gain a +3 to AC, when you roll damage in this state you add your proficiency to the damage."}, {"name": "Sanguine Storm", "lvl": 18, "text": "At 18th level, when your spell reduces a creature to 0 hit points you can spend two sorcery points to cause it to explode violently, the creature fails two death saving throws, all creatures in a 15 foot radius must make a dexterity saving throw or take 7d8 necrotic damage. You can use metamagic on this treating it as a necromancy spell."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_DREAM_MAGIC", "name": "Dream Magic", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Your innate magic comes from a place of dreams. This could be from a place that you only connect to while you sleep, or a plane or realm of dreams to which you have been exposed. You may even have a connection to, or have been cursed by, a creature of nightmares or dreams.\r\n\t\t\tDream sorcerers often first manifest their powers in their sleep, leading some to not realise they actually have these powers at first. It is also not uncommon for those who have not started mastering their powers to unwit", "features": [{"name": "Dreaming Mind", "lvl": 1, "text": "At 1st level, your dreams are protected by the magic you gain from them. Magic cannot put you to sleep unless you allow it to, and if magic is affecting your dreams you are immediately aware of it.\r\n\t\t\tAdditionally, while sleeping, you can hear and see as if conscious, however all other effects of the sleeping condition effect you."}, {"name": "Slumbering Power", "lvl": 1, "text": "Starting at 1st level, you learn the sleep spell, which doesn't count against your number of spells known.\r\n\t\t\tWhen you reach 2nd level in this class, when you cast the sleep spell you can expend a number of sorcery points equal to half the level of the spell slot (rounded up), when you do so all rolls of less than 4 on the d8 are counted as 5."}, {"name": "Terrors of the Night", "lvl": 6, "text": "At 6th level, you gain the power to manifest fears hidden deep in the subconscious of your foes. When you hit a creature you can see with a spell attack or a creature you can see fails a saving throw against one of your spells, you can choose to create an illusory manifestation of the target's deepest fears in an unoccupied space within 30ft of the target.\r\n\t\t\tThe target must make a Wisdom saving throw against your sorcerer spell save DC, becoming frightened of the illusion until it disappears on a failed save. The target ca repeat the saving throw at the end of each of its turns. THe illusion lasts for 1 minute, or until you lose your concentration (as if casting a concentration spell.) THe illusion moves with the target always staying within 30ft of it. Once you use this feature you can't use it again until you finish a short or long rest."}, {"name": "Protective Stupor", "lvl": 14, "text": "At 14th level, when a creature you can see attacks you or another creature you can see within 60ft of you, you may use your reaction to cause the attacker's mind to slumber for a moment. The attacker must make a Wisdom saving throw or have disadvantage on all attack rolls until the end of its next turn of a failed save or only on this one attack on a successful save."}, {"name": "Dream Walker", "lvl": 18, "text": "At 18th level, not even being asleep can stop you. When something causes you to become unconscious, you can instead spend 3 sorcery points to enter a semi-conscious state. While in this state you do not suffer any of the negative effects of being unconscious such as not being able to move or take actions. If knocked unconscious by being reduced to 0 hit points you may use this ability however you must still make death saves as usual and suffer the normal effects of taking damage at 0 hit points. This state lasts 10 minutes or until you are no longer unconscious, and when it ends if you are still unconscious you may simply spend 3 more points in order to continue this state.\r\n\t\t\tAdditionally, your power over dreams grows, you learn the dream spell. Also, your dreams can no longer be affected by any magic unless you allow it."}]}, {"id": "ID_RDDT_SORCERER_ARCHETYPE_OOZE_BLOODED", "name": "Ooze Blooded", "parentClass": "Sorcerer", "source": "Reddit : Unearthed Arcana", "summary": "Your innate magic comes from corrosive arcane ooze that is mingled with your blood. Many with this power can trace their magic back to an ancestor who worshiped Juiblex.", "features": [{"name": "Slime Secretion", "lvl": 1, "text": "At 1st level, you are able to open your pores and emit a thick slime, that absorbs harm. As a bonus action you can gain 1d6 temporary hit points. While you have these hit points any creature that deals melee damage to you takes {{charisma:modifier}} acid damage."}, {"name": "Corrosive Strike", "lvl": 1, "text": "At 1st level, your fists are coated in a potent acid. Your unarmed strikes deal 1d6 + your {{charisma:modifier}} acid damage."}, {"name": "Ooze Form", "lvl": 6, "text": "At 6th level, you can spend 1 sorcery point to temporarily allow the slime within you to take over your body. You can end this at any time. While in ooze form you are immune to acid damage, you gain a bonus to +{{charisma:modifier}} to AC, your corrosive strikes ignore acid resistance and you have advantage on all ability checks and saving throws to escape a grapple or avoid being grappled."}, {"name": "Supple Body", "lvl": 14, "text": "At 14th level you can mould and twist your form into unnatural shapes. You can move freely through small holes, narrow opening and even mere cracks. Additionally you can climb on any surface including vertical or inverted surfaces without requiring an ability check."}, {"name": "ID_RDDT_ARCHETYPE_FEATURE_OOZE_BLOODED_ZERO_SPLIT", "lvl": 18, "text": ""}]}, {"id": "official-barbarian-path-of-the-berserker", "name": "Path of the Berserker", "parentClass": "Barbarian", "source": "PHB / DSC", "summary": "Path of the Berserker (Barbarian subclass). See source book for full features.", "features": []}, {"id": "official-barbarian-path-of-the-totem-warrior", "name": "Path of the Totem Warrior", "parentClass": "Barbarian", "source": "PHB / DSC", "summary": "Path of the Totem Warrior (Barbarian subclass). See source book for full features.", "features": []}, {"id": "official-bard-college-of-lore", "name": "College of Lore", "parentClass": "Bard", "source": "PHB / DSC", "summary": "College of Lore (Bard subclass). See source book for full features.", "features": []}, {"id": "official-bard-college-of-valor", "name": "College of Valor", "parentClass": "Bard", "source": "PHB / DSC", "summary": "College of Valor (Bard subclass). See source book for full features.", "features": []}, {"id": "official-cleric-life-domain", "name": "Life Domain", "parentClass": "Cleric", "source": "PHB / DSC", "summary": "Life Domain (Cleric subclass). See source book for full features.", "features": []}, {"id": "official-cleric-light-domain", "name": "Light Domain", "parentClass": "Cleric", "source": "PHB / DSC", "summary": "Light Domain (Cleric subclass). See source book for full features.", "features": []}, {"id": "official-cleric-war-domain", "name": "War Domain", "parentClass": "Cleric", "source": "PHB / DSC", "summary": "War Domain (Cleric subclass). See source book for full features.", "features": []}, {"id": "official-druid-circle-of-the-land", "name": "Circle of the Land", "parentClass": "Druid", "source": "PHB / DSC", "summary": "Circle of the Land (Druid subclass). See source book for full features.", "features": []}, {"id": "official-druid-circle-of-the-moon", "name": "Circle of the Moon", "parentClass": "Druid", "source": "PHB / DSC", "summary": "Circle of the Moon (Druid subclass). See source book for full features.", "features": []}, {"id": "official-fighter-champion", "name": "Champion", "parentClass": "Fighter", "source": "PHB / DSC", "summary": "Champion (Fighter subclass). See source book for full features.", "features": []}, {"id": "official-fighter-battle-master", "name": "Battle Master", "parentClass": "Fighter", "source": "PHB / DSC", "summary": "Battle Master (Fighter subclass). See source book for full features.", "features": []}, {"id": "official-fighter-eldritch-knight", "name": "Eldritch Knight", "parentClass": "Fighter", "source": "PHB / DSC", "summary": "Eldritch Knight (Fighter subclass). See source book for full features.", "features": []}, {"id": "official-monk-way-of-the-open-hand", "name": "Way of the Open Hand", "parentClass": "Monk", "source": "PHB / DSC", "summary": "Way of the Open Hand (Monk subclass). See source book for full features.", "features": []}, {"id": "official-monk-way-of-shadow", "name": "Way of Shadow", "parentClass": "Monk", "source": "PHB / DSC", "summary": "Way of Shadow (Monk subclass). See source book for full features.", "features": []}, {"id": "official-monk-way-of-the-four-elements", "name": "Way of the Four Elements", "parentClass": "Monk", "source": "PHB / DSC", "summary": "Way of the Four Elements (Monk subclass). See source book for full features.", "features": []}, {"id": "official-paladin-oath-of-devotion", "name": "Oath of Devotion", "parentClass": "Paladin", "source": "PHB / DSC", "summary": "Oath of Devotion (Paladin subclass). See source book for full features.", "features": []}, {"id": "official-paladin-oath-of-the-ancients", "name": "Oath of the Ancients", "parentClass": "Paladin", "source": "PHB / DSC", "summary": "Oath of the Ancients (Paladin subclass). See source book for full features.", "features": []}, {"id": "official-paladin-oath-of-vengeance", "name": "Oath of Vengeance", "parentClass": "Paladin", "source": "PHB / DSC", "summary": "Oath of Vengeance (Paladin subclass). See source book for full features.", "features": []}, {"id": "official-ranger-hunter", "name": "Hunter", "parentClass": "Ranger", "source": "PHB / DSC", "summary": "Hunter (Ranger subclass). See source book for full features.", "features": []}, {"id": "official-ranger-beast-master", "name": "Beast Master", "parentClass": "Ranger", "source": "PHB / DSC", "summary": "Beast Master (Ranger subclass). See source book for full features.", "features": []}, {"id": "official-rogue-thief", "name": "Thief", "parentClass": "Rogue", "source": "PHB / DSC", "summary": "Thief (Rogue subclass). See source book for full features.", "features": []}, {"id": "official-rogue-assassin", "name": "Assassin", "parentClass": "Rogue", "source": "PHB / DSC", "summary": "Assassin (Rogue subclass). See source book for full features.", "features": []}, {"id": "official-rogue-arcane-trickster", "name": "Arcane Trickster", "parentClass": "Rogue", "source": "PHB / DSC", "summary": "Arcane Trickster (Rogue subclass). See source book for full features.", "features": []}, {"id": "official-sorcerer-draconic-bloodline", "name": "Draconic Bloodline", "parentClass": "Sorcerer", "source": "PHB / DSC", "summary": "Draconic Bloodline (Sorcerer subclass). See source book for full features.", "features": []}, {"id": "official-sorcerer-wild-magic", "name": "Wild Magic", "parentClass": "Sorcerer", "source": "PHB / DSC", "summary": "Wild Magic (Sorcerer subclass). See source book for full features.", "features": []}, {"id": "official-warlock-the-archfey", "name": "The Archfey", "parentClass": "Warlock", "source": "PHB / DSC", "summary": "The Archfey (Warlock subclass). See source book for full features.", "features": []}, {"id": "official-warlock-the-fiend", "name": "The Fiend", "parentClass": "Warlock", "source": "PHB / DSC", "summary": "The Fiend (Warlock subclass). See source book for full features.", "features": []}, {"id": "official-warlock-the-great-old-one", "name": "The Great Old One", "parentClass": "Warlock", "source": "PHB / DSC", "summary": "The Great Old One (Warlock subclass). See source book for full features.", "features": []}, {"id": "official-wizard-school-of-evocation", "name": "School of Evocation", "parentClass": "Wizard", "source": "PHB / DSC", "summary": "School of Evocation (Wizard subclass). See source book for full features.", "features": []}, {"id": "official-wizard-school-of-abjuration", "name": "School of Abjuration", "parentClass": "Wizard", "source": "PHB / DSC", "summary": "School of Abjuration (Wizard subclass). See source book for full features.", "features": []}, {"id": "official-wizard-school-of-divination", "name": "School of Divination", "parentClass": "Wizard", "source": "PHB / DSC", "summary": "School of Divination (Wizard subclass). See source book for full features.", "features": []}, {"id": "official-moon-guardian-path-of-luna", "name": "Path of Luna", "parentClass": "Moon Guardian", "source": "PHB / DSC", "summary": "Path of Luna (Moon Guardian subclass). See source book for full features.", "features": []}, {"id": "official-moon-guardian-path-of-the-eclipse", "name": "Path of the Eclipse", "parentClass": "Moon Guardian", "source": "PHB / DSC", "summary": "Path of the Eclipse (Moon Guardian subclass). See source book for full features.", "features": []}, {"id": "official-moon-guardian-path-of-the-full-moon", "name": "Path of the Full Moon", "parentClass": "Moon Guardian", "source": "PHB / DSC", "summary": "Path of the Full Moon (Moon Guardian subclass). See source book for full features.", "features": []}];
window.CUSTOM_CLASSES = [{"id": "ID_RDDT_CLASS_GLADIATOR", "name": "Gladiator", "source": "Reddit : Unearthed Arcana", "summary": "", "hitDie": "d8", "primary": "—", "saves": "—"}, {"id": "ID_RDDT_CLASS_ARCANE_ARMSMAN", "name": "Arcane Armsman", "source": "Reddit : Unearthed Arcana", "summary": "", "hitDie": "d8", "primary": "—", "saves": "—"}, {"id": "ID_RDDT_CLASS_CULTIVATOR", "name": "Cultivator", "source": "Reddit : Unearthed Arcana", "summary": "", "hitDie": "d8", "primary": "—", "saves": "—"}];
window.CUSTOM_FEATS = [{"id": "id_wiki_feat_adamantine-spirit", "name": "Adamantine Spirit", "text": "Any unarmed strikes that you make use a d6 and are counted as an adamantine bludgeoning weapon that you have proficiency with.\r\n\t\t\tAdditionally once per long rest you can use your reaction to make any critical hit against you into a normal hit.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_adept_aviator", "name": "Adept Aviator", "text": "Your Dexterity score increases by 1.\r\n\t\t\tYour flying speed increases by 10 feet.\r\n\t\t\tYou are immune to fall damage", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_all_for_one_and_one_for_all", "name": "All for One and One for All", "text": "When you are in combat you exude a confidence that empowers both yourself and your allies.\r\n\t\t\tAll allies within 30ft of you gain a +1 to all attack and damage rolls, for each ally within 5ft of you, you gain a consecutive +1 up to a maximum of +3 for attack and damage rolls.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_arcane_artillerist", "name": "Arcane Artillerist", "text": "If the spell as a range greater than self then the range is doubled.\r\n\t\t\tYour spells' area or reach is also doubled (15-foot cone becomes 30-cone, 20-foot radius becomes 40-foot radius, etc.) You can do this 2 times per short rest", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_arcane_specialist", "name": "Arcane Specialist", "text": "Your spellcasting attack modifier and save DC increases by 1\r\n\t\t\tWhen you finish a long rest you can choose a single spell, when you cast this spell it requires a spell slot of one level lower than the level you're casting it at. \rAdditionally you have +2 on the spell attack roll or induce -2 on saving throw.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_armor_master", "name": "Armor Master", "text": "Increase your Strength score by 1, to a maximum of 20.\r\n\t\t\tWhile wearing armor, you have a +1 bonus to your AC.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_battle_mage", "name": "Battle Mage", "text": "When you make a ranged spell attack, you do not suffer disadvantage on the attack roll if you are within 5 feet of a hostile creature.\r\n\t\t\tWhen you cast an instantaneous spell that requires a single spell attack roll, you can choose to take a -5 penalty to that attack roll. If you hit, you add +10 to the damage dealt by the spell, if the spell would otherwise deal damage.\r\n\t\t\tYou have advantage on Constitution saving throws that you make to maintain your concentration on a spell when you take damage.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_blind_savant", "name": "Blind Savant", "text": "Your wisdom increases by 1, to a maximum of 20\r\n\t\t\tYou gain blindsight of 60ft\r\n\t\t\tPerception checks made without sight have advantage.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_bow_master", "name": "Bow Master", "text": "Increase your dexterity by 1 to a maximum of 20\r\n\t\t\tYou get +1 to attack rolls with a bow and you can make attacks with a bow using a bonus action.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_brutal_strength", "name": "Brutal Strength", "text": "Increase your strength by 1 to a maximum of 20\r\n\t\t\tWhen dealing damage with a melee weapon add 1d4 to the damage.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_counter_striker", "name": "Counter Striker", "text": "Increase your Dexterity by 1, to a maximum of 20\r\n\t\t\tWhenever you are hit by a melee attack, as a reaction, you may immediately make a melee attack against the attacker.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_critical_combo", "name": "Critical Combo", "text": "Increase your critical range by 1 (20 becomes 19-20, 19-20 becomes 18-20)\r\n\t\t\tIf you deal a critical hit to a target you can use your bonus action to attack that target again with advantage or any other target within range without advantage.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_critical_wrath", "name": "Critical Wrath", "text": "When wielding a melee weapon you're proficient with, gain +1 to attack rolls and deal 1 extra damage die on a critical hit.\r\n\t\t\tThe critical range with the weapon is made one larger, (20 becomes 19-20, 19-20 becomes 18-20)", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_crystal_eyes", "name": "Crystal Eyes", "text": "You have advantage on saving throws against being blinded\r\n\t\t\tYou gain 60ft of darkvision", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_deadshot", "name": "Deadshot", "text": "Increase your Dexterity score by 1 to a maximum of 20.\r\n\t\t\tYou can reroll 1s on damage rolls made with ranged weapons.\r\n\t\t\tYour critical range with ranged weapons increases by 1", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_heavy_armour_master", "name": "Heavy Armour Master", "text": "Increase your strength by 1 to a maximum of 20.\r\n\t\t\tWhen wearing heavy armour you reduce all non-magical piercing, bludgeoning or slashing damage by your constitution modifier + your proficiency bonus.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_wiki_feat_lethal_duelist", "name": "Lethal Duelist", "text": "When making an attack with a melee weapon you're proficient with you can choose to impose a penalty up to -5 on the attack roll. If the attack hits add the double the penalty to the damage roll (-1 to hit gives +2 damage)\r\n\t\t\tIf you score a critical hit with a weapon you're proficient with you can take a bonus action to attack the same target again provided you don't have a shield or weapon in your off hand.", "prerequisite": "", "source": "D&D Wiki"}, {"id": "id_rddt_feat_sniper's_nest", "name": "Sniper's Nest", "text": "If you haven't moved on your turn you can spend all movement to impose advantage on your next ranged attack, this can be done 4 times per short rest\r\n\t\t\tBeing prone doesn't imposed disadvantage on ranged attacks.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_double_shot", "name": "Double Shot", "text": "Your dexterity increases by 1 to a max of 20\r\n\t\t\tOn your turn as part of a ranged attack with a non-reloading weapon you can fire a second shot with disadvantage.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_bow_bash", "name": "Bow Bash", "text": "Your dexterity increases by 1 to a max of 20\r\n\t\t\tYou can make a melee attack with a ranged weapon dealing 1d8 + {{strength:modifier}}, then as a bonus action you can make a ranged attack on them without disadvantage", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_pinpoint_accuracy", "name": "Pinpoint Accuracy", "text": "When a creature you can see makes a ranged weapon attack within your range you can use your reaction to try to shoot it out of the air, make a ranged attack against their attack roll, if yours is higher their attack misses.\r\n\t\t\tWhen you make a ranged weapon attack against an opponent you can try to disarm them, when you do they must make a strength save against your attack roll, if they fail they drop their weapon that they're holding.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_flawless_shots", "name": "Flawless Shots", "text": "When you score a critical hit with a ranged weapon you add a modifier equivalent to the maximum damage possible (for a longbow 1d8 -> +8 damage), this is not effected by any multipliers for the critical.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_far_touch", "name": "Far Touch", "text": "When you cast a spell with a range of Touch, you can increase that range to 10 ft. {{level}} times per long rest, you can increase that distance to 30ft.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_lightning_striker", "name": "Lightning Striker", "text": "When you engage in combat (one weapon or two) you can use your bonus action to make an attack with each weapon you are holding. Additionally when you take the attack action you can sheath and draw one weapon.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_magic_striker", "name": "Magic Striker", "text": "When you make a weapon attack, you can use your Spellcasting modifier instead of strength. If you cast a spell on your turn you can make a single weapon attack that deals an additional d6 per spell level (1d4 for a cantrip).", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_precise_striker", "name": "Precise Striker", "text": "When you make an attack with a finesse weapon its damage die is increased by one size (d4 becomes d6). When you strike a creature for a second time on your turn the second attack deals {{proficiency}} in damage. When you deal a critical hit one of the damage die is treated as its maximum value.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_shield_striker", "name": "Shield Striker", "text": "Increase your constitution by 1 to a maximum of 20. You can use your shield to make a shove attack against creatures within 5ft of you as a bonus action. When you make this shove it take {{strength:modifier}} in bludgeoning damage.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_bulwark", "name": "Bulwark", "text": "When a creature targets you with an attack while you are wielding a shield, you can use your reaction to impose disadvantage on the attack roll.\r\n\t\t\tWhile you are wearing heavy armor and a shield, allies within 5 feet of you gain the benefits of half cover as long as you aren't incapacitated.\r\n\t\t\tWhen a creature within 5 feet of you is targeted with an attack, and you use your reaction to grant the attack roll disadvantage, you can reduce the damage that creature takes on a hit by 1d10 + your proficiency bonus, you then take that amount of damage instead.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_cleave", "name": "Cleave", "text": "You use the momentum of one of your strikes to cut into another creature. When you reduce a creature to 0 hit points with a melee weapon attack using Strength, and there is an excess of damage remaining in relation to the creature's hit points the excess carries over to another creature of your choice within reach provided that the original attack roll would also hit it. Repeat this process carrying over the remaining damage until there is no more valid targets or the carried over damage fails to reduce a creature to 0 hit points.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_dervish", "name": "Dervish", "text": "You gain a +1 bonus to AC while you are wielding a separate melee weapon in each hand.\r\n\t\t\tYour walking speed increases by 10 feet while you are moving in between attacks provided you are wielding a separate melee weapon in each hand.\r\n\t\t\tWhen you engage in two weapon fighting, you can make the additional attack with your off-hand weapon as part of the Attack action instead of a bonus action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_iron_grip", "name": "Iron Grip", "text": "You can use the larger damage die while wielding a weapon with the versatile property as if you were wielding it with two hands.\r\n\t\t\tYou don't have disadvantage on attack using a weapon with the heavy property if your size is Small.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_mauler", "name": "Mauler", "text": "When you make a melee weapon attack using a greateaxe, greatclub, greatsword, or maul, you increase your reach by and additional 5 feet.\r\n\t\t\tWhen you hit a creature with a weapon attack using a weapon with the two-handed and/or heavy property you can use a bonus action to attempt to shove it.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_mobile_shooter", "name": "Mobile Shooter", "text": "Your movement does not provoke attacks of opportunity while you are moving in between attacks provided that you move no more than 5 feet between each attack and you are wielding a ranged weapon.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_phalanx", "name": "Phalanx", "text": "You gain a +1 bonus to AC while you are wielding a shield\r\n\t\t\tWhile you are wielding a shield, you can use an action on your turn to move up to half your speed without provoking attacks of opportunity, any creature of your size or smaller in front of you must make a Strength saving throw (DC = 8 + your proficiency bonus + your Strength modifier) or be pushed back 10 feet, and any ally within 5 feet of you who can see you and is wielding a shield can use its reaction to move up to half their speed in the same direction and force any creature in front of them to make the same saving throw.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_rampage", "name": "Rampage", "text": "When you reduce a creature to 0 hit points with a melee weapon attack or you score a critical hit with one, you can use your reaction to move up half your speed towards another creature and make a weapon attack against them as part of the same reaction. This movement does not provoke attacks of opportunity", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_skewer", "name": "Skewer", "text": "When you reduce a creature to 0 hit points with a weapon attack that dealt piercing damage, and there is an excess of damage remaining in relation to the creature's hit points the excess carries over to another creature of your choice within reach provided that it is directly behind the original target and the orginal attack roll would also hit it. Repeat this process carrying over the remaining damage until there is no more valid targets or the carried over damage fails to reduce a creature to 0 hit points.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_sniper", "name": "Sniper", "text": "Being prone does not impose disadvantage on your ranged weapon attack rolls.\r\n\t\t\tIf you have moved less than half your walking speed on your turn, you can use a bonus action to reduce your speed to 0 until the start of your next turn and become prone, if you do, you gain advantage on the next ranged weapon attack you make and you deal an additional 1d6 damage to the target on a hit.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_tactical_thrower", "name": "Tactical Thrower", "text": "When you take the attack action on your turn and make a ranged attack using a weapon with the thrown property, you can use a bonus action to make a ranged weapon attack with a weapon with the thrown property using your off-hand, this attack obeys the rules for two-weapon fighting.\r\n\t\t\tWhen you miss with a ranged attack roll using a weapon with the thrown property, you can use your reaction to cause the weapon to ricochet and go back to your hand provided that the attack wasn't at long range.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_wall_runner", "name": "Wall Runner", "text": "If you move at least 10 feet on a straight line while adjacent to a wall, you can move horizontally across it without falling.\r\n\t\t\tYou have advantage on Strength (Athletics) checks and Dexterity (Acrobatics) checks made to jump while you are moving across a wall.\r\n\t\t\tYou double your vertical jumping distance while you are moving across a wall.\r\n\t\t\tYou have advantage on the first melee weapon attack you make immediately after you stop moving across a wall.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_whirlwind_striker", "name": "Whirlwind Striker", "text": "When you take the Attack action on your turn while you engage in two-weapon fighting, you can make one additional weapon attack with your off-hand weapon as part of the same action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_wrestler", "name": "Wrestler", "text": "You have advantage on Stregth (Athletics) checks made to grapple or shove a creature.\r\n\t\t\tWhen you hit a creature with a melee weapon attack, you can use a bonus action to attempt to grapple or shove the creature.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_dueling_master", "name": "Dueling Master", "text": "On your turn, when you miss with an attack with a melee weapon against a creature, you can make one melee weapon attack against the same creature as a bonus action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_opportunist", "name": "Opportunist", "text": "When a creature within 5 feet of you makes an attack roll at disadvantage, you can use your reaction to make a melee weapon attack against that creature.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_pugilist", "name": "Pugilist", "text": "Your unarmed strike uses a d4 for damage.\r\n\t\t\tWhen you take the Attack action with an unarmed strike, you can make one unarmed strike as a bonus action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_whip_master", "name": "Whip Master", "text": "When you use a whip, its damage die changes from a d4 to a d6.\r\n\t\t\tWhen you hit a creature no more than one size larger than you with a whip on your turn, you can use a bonus action to make a special melee attack against the target. You make an attack roll contested by the target’s Strength (Athletics) check or Dexterity (Acrobatics) check. A creature can willingly lose this contest and you succeed automatically if the target is incapacitated. If you succeed, you either pull the target 5 feet toward you, or it drops one item of your choice that it’s holding.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_academic", "name": "Academic", "text": "You have dedicated yourself to a particular field of study:\r\n\t\t\tYou can roll a d6 and add the number rolled to any ability check you make with your chosen skill.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_banditry", "name": "Banditry", "text": "Your ability to exploit your opponent’s weaknesses isn’t restricted to light and ranged weaponry:\r\n\t\t\tYour sneak attack is now compatible with any melee weapon, so long as that weapon lacks the heavy property.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_barbaric_charge", "name": "Barbaric Charge", "text": "The fury of your rage allows you to move at greater speeds. You gain the following benefits:\r\n\t\t\tWhile raging, your speed increases by 10 feet.\r\n\t\t\tWhen you use your bonus action to enter a rage, you also take the Dash action as part of that same bonus action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_bard_initiate", "name": "Bard Initiate", "text": "You’ve refined your spellcasting and martial abilities. You gain the following benefits:\r\n\t\t\tYou can touch one weapon that you are proficient with and begin to perform a 1-hour ritual. This ritual can be performed during a short rest. When the ritual is complete, the weapon can be used as a spellcasting focus.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_courageous", "name": "Courageous", "text": "You are able to overcome your fear, granting you the following benefits:\r\n\t\t\tYou have advantage on saving throws made to resist the Frightened condition.\r\n\t\t\tYour movement is no longer affected by the Frightened condition.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_chameleon", "name": "Chameleon", "text": "You are capable of changing the colour and transparency of your scales to better blend in with your surroundings. So long as you aren’t wearing armour, you can become Invisible as an action. Any equipment you are wearing or carrying becomes invisible with you. The Invisibility ends if you; move, take any action, don armour, concentrate on a spell or become incapacitated.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_disenchanting", "name": "Disenchanting", "text": "Your ability to disrupted mind altering effects has improved. You gain the following benefits:\r\n\t\t\tCountercharm can now be activated as a bonus action, instead of an action.\r\n\t\t\tAny friendly creatures under the effects of Countercharm can add {{charisma:modifier}} to any saving throws they make to resist being charmed or frightened.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_deep_sea_chaperon", "name": "Deep Sea Chaperon", "text": "Your ability to control the power of the sea has improved, granting you the following benefits:\r\n\t\t\tYou can cast Water Breathing without expending a spell slot. When you cast Water Breathing using this feat, targets of the spell gain a swimming speed equal to their walking speed for the duration. Once you cast Water Breathing in this way, you must finish a long rest before you can do so again.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_druid_initiate", "name": "Druid Initiate", "text": "Nature has made a call and you have answered. You learn two cantrip of your choice from the Druid spell list, wisdom is your spellcasting ability for these spells.\r\n\t\t\tAdditionally, you can use your action to magically assume the shape of a beast that you have seen before. The beast must have a CR of 0 and lack a swimming or flying speed. The transformation lasts 10-minutes and can be ended early as a bonus action. This feat uses the same rules as Wildshape, see page 66 of the Player’s Handbook for more details.\r\n\t\t\tYou can use this feature twice, regaining all expended uses after finishing a long rest.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_elusive", "name": "Elusive", "text": "You have a knack for avoiding the consequences of your actions:\r\n\t\t\tYou and up to ten companions within 60 feet of you can travel at a normal pace while stealthing. If you choose to travel at a slow pace, you and your companions gain a +5 bonus to their stealth rolls.\r\n\t\t\tCreatures have disadvantage on any Wisdom (Perception) & Wisdom (Survival) checks they make in an attempt to track you or your companions.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_familiar_friend", "name": "Familiar Friend", "text": "You have bonded with an animal spirit, granting you the following benefits:\r\n\t\t\tYou learn the Find Familiar spell, which can cast without expending a spell slot. You must finish a long rest before you can cast it in this way again.\r\n\t\t\tWhen choosing your familiar’s form, you can choose any CR 0 beast.\r\n\t\t\tWhile you are touching your familiar, you can change its form as an action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_feather_foot", "name": "Feather Foot", "text": "You move with a soft, delicate step. You gain the following benefits:\r\n\t\t\tYou can use Dexterity, instead of Strength, to determine how far and high you can jump.\r\n\t\t\tYour footsteps no longer trigger non-magical, pressure-based traps. Examples of such traps include; pitfalls, hunting traps, pressure plates, and trip wires.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_friend_of_the_forest", "name": "Friend of the Forest", "text": "You are a friend to creatures big and small. You gain the ability to understand and speak with beasts.\r\n\t\t\tThe knowledge and awareness of many beasts is limited by their intelligence, but at minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_foreign_magic", "name": "Foreign Magic", "text": "You begin to study the magical talents of your {{foreignmagic:class}}\r\n\t\t\tYou learn 2 1st-level spells from this class. You can use either Intelligence, Wisdom, or Charisma as the spellcasting ability for these spells.\n\t\t\tYou can cast each of these spells without expending a spell slot. Once you cast either of these spells in this way, you can’t cast that spell in this way again until you finish a long rest. You can also cast these spells using a spell slot that you have.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_fountain_of_sorcery", "name": "Fountain of Sorcery", "text": "You unlock a hidden source of sorcery within yourself. You gain the following benefits:\r\n\t\t\tYou gain {{level:sorcerer:half}} additional sorcery points. These additional sorcery points can only be spent on Metamagic and cannot be converted into spell slots. You regain all spent sorcery points when you finish a long rest.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_hands_of_devotion", "name": "Hands of Devotion", "text": "Your body is a vessel for your divine power:\r\n\t\t\tYour body is considered a holy symbol and can be used as a spellcasting focus for your Paladin spells.\r\n\t\t\tYour Divine Smite feature is now compatible with unarmed strikes. This extends to your Improved Divine Smite feature at 11th level.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_hound", "name": "Hound", "text": "You have a nose like a dog. You gain the following benefits:\r\n\t\t\tYou have advantage on Wisdom (Perception) checks that rely on smell.\r\n\t\t\tYou can smell an object that has been worn or used by a creature within the last 10 days to gain a +5 bonus to Wisdom (Perception) and Wisdom (Survival) checks made to track that creature. This effect lasts until you finish a long rest.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_infusionist", "name": "Infusionist", "text": "Your ingenuity and inventiveness have improved, granting you the following benefits:", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_insomniac", "name": "Insomniac", "text": "Your many late nights have taught you how to function with less sleep. You gain the following benefits:\r\n\t\t\tYou only need 4 hours of sleep to gain the benefits of a long rest.\r\n\t\t\tYou no longer have disadvantage on ability checks when you have only a single level of exhaustion.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_mariner", "name": "Mariner", "text": "You have learned how to sail the seas, granting you the following benefits:\r\n\t\t\tYou can spend 1-minute studying the sky to determine what the weather will be for the next 24 hours.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_monk_initiate", "name": "Monk Initiate", "text": "You’ve learned the basics of unarmed martial arts:\r\n\t\t\tYou can use Dexterity instead of Strength for the attack and damage rolls of your unarmed strikes.\r\n\t\t\tYour unarmed strikes gain a d4 damage die.\r\n\t\t\tWhen you use the Attack action with an unarmed strike, you can make one unarmed strike as a bonus action.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_mountaineer", "name": "Mountaineer", "text": "No peak is beyond your reach. You gain the following benefits:\r\n\t\t\tYou can reduce any falling damage you take by {{level}}\r\n\t\t\tYou gain advantage on any Strength (Athletics) checks you make in relation to climbing.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_mystic", "name": "Mystic", "text": "You’ve learned how to better harness the power of Ki. You gain the following benefits;", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_paladin_initiate", "name": "Paladin Initiate", "text": "You learn how to empower your strikes with divine magic. You gain a pool of {{proficiency}} d8’s. When you hit a creature with a melee weapon attack, you can spend one or more of these d8 to deal extra radiant damage to the target, in addition to the weapon’s damage. Roll the dice you spend; the target takes additional radiant damage equal to the amount rolled.\r\n\t\t\tThe maximum number of d8’s you can spend on a single attack is {{proficiency:half}}. You regain all expended dice when you finish a long rest.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_pushover", "name": "Pushover", "text": "You learn how to effectively use your strength to overpower your enemies. You gain the following benefits:\r\n\t\t\tYou have advantage on Strength (Athletics) checks made to Shove a Creature.\r\n\t\t\tWhen you successfully shove a creature and decide to push them, the distance they are pushed is now equal to your strength score, rounded down to the nearest 5ft.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_recall_arcana", "name": "Recall Arcana", "text": "You can more easily recall and recite the incantation for spells you haven’t prepared. You can cast an unprepared spell of 5th level or lower from your spellbook, treating the spell as if it were prepared.\r\n\t\t\tYou can use this feat {{proficiency:half}} times, regaining all expended uses when you finish a long rest.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_resolute", "name": "Resolute", "text": "Your strength and will is unyielding. You gain the following benefits:\r\n\t\t\tWhen you use your Indomitable feature on a saving throw you aren’t proficient with, you can add your Proficiency Bonus to the rerolled saving throw.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_seismic_touch", "name": "Seismic Touch", "text": "You learn how to sense the subtle vibrations that travel through the ground. As an action, you can touch a solid surface and gain 60ft Tremorsense until the start of your next turn.\r\n\t\t\tA creature with Tremorsense can detect and pinpoint the origin of vibrations within a specific radius, provided that creature and the source of the vibrations are in contact with the same ground or substance. Tremorsense can't be used to detect flying or incorporeal creatures.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_rddt_feat_tactician", "name": "Tactician", "text": "You are always ready for battle and always have a battle plan:\r\n\t\t\tWhenever you roll initiative roll a d4. You gain a bonus to your initiative equal to the number rolled.\r\n\t\t\tAfter you roll initiative but before the first turn of combat, you can swap your initiative position with a willing creature. You can only use this feat once per combat encounter.", "prerequisite": "", "source": "Reddit : Unearthed Arcana"}, {"id": "id_phb_feat_tough", "name": "Tough", "text": "Your hit points maximum increases by double your level.", "prerequisite": "", "source": "Player’s Handbook"}];
